window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-dermatologia-der-unico"]={"block":"medcurso:medcurso-dermatologia-der-unico","label":"Medcurso · DER UNICO","count":455,"questions":[{"id":"medcurso-dermatologia-der-unico-345450","number":"345450","sourceNumber":"345450","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As infecções pelo herpes simples vírus apresentam-se como desafios, cada vez\nmaiores, para diversas áreas da medicina, por serem dotadas de várias peculiaridades.\n\nConsiderando as manifestações clínicas e estado imunológico do hospedeiro, quanto à Herpes\nrecidivante, assinale a alternativa CORRETA:","options":{"A":"A primo-infecção pode ser no olho, com vesículas e erosões na conjuntiva e córnea. Após a\nregressão, podem surgir as recidivas, que determinam ulcerações profundas, eventualmente\ncausando cegueira.","B":"É de observação mais comum em criança, podendo variar de um quadro discreto, com algumas\nlesões vésicoerosivas e subfebril, até quadros graves, com erupção vesiculosa, febre alta,\nadenopatias e comprometimento do estado geral.","C":"É de observação mais comum em adultos, surgindo as lesões em qualquer área da pele ou\nmucosa, onde ocorreu a inoculação primária.","D":"Ocorre quando a parturiente apresenta herpes genital com contaminação do neonato durante o\nparto."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-345465","number":"345465","sourceNumber":"345465","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Dermatite genética, crônica e que se apresenta com pele seca, erupções que coçam e\ncrostas, mais comumente nas dobras dos braços e da parte de trás dos joelhos, podendo estar\nassociada a rinite alérgica e com manifestação clínica variável. Trata-se de:","options":{"A":"Dermatite de contato.","B":"Dermatite atópica.","C":"Dermatite herpetiforme.","D":"Dermatite seborreica."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-345500","number":"345500","sourceNumber":"345500","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 12 meses de vida, com 10 Kg de peso, é levado para consulta por\naparecimento recente de lesões de pele. As lesões\nsão pápulas e vesículas eritematosas,\ndisseminadas, com acometimento inclusive de palmas e plantas, com escoriações nas áreas\nafetadas e prurido intenso à noite. Considerando o diagnóstico mais provável, qual das seguintes é\na melhor opção terapêutica?","options":{"A":"Ivermectina via oral dose única.","B":"Permetrina tópica.","C":"Ivermectina via oral 2 doses com intervalo de 10 a 15 dias.","D":"Albendazol dose única."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-343850","number":"343850","sourceNumber":"343850","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O eczema crônico é caracterizado pela presença de:","options":{"A":"Eritema e edema.","B":"Vesículas e exsudação.","C":"Liquenificação e prurido.","D":"Pústulas e crostas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-283277","number":"283277","sourceNumber":"283277","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo masculino, 40 anos, apresenta placa cutânea, eritêmato-infiltrada com\nbordos elevados e ovalada de 7 cm, anestésica no braço direito. Após biópsia, a análise\nhistopatológica revelou dermatite granulomatosa não caseosa, com células gigantes tipo Langhans\ne infiltrado linfo-plasmocitário perivascular e ao redor de filetes nervosos. Pesquisa de BAAR\nnegativa com teste de Mitsuda positivo. Qual diagnóstico?","options":{"A":"Hanseníase indeterminada.","B":"Hanseníase Virchowiana.","C":"Hanseníase atípica.","D":"Hanseníase tuberculóide."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-283304","number":"283304","sourceNumber":"283304","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 4 meses é levado pela mãe em consulta pediátrica, devido apresentar\n\"carroços no corpo\" que coçam muito\nprincipalmente à noite, há 10 dias; ela acrescenta que os\nirmãos maiores estão com o mesmo quadro. No exame físico, observa-se pápulas eritematosas em\ntronco, punhos, palmas das mãos, virilhas, tornozelos, plantas dos pés e nos espaços interdigitais,\nalém de nódulos em palmas e plantas dos pés, além de lesões serpinginosas em tronco, algumas\ncom formato de J. Qual o tratamento de PRIMEIRA escolha para esse lactente?","options":{"A":"Ivermectina oral.","B":"Pasta de enxofre a 10%.","C":"Permetrina loção a 5%.","D":"Sabonete de enxofre."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-281153","number":"281153","sourceNumber":"281153","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um lactente feminino de 3 meses apresenta-se com lesão em região lateral da face\nesquerda, inicialmente era uma lesão papular\neritematosa e agora como uma tumoração de cor\nvermelho vivo, bem delimitada, não dolorosa, de crescimento rápido no último mês. Assinale qual a\nmelhor opção terapêutica para este paciente","options":{"A":"Manejar de forma expectante, orientado a evolução natural e com reavaliações frequentes.","B":"Pelo risco de ulceração e infecção secundária pela localização deve-se iniciar tratamento tópico\ncom corticosteróides.","C":"Pelo crescimento rápido recente deve-se iniciar tratamento com corticosteróides sistêmicos pelo\nrisco de comprometimento funcional.","D":"Pelo crescimento rápido recente e pela localização e risco de alteração funcional a melhor\nterapêutica a se instituir é o uso de betabloqueador sistêmico.","E":"Por ainda estar crescendo numa fase que já se esperaria sua regressão o melhor resultado\nneste momento se conseguiria através do tratamento\ncirúrgico."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-283359","number":"283359","sourceNumber":"283359","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Amanda de 20 anos de idade, leva seu filho de 1 mês de vida para consulta no módulo\nde saúde próximo a sua casa. A criança em\namamentação exclusiva, na última semana está muito\nirritada, chora à noite toda, a mãe notou que surgiram lesões avermelhadas no corpo da criança. O\nmédico da UBS solicitou que a mãe retirasse toda a roupa da criança para que pudesse\n\nexaminá-la, identificando pequenas pápulas eritematosas lineares, medindo 3 a 8 mm em média na\nregião periumbilical, no pênis, no escroto, e nas regiões palmo-plantares. O diagnóstico e a conduta\nsão:","options":{"A":"Doença pé mão boca/prescreve analgésico oral e orienta a mãe.","B":"Prurigo estrófulo/cortiesteróides tópico.","C":"Dermatite de contato eczematizada/antibiótico tópico.","D":"Escabiose/enxofre a 5-10% em creme e tratar a mãe."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-247144","number":"247144","sourceNumber":"247144","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente com história de mancha hipercrômica ovalada que surge após o uso de\nanalgésicos, desaparece gradualmente após a\nsuspensão da medicação e recidiva no mesmo local\napós a suspensão da medicação e recidiva no mesmo local após nova exposição à droga. Trata-se\nprovavelmente de:","options":{"A":"Eritema nodoso.","B":"Exantema agudo.","C":"Urticária crônica.","D":"Eritema fixo.","E":"Eritema multiforme."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-247171","number":"247171","sourceNumber":"247171","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo feminino, 63 anos, obesa e com baixa adesão ao tratamento de\ndiabetes tipo 2, apresenta queixa de prurido\nem axilas, região perineal e região inframamária. Ao\nexame, observa-se rash avermelhado com discreta secreção esbranquiçada nas áreas relatadas.\nAssinale a alternativa CORRETA, que apresenta, respectivamente, o diagnóstico mais provável e o\ntratamento mais apropriado para a condição.","options":{"A":"Tinea corporis - Antifúngico via oral.","B":"Acantose nigricans - Melhor controle glicêmico.","C":"Intertrigo - Antifúngico tópico.","D":"Demopatia diabética - Tratamento não necessário.","E":"Bullosis diabeticorum - Melhor controle glicêmico."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-217705","number":"217705","sourceNumber":"217705","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A tinea capitis é a infecção fúngica mais comum na infância, acomete o couro cabeludo\ne caracteriza-se por alopecia descamativa\ndistribuída em placas bem delimitadas e com cabelos\nquebrados logo após a emergência do folículo piloso. Sobre a tinea capitis está CORRETO afirmar:","options":{"A":"No Brasil o fungo mais envolvido nos casos de tinea de couro cabeludo e tinea de corpo em\ncrianças é o Malassezia furfur.","B":"Querion é uma apresentação inflamatória da tinea capitis, com placas infiltradas, alopecia,\npústulas e frequentemente drenagem de secreção purulenta.","C":"O tratamento da tinea capitis é tópico com xampu de sulfeto de selênio 2,5% ou cetoconazol a\n2%.","D":"A confirmação diagnóstica é importante para que se estabeleça o tratamento, sendo o\npadrão-ouro a presença de fungos no exame microscópico direto."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-217724","number":"217724","sourceNumber":"217724","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A pele é maior órgão do corpo humano, correspondendo a 15% do peso corporal. É\ncomposta por três camadas conectadas estrutural e funcionalmente. Existem mais de duas mil\nlesões que afetam a pele, as quais podem ser exclusivamente cutâneas ou fazer parte de doenças\nsistêmicas. Com base em seus conhecimentos sobre as lesões de pele, todas as afirmativas são\ncorretas, EXCETO:","options":{"A":"As lesões elementares podem ser primárias ou secundárias.","B":"A distribuição das lesões pode ter grande valor na diferenciação entre dois diagnósticos.","C":"As lesões secundárias surgem sobre uma lesão primária ou podem representar sua evolução.","D":"Quando a dermatose compromete mais de 90% da superfície cutânea, é chamada de universal."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-183184","number":"183184","sourceNumber":"183184","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Certas condições clínicas podem simular a anafilaxia em crianças, ficando difícil fazer o\ndiagnóstico diferencial. É preciso boa anamnese observando a ordem e o tempo que precedem os\nsintomas. Essas situações clínicas que confundem são listadas abaixo, EXCETO:","options":{"A":"Disfunção de cordas vocais levando à desconforto respiratório.","B":"Reação vasovagal levando à hipotensão e/ou síncope.","C":"Quadro renal como síndrome nefrótica.","D":"Angioedema hereditário.","E":"Exacerbação da asma levando a desconforto respiratório."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-182660","number":"182660","sourceNumber":"182660","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pré-escolar com história de pápulas eritematosas, vesículas e pústulas disseminadas\nacometendo palmas das mãos e plantas dos pés, sem sintomas sistêmicos. A mãe tem lesões\nsemelhantes na região inframamária e antebraços, com prurido principalmente noturno, Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Miliária.","B":"Varicela.","C":"Dermatite atópica.","D":"Escabiose."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-182676","number":"182676","sourceNumber":"182676","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a escabiose, assinale V (verdadeiro) ou F (falso). ( ) No lactente, a medicação é\naplicada em todo o corpo, excluindo a face.; ( ) A ivermectina por via oral é indicada nos pacientes\ncom dermatite atópica grave.; ( ) A ausência de prurido noturno afasta a possibilidade de\nescabiose.; ( ) Os familiares de uma pessoa com escabiose que não possuam lesões não\nnecessitam ser tratados. A sequência CORRETA é:","options":{"A":"V, F, F, V","B":"F, V, F, F","C":"V, V, F, F","D":"V, F, V, V"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-182680","number":"182680","sourceNumber":"182680","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Para o tratamento da pediculose, é importante conhecer ciclo de vida do Pediculus\ncapitis e sua forma de contágio. Sobre esse\ntema, assinale a alternativa CORRETA:","options":{"A":"As lêndeas eclodem em 7 a 10 dias, e esse dado é importante para saber o intervalo de uso da\npermetrina.","B":"A transmissão do Pediculus capitis não ocorre por meio de bonés, pois o agente não sobrevive\nlonge do ser humano.","C":"As lêndeas podem ser facilmente removidas dos fios de cabelo com água e permetrina.","D":"Para remover as lêndeas, a permetrina deve ser usada durante 10 dias, que é o tempo de\neclosão das lêndeas em ninfas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-108650","number":"108650","sourceNumber":"108650","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual a manifestação cutânea paraneoplásica está mais associada ao câncer gástrico?","options":{"A":"Acantose nigricans.","B":"Prurido.","C":"Pênfigo.","D":"Síndrome de Bazex."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-50083","number":"50083","sourceNumber":"50083","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual é a patologia dermatológica mais provável para uma criança com 10 anos de\nidade que é levada ao ambulatório de pediatria por apresentar lesões cutâneas hipocrômicas e\nhipercrômicas em região de face e tronco que, quando atritadas, apresentam descamação\nfurfurácea?","options":{"A":"Dermatite seborreica;","B":"Ptiríase versicolor;","C":"Tínea corporis;","D":"Hanseníase."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-50035","number":"50035","sourceNumber":"50035","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 2 anos vem em consulta de ambulatório de Pediatria acompanhada por sua\nmãe queixando-se de coceira no pé direito. Ao\nexame, percebe-se lesão de aproximadamente 4 cm\nde característica eritematopapulosa com algumas vesículas de trajeto serpiginoso com escoriações.\nMãe refere contato esporádico com cachorro. Qual a principal hipótese diagnóstica e tratamento?","options":{"A":"Tinea pedis - Cetoconazol tópico.","B":"Escabiose - Permetrina tópica.","C":"Larva migrans cutânea - Tiabendazol tópico.","D":"Eczema de contato - Corticoide não fluorado tópico."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-50039","number":"50039","sourceNumber":"50039","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 7 meses apresenta lesões vesiculares com base eritematosa em palato\nduro, lábios e mucosa jugal que não\nultrapassam os pilares anteriores, associadas à febre baixa,\nanorexia e linfadenopatia cervical bilateral. Qual o dignóstico e seu agente etiológico?","options":{"A":"Herpangina - Coxsackievírus;","B":"Gengivoestomatite herpética - Herpes simples;","C":"Monilíase oral - Candida albicans;","D":"Síndrome mão-boca-pé- Coxsackievirus;"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-50043","number":"50043","sourceNumber":"50043","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, masculino, diabético, 52 anos, em uso de hipoglicemiante oral, refere que há\n3 dias iniciou quadro de prurido em bolsa\nescrotal, evoluindo com dor local e hiperemia. Ao exame\nfísico apresenta bolsa escrotal edemaciada com hiperemia, e área de necrose de pele e crepitação\nque se estendem até a região perineal. O diagnóstico mais provável é:","options":{"A":"Gangrena de Fournier.","B":"Epididimite aguda.","C":"Torção testicular com necrose.","D":"Furunculose necrótica."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-37084","number":"37084","sourceNumber":"37084","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O eczema crônico é caracterizado pela presença de:","options":{"A":"Eritema e edema","B":"Vesículas e exsudação","C":"Liquenificação e prurido","D":"Pústulas e crostas","E":"Bolhas e eritema"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-37063","number":"37063","sourceNumber":"37063","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente masculino, diabético, 52 anos, em uso de hipoglicemiante oral, refere que há 3\ndias iniciou quadro de prurido em bolsa escrotal, evoluindo com dor local e hiperemia. Ao exame\nfísico apresenta bolsa escrotal edemaciada com hiperemia e áreas de necrose de pele e crepitação\nque se estendem até a região perineal. O diagnóstico mais provável?","options":{"A":"Gangrena de Fournier.","B":"Epididimite aguda.","C":"Torção testicular com necrose.","D":"Furunculose necrótica.","E":"Síndrome de Élan."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-314205","number":"314205","sourceNumber":"314205","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em uma criança com Pediculose, a presença de exsudato purulento é indicativa de:","options":{"A":"Glomerulonefrite aguda.","B":"Hiperemia sem sinais flogísticos.","C":"Evolução com infecção bacteriana.","D":"Eritema inflamatório."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-278607","number":"278607","sourceNumber":"278607","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Os principais agentes relacionados à anafilaxia são medicamentos, veneno de insetos e\nalimentos, sendo correto que:","options":{"A":"A anafilaxia não tem muitas apresentações clínicas, mas o comprometimento respiratório e o\ncolapso cardiovascular nunca podem causar preocupação, devido à baixa mortalidade.","B":"A anafilaxia tem muitas apresentações clínicas, mas o comprometimento respiratório e o colapso\ncardiovascular podem causar a maior preocupação, devido inexistente mortalidade.","C":"A anafilaxia tem muitas apresentações clínicas, mas o comprometimento respiratório e o colapso\ncardiovascular podem causar a maior preocupação, devido à alta mortalidade.","D":"A anafilaxia tem muitas apresentações clínicas, mas o comprometimento respiratório e não o\ncolapso cardiovascular podem causar a maior preocupação, devido à alta mortalidade."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-275972","number":"275972","sourceNumber":"275972","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação as úlceras cutâneas, cite a afirmativa CORRETA dentre as opções abaixo\nrelacionadas:","options":{"A":"Podem ser de origem venosa, mas não arteriais.","B":"As úlceras cutâneas não necessitam ser biopsiadas.","C":"As úlceras causadas por diabetes Mellitus, alcoólismo e hanseníase são consideradas úlceras\nneurotróficas.","D":"As úlceras de decúbito não são consideradas úlceras de pressão.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-280412","number":"280412","sourceNumber":"280412","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na tinea pedis a recidiva é frequente caso não seja realizada a orientação correta das\nformas de contagio. Sobre o tema assinale a alternativa correta.","options":{"A":"Melhorar a hidratação da pele com cremes hidratantes diários permite restaurar a barreira\ncutânea e evitar reinfecção.","B":"Restringir o contato com animais é fundamental para evitar a possibilidade de reinfecção.","C":"Minimizar o uso de calcados fechados e utilizar meias de algodão permitem evitar recidiva.","D":"Utilizar chinelos de borracha nos vestiários e tratar os animais domésticos permitem evitar\nreinfecção."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-278623","number":"278623","sourceNumber":"278623","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considere a Síndrome de Stevens Johnson (SSJ) e a Necrólise Epidérmica Tóxica\n(NET), assinale a alternativa correta.","options":{"A":"Fármacos classicamente relacionados a reações de hipersensibilidade tipo I apresentam algum\nrisco de induzir reações de hipersensibilidade tipo IV, potencialmente fatais.","B":"O comprometimento da pele superior a 30% da sua extensão define SSJ.","C":"Os sintomas sistêmicos associados à SSj e `NET incluem febre, redução de enzimas hepáticas,\nmanifestações intestinais e pulmonares, além de elevação dos níveis de linfócitos.","D":"Os antibióticos e AINEs estão entre os fármacos de maior risco apenas para SSJ."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-278624","number":"278624","sourceNumber":"278624","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa incorreta em relação à Urticária e Angioedema.","options":{"A":"Os fármacos são mais propensos a produzir urticária aguda, angioedema e anafilaxia quando\nadministrados por via parenteral","B":"As erupções urticariformes põem ser acompanhadas por angioedema, que é mais comum em\ntorno dos olhos, lábios e membranas mucosas.","C":"Para o tratamento das reações agudas de urticária, são recomendados anti-histamínicos de\nprimeira geração, como loratadina e cetirizina.","D":"As lesões urticariformes devem durar menos de 48 horas, mas novas lesões ainda podem surgir."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-278632","number":"278632","sourceNumber":"278632","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa correta sobre as Farmacodermias.","options":{"A":"As resposta cutâneas adversas a medicamentos surgem apenas a partir de reações mediadas\nimunologicamente.","B":"Os esteroides sistêmicos causam uma variedade de alterações cutâneas, como erupções\nacneiformes.","C":"Na síndrome de Stevens Johnson, observa-se acometimento da camada mais superficial da\nepiderme, caracterizado pela presença e lesões bolhosas e sinal de Nikolsky positivo.","D":"O acometimento linfonodal é raro em pacientes com DRESS."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252885","number":"252885","sourceNumber":"252885","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 54 anos de idade, dá entrada na UPA por queixas de dor em região lombar à\ndireita, há 2 dias. É portadora de hipertensão arterial sistêmica, em uso de losartana, e psoríase,\nem uso de ciclosporina. Não possui outras morbidades. Ao exame físico, apresenta-se em bom\nestado geral, com ausculta cardiorrespiratória e exame abdominal sem alterações. Giordano\nnegativo. Presença de lesões vesiculares dispostas linearmente em região lombar à direita,\nobedecendo a linha mediana. Diante do quadro apresentado, indique a conduta terapêutica mais\nadequada no momento.","options":{"A":"Suspensão temporária da ciclosporina e conduta expectante em relação às lesões de pele\natuais.","B":"Suspensão temporária da ciclosporina e introdução de valaciclovir.","C":"Manutenção da ciclosporina e introdução de ganciclovir.","D":"Manutenção da ciclosporina e introdução de metilprednisolona."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252886","number":"252886","sourceNumber":"252886","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 54 anos de idade, dá entrada na UPA por queixas de dor em região lombar à\ndireita, há 2 dias. É portadora de hipertensão arterial sistêmica, em uso de losartana, e psoríase,\nem uso de ciclosporina. Não possui outras morbidades. Ao exame físico, apresenta-se em bom\nestado geral, com ausculta cardiorrespiratória e exame abdominal sem alterações. Giordano\nnegativo. Presença de lesões vesiculares dispostas linearmente em região lombar à direita,\nobedecendo a linha mediana. Identifique as complicações mais frequentemente associadas ao\nquadro clínico atual da paciente.","options":{"A":"Paralisia de Bell e nevralgia.","B":"Nevralgia e infecção bacteriana.","C":"Infecção bacteriana e trombocitopenia.","D":"Trombocitopenia e paralisia de Bell."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252887","number":"252887","sourceNumber":"252887","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 54 anos de idade, dá entrada na UPA por queixas de dor em região lombar à\ndireita, há 2 dias. É portadora de hipertensão arterial sistêmica, em uso de losartana, e psoríase,\nem uso de ciclosporina. Não possui outras morbidades. Ao exame físico, apresenta-se em bom\nestado geral, com ausculta cardiorrespiratória e exame abdominal sem alterações. Giordano\nnegativo. Presença de lesões vesiculares dispostas linearmente em região lombar à direita,\nobedecendo a linha mediana. Indique a orientação mais adequada em relação à precaução de\ntransmissão nesse caso.","options":{"A":"É necessária apenas a precaução de contato, visto que o contágio se dá através das lesões de\npele na doença localizada.","B":"É necessário o uso de máscara do tipo N-95 pelos contactantes porque, apesar de doença\nlocalizada, a paciente está imunossuprimida.","C":"É necessária a precaução de contato, associada à utilização de máscara cirúrgica pelos\ncontactantes, devido ao risco de transmissão por gotículas.","D":"É necessária apenas a utilização de máscara cirúrgica pela paciente, já que a transmissão é\nmenor por pacientes imunossuprimidos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-231362","number":"231362","sourceNumber":"231362","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre os cânceres de pele mais frequentes, assinale a incorreta:","options":{"A":"Melanoma tem seu prognóstico relacionado ao índice de Breslow.","B":"Carcinoma basocelular, é o tipo de câncer mais frequente dentre todos os cânceres.","C":"Carcinoma basocelular é o tipo de câncer de pele menos comum.","D":"Carcinoma espinocelular é o tipo de câncer derivado da linhagem dos queratinocitos\nsuprabasais.","E":"Melanoma acomete indivíduos de qualquer fototipo."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-215204","number":"215204","sourceNumber":"215204","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A Leishmaniose Tegumentar Americana ou Úlcera de Bauru, nariz de tapir ou botão do\nOriente são infecções por leishmanias que causam a leishmaniose. Os vetores da LTA são insetos\ndenominados flebotomíneos, pertencentes à ordem Diptera, família Psychodidae, subfamília\nPhlebotominae, gênero Lutzomyia, conhecidos popularmente como mosquito palha, tatuquira,\nbirigui, entre outros, dependendo da localização geográfica, sendo INADEQUADO que:","options":{"A":"Infecções por leishmanias que causam a Leishmaniose Tegumentar Americana (LTA) foram\ndescritas em várias espécies de animais silvestres (roedores, marsupiais, edentados e canídeos\nsilvestres), sinantrópicos (roedores) e domésticos (canídeos, felídeos e equídeos).","B":"Doença infecciosa, não contagiosa, causada por protozoário, de transmissão vetorial, que\nacomete pele poupando as mucosas.","C":"Com relação aos animais domésticos, seu papel na manutenção do parasito no meio ambiente\nainda não foi esclarecido.","D":"Picada de fêmeas de ?ebotomíneos? infectadas. Não há transmissão de pessoa a pessoa."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-215239","number":"215239","sourceNumber":"215239","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Para fins de encerramento do caso de Leishmaniose Tegumentar Americana (LTA) no\nSistema de Informação de Agravos de Notificação (Sinan), não é necessário aguardar o término do\nacompanhamento. Sendo INADEQUADA, apenas, uma das condutas abaixo descrita. Marque-a.","options":{"A":"O critério de cura é clínico, sendo indicado o acompanhamento regular por 12 meses.","B":"Os critérios de cura para pacientes acometidos pela forma cutânea são definidos pela\nepitelização das lesões ulceradas, com\nregressão total da infiltração e do eritema, até 3 meses\napós a conclusão do esquema terapêutico.","C":"Nos casos em que não se cumpriram os critérios supracitados, sugere-se o prolongamento da\nobservação até se completarem 6 meses.","D":"O critério de cura para os acometidos pela forma mucosa é definido pela regressão de todos os\nsinais e comprovado pelo exame otorrinolaringológico, até 2 meses após a conclusão do esquema\nterapêutico."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-216324","number":"216324","sourceNumber":"216324","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O critério de cura para Leishmaniose Tegumentar Americana é clínico, sendo indicado\no acompanhamento regular por 12 meses. Sendo assim, o\nseguinte item se mostra CORRETO:","options":{"A":"Os critérios de cura para pacientes acometidos pela forma cutânea são definidos pela\nepitelização das lesões ulceradas, com\nregressão total da infiltração e do eritema, até 3 semanas\napós a conclusão do esquema terapêutico.","B":"Os critérios de cura para pacientes acometidos pela forma cutânea são definidos pela\ndesepitelização das lesões ulceradas, com\nregressão total da infiltração e do eritema, até 3 meses\napós a conclusão do esquema terapêutico.","C":"Os critérios de cura para pacientes acometidos pela forma cutânea são definidos pela\nepitelização das lesões ulceradas, com\nregressão total da infiltração e do eritema, até 3 meses\napós a conclusão do esquema terapêutico.","D":"Os critérios de cura para pacientes acometidos pela forma cutânea são definidos pela\nepitelização das lesões ulceradas, mesmos sem\na regressão total da infiltração e do eritema, até 3\nmeses após a conclusão do esquema terapêutico."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-215275","number":"215275","sourceNumber":"215275","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A Leishmaniose Tegumentar Americana (LTA) pode modificar a progressão da doença\npelo HIV e a imunodepressão causada por esse vírus facilita a progressão da LTA. As propostas e\nações em pacientes coinfectados Leishmania-HIV no Brasil estão descritas abaixo, indique o item\nINCORRETO.","options":{"A":"Não há um perfil clínico definido associado à coinfecção em pacientes portadores de HIV.","B":"Achados não usuais podem ser observados nos pacientes coinfectados, como, por exemplo, o\nencontro de Leishmania spp. em pele íntegra, e sobrepondo lesão de sarcoma de Kaposi ou em\nlesões de Herpes simplex e Herpes-zóster.","C":"Pode ocorrer acometimento do trato gastrointestinal e do trato respiratório para a coinfecção\nLeishmania-HIV.","D":"Recomenda-se oferecer a sorologia para HIV para todos os pacientes com LTA, dependendo da\nidade. Ressalta-se a importância de obter o resultado da sorologia para HIV o mais rapidamente\npossível, para orientar a conduta clínica específica."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-216299","number":"216299","sourceNumber":"216299","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Nas últimas décadas, a Leishmaniose Tegumentar Americana - LTA apresentou\nmudanças no seu comportamento. Inicialmente\nconsiderada zoonose de animais silvestres, que\nacometia ocasionalmente pessoas em contato, começou a ocorrer em zonas rurais já praticamente\ndesmatadas e em regiões periurbanas. Sobre isso, está CORRETO que:","options":{"A":"Observa-se a coexistência pela manutenção de casos oriundos dos focos antigos ou de áreas\npróximas a eles, e pelo aparecimento de surtos associados a fatores decorrentes do surgimento de\natividades econômicas, como garimpos, expansão de fronteiras agrícolas e extrativismo, em\ncondições ambientais altamente desfavoráveis à transmissão da doença.","B":"Observa-se a coexistência pela manutenção de casos oriundos dos focos antigos ou de áreas\npróximas a eles, e pelo desaparecimento de surtos associados a fatores decorrentes do surgimento\nde atividades econômicas, como garimpos, expansão de fronteiras agrícolas e extrativismo, em\ncondições ambientais altamente favoráveis à transmissão da doença.","C":"Observa-se a coexistência pela manutenção de casos oriundos dos focos antigos ou de áreas\npróximas a eles, e pelo aparecimento de surtos associados a fatores decorrentes do surgimento de\natividades econômicas, como garimpos, expansão de fronteiras agrícolas e extrativismo, mesmo\nsem condições ambientais favoráveis à transmissão da doença.","D":"Observa-se a coexistência pela manutenção de casos oriundos dos focos antigos ou de áreas\npróximas a eles, e pelo aparecimento de surtos associados a fatores decorrentes do surgimento de\natividades econômicas, como garimpos, expansão de fronteiras agrícolas e extrativismo, em\ncondições ambientais altamente favoráveis à transmissão da doença."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-201796","number":"201796","sourceNumber":"201796","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre a hanseníase.","options":{"A":"A hanseníase é moléstia causada pelo mycobacterium leprae e provoca lesões cutâneas\ncaracterizadas por alterações de sensibilidade.","B":"O eritema nodoso hansênico é característico da reação hansênica tipo 2.","C":"Nas formas tuberculóides da hanseníase, a baciloscopia nas lesões é positiva.","D":"Na forma virchoviana, pode ocorrer alopecia de cílios e supercílios, além de espessamento dos\npavilhões auriculares.","E":"Na reação hansênica tipo 1, as lesões existentes se tornam mais eritematosas e edematosas,\nbem como podem surgir novas lesões agudas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212190","number":"212190","sourceNumber":"212190","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A acne pode se manifestar, frequentemente, como dermatose ocupacional,\ndenominada elaioconiose, em trabalhadores que exercem suas funções expostos a","options":{"A":"derivados de bergamota.","B":"óleos combustíveis.","C":"borracha.","D":"corantes.","E":"cromo."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212145","number":"212145","sourceNumber":"212145","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Jéssica, 11 anos, é levada à consulta com Pediatra devido ao surgimento de lesões\npapulares umbilicadas, de tamanhos variados (3\nmm a 1 cm de diâmetro), em abdome, há cerca de\n3 semanas. Sua genitora afirma que inicialmente eram poucas, que vem aumentando seu número e\nque são assintomáticas. Qual a hipótese diagnóstica mais provável e qual a melhor conduta a ser\ntomada para Jéssica?","options":{"A":"Prurigo estrófulo, devendo ser utilizado corticoide tópico.","B":"Nódulo escabiótico, devendo ser utilizado anti-histamínico.","C":"Molusco contagioso, devendo ser realizada curetagem das lesões.","D":"Verruga filiforme, devendo ser utilizada solução à base de ácidos salicílico e lático.","E":"Condiloma acuminado, devendo ser utilizada solução à base de ácidos salicílico e lático."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-180114","number":"180114","sourceNumber":"180114","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa incorreta em relação às micoses superficiais.","options":{"A":"A piedra branca é provocado por leveduras do\ngênero Trichosporon sp.","B":"A tinha nigra acomete principalmente a camada\ncórnea das regiões palmoplantares.","C":"A piedra preta é caracterizada por nódulos firmes, escuros, aderidos ao pelo.","D":"A pitiriase vesicolor caracteriza-se por lesões\n\nmaculares, descamativas, de cor variável, do branco ao acastanhado.","E":"A piedra branca caracteriza-se por nódulos de\nconsistência firme, aderidos ao pelo."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-181377","number":"181377","sourceNumber":"181377","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao uso de corticoides como a hidrocortisona no tratamento da reação\nanafilática ao látex, qual a alternativa correta?","options":{"A":"Não está indicado em nenhuma fase do tratamento.","B":"Está indicado como tratamento secundário, apenas nos casos limitados à reação cutânea.","C":"Está indicado como tratamento secundário e visa prevenir a ocorrência de reação bifásica.","D":"Está indicado como tratamento primário e visa prevenir a degranulação de mastócitos e\nbasófilos.","E":"Está indicado como tratamento secundário e visa minimizar os efeitos da histamina sob os\nreceptores simpáticos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-180124","number":"180124","sourceNumber":"180124","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa incorreta sobre a Hanseníase.","options":{"A":"A Hanseníase é moléstia causada pelo\nmycobacterium leprae e provoca lesões cutâneas\ncaracterizadas por alterações de sensibilidade.","B":"O eritema nodoso hansênico é característico da\nreação hansênica tipo 2.","C":"Nas formas tuberculóides da Hanseníase, a\nbaciloscopia nas lesões é positiva.","D":"Na forma virchoviana, pode ocorrer alopecia de cílios e supercílios, além de espessamento dos\npavilhões\n\nauriculares.","E":"Na reação hansênica tipo 1, as lesões existentes se tornam mais eritematosas e edematosas,\nbem como poderm surgir novas lesões agudas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-187848","number":"187848","sourceNumber":"187848","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação aos tumores de pele assinale alternativa ERRADA:","options":{"A":"As metástases linfonodais dos carcinomas de células escamosas são mais precoces e mais\nfrequentes do que as do carcinoma basocelular","B":"Ceratose actínica é precursora principalmente de carcinoma basocelular, mas pode\neventualmente ocasionar melanoma e carcinoma de células escamosas","C":"Nódulos peroláceos nas bordas das lesões são típicos de carcinoma basocelular","D":"Pacientes submetidos a transplante de órgãos têm risco maior de desenvolverem carcinoma de\ncélulas escamosas"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-180131","number":"180131","sourceNumber":"180131","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"O mixedema pré-tibial caracteriza-se por placas firmes, coloração amarelada, prefencialmente\nna\n\nface anterior das pernas, podendo estar associado à Doença de Graves.","B":"Na acrodermatite enteropática ocorre dermatite de\n\nlocalização acral, alopecia e diarreia, provocada por deficiência de cobre.","C":"Xantomas são lesões cutâneas deocrrentes do depósito de lípidios na pele, mesmo que os\nniveis\n\nsanguineos estejam normais.","D":"A principal manifestação cutânea das porfirias é a\nfotossensibilidade.","E":"Na amiloidose cutânea primária macular, ocorre predileção das lesões pela região\ninterescapular."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-181410","number":"181410","sourceNumber":"181410","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ágatha, 10 meses, vem apresentando, há 05 meses, placas eritematosas e\npruriginosas, principalmente na face, exceto nariz e\nboca; no tronco e na região extensora dos\nmembros, exceto a região coberta pelas fraldas, com exacerbações e remissões recorrentes. Qual\na principal hipótese diagnóstica?","options":{"A":"Escabiose.","B":"Prurigo estrófulo.","C":"Dermatite atópica.","D":"Hiperceratose epidermolítica.","E":"Eritrodermia ictiosiforme congênita."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-152627","number":"152627","sourceNumber":"152627","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o melanoma, qual é o subtipo mais frequente e qual a classificação que está\ndiretamente relacionada ao prognóstico do paciente, respectivamente?","options":{"A":"Nodular e Clark.","B":"Extensivo superficial e Clark.","C":"Extensivo superficial e Breslow.","D":"Lentiginoso acral e Clark.","E":"Nodular e Breslow."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-152634","number":"152634","sourceNumber":"152634","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a hanseníase, sabe-se que esta pode causar alteração de sensibilidade, que\nsempre deve ser pesquisada no exame físico.\nQual a sequência de alteração de sensibilidade em\nordem, a partir daquela que altera primeiro até a última?","options":{"A":"Dolorosa, tátil, térmica.","B":"Térmica, dolorosa, tátil.","C":"Tátil, térmica, dolorosa.","D":"Dolorosa, térmica, tátil.","E":"Térmica, tátil, dolorosa."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-158750","number":"158750","sourceNumber":"158750","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Dadas as afirmativas quanto ao diagnóstico da dermatite das fraldas, I. Precisa ser\nrealizado diagnóstico diferencial com infecções\npor cândida, dermatite seborreica e histiocitose das\ncélulas de Langerhans. II. Na forma moderada, há eritema intenso e pápulas e acomete área em\nformato de W na região das fraldas, sem eritema nas pregas. III. Na forma grave, há eritema\nintenso, pápula, vesículas, áreas de exulceração e descamação e as pregas estão poupadas.\n\nVerifica-se que está(ão) correta(s)","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-158785","number":"158785","sourceNumber":"158785","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Jéssica, três meses de vida, foi levada para avaliação pediátrica devido ao surgimento\nde lesões com intenso eritema, pápulas e\nvesículas satélites e áreas de exulceração e descamação\nem região perineal. Não foram notadas lesões na cavidade oral nem outras anormalidades no\nexame físico. Qual a melhor conduta nesse caso?","options":{"A":"Realizar biópsia para avaliação da possibilidade de Histiocitose das células de Langerhans.","B":"Trocar as fraldas com maior frequência que a habitual, limpar\nsuavemente e iniciar o uso de betametasona creme.","C":"Trocar as fraldas com maior frequência que a habitual, limpar\nsuavemente, expor a pele ao ar e aplicar cremes de barreira.","D":"Trocar as fraldas com maior frequência que a habitual, limpar\nsuavemente e iniciar o uso de nistatina ou miconazol creme.","E":"Trocar as fraldas com maior frequência que a habitual, limpar suavemente e iniciar o uso de\nfluconazol solução oral, como primeira escolha."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-158803","number":"158803","sourceNumber":"158803","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Karen, quinze meses de vida, começou a apresentar lesões papulovesiculares\n(seropápula de Tomazoli) em regiões\nextensoras dos braços e pernas há cerca de quatro dias,\ntendo recebido orientação para uso de betametasona a 0,1%, por cinco dias. Há doze horas, surgiu\nsecreção purulenta, localizada no braço direito, sem distermia. Qual a hipótese diagnóstica e a\nmelhor conduta para o caso?","options":{"A":"Trata-se de dermatite atópica, devendo ser mantido corticoide e iniciar antibiótico tópico com\nácido fusídico.","B":"Trata-se de quadro de prurigo estrófulo com infecção secundária, devendo ser utilizado\nantibiótico sistêmico, como cefalexina, por sete dias.","C":"Trata-se de quadro de prurigo estrófulo com infecção secundária, devendo ser utilizado\nantibiótico tópico, como mupirocina, por sete dias.","D":"Trata-se de quadro de urticária papular sem infecção secundária, devendo ser rompidas as\nlesões e não ser utilizado antibiótico no momento.","E":"Trata-se de quadro de urticária papular com infecção secundária, devendo ser rompidas as\nlesões e não ser utilizado antibiótico no momento."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-158812","number":"158812","sourceNumber":"158812","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Laura, sete meses de vida, foi levada à consulta com pediatra, por apresentar lesões\npapulares, em grupos de três, com disposição linear no tronco, próxima ao elástico da roupa. Qual\no diagnóstico mais provável e a melhor conduta?","options":{"A":"Trata-se de prurigo estrófulo, devido a agente voador, como mosquitos ou pernilongos. Evitar a\npicada é o tratamento mais eficaz. Pode ser usado repelente cujo princípio ativo é a icaridina, bem\ncomo corticoide tópico, além de anti-histamínicos e loções com cânfora ou calamina.","B":"Trata-se de prurigo estrófulo, devido a agente andador, como pulga ou percevejo. Evitar a\npicada é o tratamento mais eficaz. Pode ser\nusado repelente cujo princípio ativo é a icaridina, bem\ncomo corticoide tópico, além de anti-histamínicos e loções com cânfora ou calamina.","C":"Trata-se de urticária papular, devido a agente voador, como mosquitos ou pernilongos. Evitar a\npicada é o tratamento mais eficaz. Pode ser usado repelente cujo princípio ativo é a icaridina, bem\ncomo corticoide tópico, além de anti-histamínicos e loções com cânfora ou calamina.","D":"Trata-se de picada de inseto, devido a agente andador, como pulga ou percevejo. Evitar a\npicada é o tratamento mais eficaz. Pode ser\nusado repelente cujo princípio ativo é o DEET(N,N-\ndimetil-met-toluamida), bem como corticoide tópico, além de anti-histamínicos e loções com cânfora\nou calamina.","E":"Trata-se de urticária papular devido a agente andador, como pulga ou percevejo. Evitar a picada\né o tratamento mais eficaz. Pode ser usado\nrepelente cujo princípio ativo é a permetrina a 0,5%,\ndiretamente sobre a pele, bem como corticoide tópico, além de anti-histamínicos e loções com\ncânfora ou calamina."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-134038","number":"134038","sourceNumber":"134038","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ao examinar um lactente de um ano, nota-se a presença de adenomegalia\noccipital. Você tranquiliza a mãe e fala a ela\nque o comprometimento desses linfonodos está\nassociado","options":{"A":"à faringite aguda.","B":"à erupção dentária.","C":"à dermatite seborreica.","D":"ao processo inflamatório da parótida."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-110530","number":"110530","sourceNumber":"110530","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Vendedor ambulante queixa-se de uma úlcera com seis meses de evolução, localizada\nno lábio inferior, medindo 2,0 cm de extensão.\nEm tumores com essa história e localização,\nqual a histologia mais comum?","options":{"A":"Ca epidermoide.","B":"Ca basocelular.","C":"Ca metatípico.","D":"Ca mórfeo.","E":"Melanoma."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-110539","number":"110539","sourceNumber":"110539","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Vendedor ambulante queixa-se de uma úlcera com seis meses de evolução, localizada\nno lábio inferior, medindo 2,0 cm de extensão.\nNesse vendedor qual a lesão mais frequente\nda pele da face?","options":{"A":"Ceratose actínica.","B":"Dermatite seborréica.","C":"Ceratose seborréica.","D":"Nevos sebáceo.","E":"Ca de Bowen."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-109991","number":"109991","sourceNumber":"109991","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na Reação Hansênica Tipo 2, normalmente usamos a Talidomida, mas em\ndeterminadas situações, precisamos associar o\ncorticoide sistêmico. Em qual das situações abaixo,\nNÃO se aplica o uso desse medicamento?","options":{"A":"Iridociclite.","B":"Neurite.","C":"Ulceração das lesões.","D":"Eritema nodoso cutâneo."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-86866","number":"86866","sourceNumber":"86866","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente jovem, sexo masculino, estudante, 23 anos. Veio para avaliação de lesão\nnévica na face, pequena, medindo cerca de 2\nmm de diâmetro, papilomatosa, de cor acastanhada\ncom distribuição uniforme, margens regulares e bordos bem definidos. A lesão surgiu na\npuberdade, com crescimento lento, muito semelhante a outras na região dorsal e nos membros\nsuperiores. Queixa-se dessa lesão por motivos estéticos, e gostaria muito de retirar a lesão. Qual a\nmelhor proposta?","options":{"A":"Orientar o paciente para não mexer na lesão, pelo risco de complicações cirúrgicas, e\nobservação periódica;","B":"Encaminhar à dermatologia para avaliar se há ou não displasia;","C":"Propor excisão por shaving na própria unidade básica;","D":"Propor biópsia para descartar lesão maligna na unidade básica;","E":"Propor tratamento com despigmentante para amenizar o efeito estético."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-108578","number":"108578","sourceNumber":"108578","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"J.P.R., 45 anos, feminino, professor, informa que há 3 dias apresentou quadro de\nfaringoamigdalite, e atualmente está fazendo uso apenas de Piroxicam, que foi prescrito por médico\nem um pronto atendimento. Há aproximadamente 12h evolui com surgimento de lesões cutâneas,\nfebre baixa, artralgia e mialgia. Ao exame físico observou-se a presença de máculas eritematosas,\nbolhas sero-hemorrágicas, e púrpuras, acometendo pele e mucosa jugal. Qual seu provável\ndiagnóstico?","options":{"A":"Síndrome de Reiter.","B":"Varicela.","C":"LES.","D":"Síndrome de Stevens-Jhonson.","E":"Síndrome de Waterhouse Friderichsen."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-108605","number":"108605","sourceNumber":"108605","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual a principal causa de urticária?","options":{"A":"Medicamentosa.","B":"Infecções.","C":"Alimentos.","D":"Aeroalérgenos.","E":"Irritantes químicos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-327231","number":"327231","sourceNumber":"327231","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A Hanseníase constitui importante problema de saúde publica em nosso meio, no Brasil\n17.979 casos novos foram notificados em 2020 (MS, 2022). Na Fundação Hospitalar Alfredo da\nMatta em 2021 foram diagnosticados 81 casos novos sendo 86,4% multibacilares. Analise as\nafirmativas a seguir: I. Define-se caso de hanseníase Lesão(ões) e/ou áreas(s) da pele com\nalteração de sensibilidade térmica e/ou dolorosa e/ou tátil; e ou Espessamento de nervo periférico,\nassociado a alterações sensitivas e/ou motoras e/ou autonômicas. II. A hanseniase dimorfa\ncaracteriza-se pela presença de uma imunidade instável, podendo atingir mais de um tronco\nnervoso, episódios reacionais frequentes e baciloscopia sempre positiva. III. O tratamento das\nformas paucibacilares é feito com o PQT-U, rifampicina, dapsona e clofazimina por 6 meses. IV. Na\navaliação neurológica dos casos suspeitos, a eletroneuromiografia mostra anormalidades na\ncondução axonal e desmielinizantes que são específicos para neuropatia hansênica. Assinale a\nalternativa CORRETA:","options":{"A":"Somente as afirmativas I e III estão corretas.","B":"Somente as afirmativas I, II e III estão corretas.","C":"Somente as afirmativas I, II e IV estão corretas.","D":"Todas as afirmativas estão corretas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-327232","number":"327232","sourceNumber":"327232","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A esporotricose é a micose subcutânea mais prevalente na América Latina. Em Manaus\ncasos autoctones tem surgido desde dezembro\n2020 ocasionando um surto epidêmico da doença.\nAssinale a alternativa CORRETA:","options":{"A":"Os mecanismos de transmissão incluem implantação direta do fungo no tecido celular\nsubcutâneo, arranhaduras ou mordeduras do animal\ncontaminado e a transmissão entre humanos\né frequentemente reportada.","B":"A manifestação mais comum é a forma localizada que se traduz clinicamente por um nódulo com\ncentro necrótico e ulcerado (cancro esporotricótico) ou placa infiltrada e verrucosa e ou ulcerada.","C":"É causada por fungo do gênero Sporothrix, cujas espécies mais prevalentes no Brasil são S.\nschenckii e S. brasiliensis.","D":"O tratamento é feito exclusivamente com solução de iodeto de potássio 20 a 25 gotas 2x por dia\npara adultos após as refeições até 1 mês após o desaparecimento das lesões."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-298189","number":"298189","sourceNumber":"298189","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo masculino, proveniente de Caapiranga, apresenta, há quase 2 anos,\nmais de vinte placas eritematosas com tamanhos que variam de 3 a 15 cm de diâmetro, com\nalgumas lesões satélites menores periféricas, localizadas em tronco e membros. Aos testes de\nsensibilidades térmica e dolorosa há diminuição da sensibilidade e na palpação de nervos\nperiféricos evidenciou-se espessamento de nervo ulnar direito e ambos os nervos tibiais\nposteriores. Baciloscopia de pele negativa. Qual o provável diagnóstico clínico?","options":{"A":"Hanseniase borderline borderline","B":"Hanseniase borderline tuberculóide","C":"Hanseniase borderline lepromatosa","D":"Hanseníase indeterminada"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-298258","number":"298258","sourceNumber":"298258","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lucia é uma auxiliar de serviços gerais que mora em uma casa de madeira num terreno\nde invasão. Tem 5 filhos entre 2 e 10 anos de\nidade. Quando sai para trabalhar deixa os filhos na\ncasa da vizinha, pois não tem quem olhe as crianças durante o dia. A vizinha mora ao lado e tem\nanimais de estimação. Há duas semanas a menina de 4 anos vem queixando de prurido intenso\nque atrapalha muito à noite, não a deixando dormir. A mãe notou lesões polimorfas eritematosas,\nalgumas com aspectos de micropapulas e outras vesicopapulas com crostas em cima, algumas\nlinhas sinuosas. Essas lesões estavam entre os dedos das mãos e pés, cotovelos, axila, coxas e\nnádegas. Considerando a principal hipótese diagnóstica pela história e lesões descritas, o melhor\ntratamento seria:","options":{"A":"Hidrixizine via oral","B":"Hidratante corporal com ureia","C":"Permetrina creme 5%","D":"Corticoide tópico"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252224","number":"252224","sourceNumber":"252224","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 45 anos, há 8 meses com alopecia, artrite, parestesia nos membros inferiores e\nplacas eritematosas disseminadas pelo tegumento. Apresentava anticorpo anticardiolipina IgG e\nFAN (1:160) positivos; complemento sérico e frações estavam dentro do padrão de normalidade.\n\nEm relação ao caso clínico, pode-se afirmar:","options":{"A":"Baciloscopia e biópsia cutânea devem ser realizadas.","B":"Trata-se de artrite reumatoide e o metotrexato é a droga de escolha.","C":"Borreliose não pode ser excluída; deve-se iniciar teste terapêutico com doxiciclina.","D":"A paciente apresenta lúpus eritematoso sistêmico; tratamento com azatioprina deve ser iniciado."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252225","number":"252225","sourceNumber":"252225","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem, 51 anos, pescador, natural e procedente de Autazes (AM), diabético, há 7\nmeses com úlcera com bordas enduradas na\nperna esquerda. O exame direto para Leishmania foi\nnegativo. Baseado no caso clínico, a alternativa CORRETA é:","options":{"A":"Na leishmaniose tegumentar americana causada por L. guyanensis, o tratamento de escolha é o\nantimoniato de meglumina.","B":"Teste de Montenegro positivo (enduração local de 5 mm) confirma diagnóstico de leishmaniose\ntegumentar americana.","C":"A biópsia da lesão mostrará áreas de necrose e inúmeros bacilos álcool-ácido resistentes.","D":"O exame direto negativo não exclui o diagnóstico de leishmaniose tegumentar americana."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252272","number":"252272","sourceNumber":"252272","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Alice de 3 anos, é recebida na sala de emergência após ter sido picada por uma abelha\nhá cerca de 10 minutos. Mãe refere intensa\nirritabilidade. Exame físico: FC= 136 bpm; FR= 50 irpm;\nrubor facial e estridor laríngeo; Face: edema de lábios e língua; Pulmões: murmúrio vesicular\npresente e simétrico bilateralmente e alguns sibilos; Pele: placas de urticária. Qual o diagnóstico\ne a\nconduta mais apropriados neste momento?","options":{"A":"Angioedema, corticoide endovenoso.","B":"Anafilaxia, adrenalina intramuscular.","C":"Alergia a picada de inseto, dexclorferinamina oral.","D":"Urticária, loratadina oral."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-252286","number":"252286","sourceNumber":"252286","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Escolar de 8 anos, apresenta infecção por dermatófitos que ao exame revela alopecia\ntonsurante com descamação e prurido. O tratamento adequado é:","options":{"A":"Corticoide oral","B":"Corticoide tópico","C":"Cetoconazol tópico","D":"Griseofulvina"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-208411","number":"208411","sourceNumber":"208411","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Hanseníase, doença crônica, infectocontagiosa, de evolução lenta, manifesta-se\nprincipalmente por sinais e sintomas\ndermatoneurológicos: lesões na pele e nos nervos periféricos.\nQuais achados clínicos relacionados a seguir, você espera encontrar em um paciente que\napresenta diagnóstico confirmado de hanseníase, baciloscopia de pele positiva?","options":{"A":"Fraqueza muscular simétrica e proximal, artralgia, heliótropo e fotossensibilidade","B":"Placa eritematosa com hiperhidrose, sem rarefação dos pelos, no tronco","C":"Mancha hipocrômica, com diminuição da sensibilidade térmica no abdome","D":"Várias placas eritematosas, infiltradas, simetricamente distribuídas, ocupando extensas áreas do\ntegumento, madarose, edema das mãos e pés"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-208309","number":"208309","sourceNumber":"208309","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sabendo que o melanoma é o câncer de pele com maior índice de mortalidade, seu\ndiagnóstico precoce está associado a um melhor prognóstico. Paciente, 59 anos, apresenta nódulo\nnegro-azulado, de crescimento rápido, com discreta ulceração na perna. Como você classifica esta\nlesão?","options":{"A":"Lentigo maligno melanoma","B":"Melanoma nodular","C":"Melanoma lentiginoso acral","D":"Melanoma extensivo superficial"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-208295","number":"208295","sourceNumber":"208295","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pré-escolar de 5 anos, é levado ao atendimento médico com lesão em pele que iniciou\ncom placa descamativa seca, ligeiramente eritematosa e elevada que disseminou centrifugamente.\nQual o diagnóstico provável?","options":{"A":"Estrófulo.","B":"Impetigo bolhoso.","C":"Tinea corporis.","D":"Psoríase."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-176004","number":"176004","sourceNumber":"176004","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à hanseníase, é possível afirmar que:","options":{"A":"Hanseníase virchowiana cursa com infiltração dos lóbulos de orelhas, queda do terço externo\ndas sobrancelhas e baciloscopia negativa.","B":"Eritema nodoso é um quadro reacional que ocorre nas formas paucibacilares.","C":"Hanseníase tuberculoide, de acordo com a OMS, é classificada como forma multibacilar.","D":"Hanseníase indeterminada caracteriza-se por mancha (s) hipocrômica (s) de limites imprecisos\ncom alteração da sensibilidade."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-151866","number":"151866","sourceNumber":"151866","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo masculino, passando férias em Manaus, comparece ao ambulatório\napresentando pápulas amareladas, com ponto escuro central, ao redor das unhas dos artelhos, que\nevoluiu inicialmente com prurido discreto e posterior aparecimento de sensação dolorosa. O mesmo\né dono e trabalha em um curral nos arredores de Natal - RN. O diagnóstico mais provável é:","options":{"A":"Pulíase.","B":"Miíase.","C":"Tungíase.","D":"Cimidíase."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-151875","number":"151875","sourceNumber":"151875","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente procedente de Eirunepé - AM, apresenta-se com infiltração difusa da pele de\ncoloração acastanhada e brilhosa. Ao exame clínico, apresentava lesões papulares em tronco e\npavilhões auriculares e coloração \"arroxeada\" em regiões palmo-plantares. Durante a consulta\ntambém queixou-se de obstrução nasal e rinorreia serossanguinolenta há dois anos. Qual o\nprincipal diagnostico a ser pensado e o primeiro exame a ser realizado?","options":{"A":"Sífilis secundária / VDRL.","B":"Sífilis terciária / FTA-ABS.","C":"Hanseníase virchowiana / teste de Mitsuda.","D":"Hanseníase virchowiana / baciloscopia de pele."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-152001","number":"152001","sourceNumber":"152001","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre hanseníase é CORRETO afirmar:","options":{"A":"Sugere-se avaliar anualmente, durante cinco anos, todos os contatos não doentes, quer sejam\nfamiliares ou sociais;","B":"Quando disponível a baciloscopia, o seu resultado negativo classifica obrigatoriamente o doente\ncomo PB.","C":"A classificação operacional utilizada de caso de hanseníase, visando definir o esquema de\ntratamento com poliquimioterapia, baseia-se\nno número de lesões cutâneas de acordo com os\nseguintes critérios: Paucibacilar (PB) - casos com até três lesões de pele; Multibacilar (MB) -\ncasos\ncom mais de três lesões de pele.","D":"Considera-se caso de hanseníase a pessoa que apresenta dois ou mais dos seguintes sinais\ncardinais: lesões e/ou áreas da pele com\nalteração da sensibilidade térmica dolorosa ou tátil;\nespessamento de nervo periférico, associado a alterações sensitivas e/ou motoras e/ou\nautonômicas; presença de bacilos M. leprae, confirmada na baciloscopia de esfregaço intradérmico\nou na biópsia de pele."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-103855","number":"103855","sourceNumber":"103855","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Clarice de 32 anos está com duas manchas hipocromicas em região medial do\nantebraço esquerdo, não sabe a quanto tempo.\nPercebeu após o parto de sua filha, há três meses.\nÀs vezes, a mancha doe, porém em geral, é dormente. Você a orienta sobre seu diagnóstico de\nHanseníase e:","options":{"A":"explica que deve ser tratada na própria Unidade de Saúde e por 18 meses (esquema para\nPaucibacilares)","B":"esclarece a paciente de que os encaminhamentos para a unidade de referência são necessários\nsempre após a suspeita de caso novo de\nHanseníase.","C":"explica que deve ser tratada na própria Unidade de Saúde da Família e por seis meses\n(esquema para Paucibacilares)","D":"explica que os membros da família (contatos intra- domiciliares) se tiverem cicatriz de BCG não\nnecessitam fazer segunda dose"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-81019","number":"81019","sourceNumber":"81019","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à hanseníase, podemos afirmar que:","options":{"A":"As provas cutâneas, como a reação de Mitsuda, têm grande valor diagnóstico.","B":"O período de incubação é em média de 6 (seis) meses.","C":"Está comprovada a existência de imunidade racial em alguns grupos étnicos isolados.","D":"O homem é o único reservatório de importância demonstrada.","E":"M. leprae se desenvolve em alguns meios de cultura."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-46673","number":"46673","sourceNumber":"46673","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de cinco meses apresenta na área de fralda pústulas satélites, aquelas que\nsalpicam a pele contígua, a conduta é:","options":{"A":"Griseofulvina Sistêmica","B":"Corticoide Sistêmico","C":"Creme Imidazólico","D":"Aciclovir tópico","E":"Penicilina"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-34297","number":"34297","sourceNumber":"34297","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A henseníase é uma doença infectocontagiosa de evolução lenta, com manifestações\ndermatoneurológicas. Em relação ao controle da Hanseníase, podemos afirmar, EXCETO:","options":{"A":"A forma principal de contágio é a via aérea superior sendo necessário o contato íntimo com o\npaciente bacilífero não tratado.","B":"As lesões de Hanseníase tem apresentações múltiplas mas sempre existe alteração da\nsensibilidade sendo este o critério diagnóstico.","C":"O tratamento da Hanseníase deve ser feito na Unidade Básica de Saúde sendo encaminhados\npara a referência os pacientes com\nintercorrências graves ou necessitem de correção cirúrgica.","D":"Os contactantes intradomiciliares de pessoa com Hanseníase devem fazer exame dematológico\ne receberem 2 doses da vacina BCG.","E":"Os pacientes com Hanseníase devem ser tratados com 09 doses (paucibacilares) ou 18 doses\n(multibacilares) dependendo do número de lesões apresentadas."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-26457","number":"26457","sourceNumber":"26457","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem, 29 anos, apresentou quadro agudo de febre, nódulos, eritematosos, alguns\nulcerados em membros superiores, dores articulares, adenomegalia diagnósticas generalizada,\nhepato-esplenomegalia e edema de mãos e pés. Quais são as suspeitas desse quadro clínico?","options":{"A":"Hanseníase virshowiania e escarlatina","B":"Eritema nodoso hansênico e reação medicamentosa","C":"Sífilis secundária e hanseníase reacional","D":"Mononucleose e vasculite infecciosa","E":"farmacodermia e escarlatina"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-10006","number":"10006","sourceNumber":"10006","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Como se caracteriza uma erupção vesiculosa: VARICELA","options":{"A":"Vesícula ou bolha que se rompe logo, formando crosta amarelada.","B":"Grupo de vesículas sobre uma base eritematosa.","C":"Placas vesico-escamosa avermelhadas, circinadas e pruriginosas.","D":"Quadro poliformio em céu estrelado, com máculas, vesículas, pústulas e crostas.","E":"Vesículas com ou sem eritema."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-10043","number":"10043","sourceNumber":"10043","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O bebê de Elis, Ícaro, nasceu há 8 dias, a termo, com peso adequado à idade\ngestacional. Está em aleitamento exclusivo.\nElis está preocupada pois não evacua há 3 dias e está\ncom bolinhas vermelhas no rosto, brotoeja. Ao exame clínico, as alterações são as referidas\npápulas vermelhadas no rosto, fimose e presença do colo umbilical. Já fez o teste do Pezinho, mas\nainda não foi vacinado. Sua conduta é:","options":{"A":"Orientar a mãe que deve ser uma constipação funcional e prescreve um laxante.","B":"Explica que Ícaro apresenta miliária rubra e orienta sobre o calor. Indica usar amido de milho\ntópico.","C":"Suspeita de infecção secundária no colo umbilical já que este ainda não caiu e encaminha à\nemergência.","D":"Orienta que a fimose é comum ao nascer e que, caso não desapareça até os 6 meses, está\nindicada cirurgia para correção.","E":"Pedir à mãe para aguardar a melhora da miliária rubra e, então, vacinar contra hepatite B e\npoliomelite."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-7521","number":"7521","sourceNumber":"7521","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Abaixo são descritas as dermatopatias mais comuns na infância - assinale a alternativa\nque corresponde ao diagnóstico das quatro lesões\ndescritas, respectivamente: 1- Lesões\neritematodescamativas, papulosas, não pruriginosas, em couro cabeludo, face, pescoço, axilas e\nárea de fralda, podendo ocorrer desde o primeiro mês de vida. 2- Doença eczematosa, crônica\nrecorrente, pruriginosa, com períodos de acalmia e exacerbação. 3- Lesão eritematopapulosa\nencimada por vesícula, pruriginosa, localizada em áreas expostas, túnel sinuoso levemente saliente\ncom conteúdo seroso, podendo haver vesículas, bolhas, infecção secundária e aczematização. 4-\nPápulas arredondadas, peroladas, firmes, com umbilicação central, sem sinais inflamatórios ao\nredor, distribuídas por toda a pele, exceto couro cabeludo e regiões palmoplantares.","options":{"A":"Dermatite seborreica, dermatite atópica, larva migrans cutânea, molusco contagioso.","B":"Dermatite atópica, dermatite de contato, miliária, molusco contagioso.","C":"Dermatite seborreica, molusco contagioso, dermatite de contato, escabiose.","D":"Dermatite atópica, dermatite seborreica, larva migrans cutânea, molusco contagioso.","E":"Dermatite seborreica, dermatite de contato, molusco contagioso, escabiose."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-294483","number":"294483","sourceNumber":"294483","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adolescente, 16 anos de idade, chega à UBS com quadro de poliúria há,\naproximadamente, 40 dias. Refere fadiga\nfrequente, o que atribui ao aumento de peso, durante a\npandemia. Nega febre, disúria e outros sintomas. Ao exame, IMC: 29kg/m²; acima do 95º percentil;\nbom estado geral, eupneica, hidratada, afebril, corada. Apresenta eritema macular hiperemiado sob\nambas as mamas, pruriginoso. O exame de urina I mostra: pH: 7,2; Densidade: de 1,01; Ausência\nde cetonas, bilirrubina, urobilinogênio, sangue e nitrito; presença de glicose ++; raros leucócitos\ne\nraras células epiteliais. Glicemia em jejum foi de 100mg/dL Indique a principal suspeita diagnóstica\npara as lesões de pele da paciente.","options":{"A":"Intertrigo por cândida.","B":"Impetigo.","C":"Acantose nigricans.","D":"Acne hormonal."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-62887","number":"62887","sourceNumber":"62887","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, dois anos de idade, apresenta lesões em pele desde os oito meses de vida.\nSão lesões eritematosas, localizadas nas pregas de flexão, no rosto e no pescoço, parte superior\ndos braços e das costas, dorso de mãos, pés, dedos das mãos e dos pés. Melhora quando usa\n\nanti-histamínicos e corticoide tópico. Recebe o diagnóstico de Dermatite Atópica (DA). A respeito da\npatologia descrita, é INCORRETO afirmar que:","options":{"A":"A Dermatite Atópica (DA), ou eczema infantil, é uma doença crônica da pele que ocorre muitas\nvezes em associação com rinite alérgica e asma (conhecida como a tríade atópica).","B":"A função de barreira da pele anormal atópica leva à perda de água transepidérmica aumentada\ne ao aumento da penetração de irritantes,\nalérgenos e micróbios.","C":"A maioria dos pacientes com DA está colonizada com Staphylococcus aureus, em contraste com\na prevalência de um estado de portador em 10%\ndos indivíduos não atópicos.","D":"Pacientes com DA infantis geralmente apresentam pápulas eritematosas e papulovesiculares em\nbochechas, testa ou couro cabeludo e não são pruriginosas.","E":"Os antagonistas de leucotrienos (zafirlucaste e montelucaste) são úteis para o tratamento da\nasma e da rinite alérgica, e, para a maior\nparte dos pacientes com DA grave, eles parecem ter\npouco sucesso."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-35005","number":"35005","sourceNumber":"35005","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere ao tratamento adjuvante do melanoma cutâneo, a droga sistêmica\nmais eficaz é:","options":{"A":"interferon alfa.","B":"dacarbazina.","C":"paclitaxel","D":"carboplatina.","E":"interleucina 2."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27437","number":"27437","sourceNumber":"27437","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na condução terapêutica do melanoma cutâneo, são indicações de pesquisa do\nlinfonodo sentinela, exceto:","options":{"A":"nível de Clark III.","B":"espessura de Breslow: 1,4 mm.","C":"presença de ulceração.","D":"subtipo histológico lentigo maligna.","E":"sinal de regressão."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-11202","number":"11202","sourceNumber":"11202","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, 24 anos de idade, com história prévia de asma, sem crise desde os 14 anos,\nsofreu, há 2 horas, picada de abelha em\nbraço esquerdo. Ao exame, apresenta-se com TA: 130 X\n80 mmHg, PR: 100 bpm, frequência respiratória de 21 ipm. Ausculta cardiorrespiratória normal, com\ndor intensa em braço esquerdo, com sinais locais de flogose. Boa perfusão periférica. A conduta\nimediata é:","options":{"A":"iniciar adrenalina SC.","B":"indicar prometazina IM.","C":"solicitar ao setor antiveneno soro específico.","D":"indicar loratadina oral.","E":"iniciar dexametasona IM."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-11203","number":"11203","sourceNumber":"11203","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, 24 anos de idade, com história prévia de asma, sem crise desde os 14 anos,\nsofreu, há 2 horas, picada de abelha em\nbraço esquerdo. Ao exame, apresenta-se com TA: 130 X\n80 mmHg, PR: 100 bpm, frequência respiratória de 21 ipm. Ausculta cardiorrespiratória normal, com\ndor intensa em braço esquerdo, com sinais locais de flogose. Boa perfusão periférica. A melhor\nconduta subsequente, baseada na história natural provável do caso, é:","options":{"A":"internar o paciente e instalar acesso venoso.","B":"liberar o paciente após controle da dor para observação domiciliar.","C":"observar o paciente por mais duas horas e liberá-lo para observação domiciliar.","D":"observar o paciente no PA por 12 horas e liberá-lo para observação domiciliar.","E":"liberar o paciente para observação domiciliar em uso de corticoide oral por dois dias."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-281862","number":"281862","sourceNumber":"281862","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa correta sobre a Síndrome da Pele Escaldada Estafilocócica.","options":{"A":"É uma infecção bacteriana grave, cursa com bolhas e apresenta elevada mortalidade.","B":"É causada por toxinas esfoliativas de estafilococos, e o foco pode ser a conjuntiva.","C":"O recém-nascido tem menor probabilidade de apresentar essa doença.","D":"Na evolução do quadro surgem cicatrizes."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-281870","number":"281870","sourceNumber":"281870","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a Síndrome de Stevens-Johnson (SSJ) e a Necrólise Epidérmica Tóxica (NET)\nassinale a alternativa incorreta.","options":{"A":"O achado laboratorial isolado de eosinofilia é um sinal de mau prognóstico.","B":"Seu mecanismo envolve a apoptose dos queratinócitos, por meio da ativação da via FasL e da\nvia TNF.","C":"Seus diagnósticos diferenciais incluem a reação a fármacos com eosinofilia e sintomas\nsistêmicos, a síndrome da pele escaldada\nestafilocócica e a infecção pelo vírus Chikungunya.","D":"O SCORTEN é um escore de gravidade."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-249715","number":"249715","sourceNumber":"249715","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As dermatoses produzem achados histopatológicos que dão pistas sobre tipo de\nalteração cutânea que as estão provocando.\nTendo em vista, os achados encontrados em\nfragmentos cutâneos, numere a segunda coluna de acordo com a primeira. ( 1 ) Degeneração\nGranular; ( 2 ) Degeneração Hidrópica; ( 3 ) Degeneração Basofilico; ( 4 ) Degeneração Fibrinoide; (\n5 ) Degeneração Balonizante; ( ) Característica de viroses; ( ) Própria de colagenoses, podendo\nestar presente em vasculite necrosante e nódulos reumatoides; ( ) Degeneração fisiológica em\náreas expostas aos raios UV e, de modo patológico, em afecções por fotosenssibilidade; ( )\nPresente em Lúpus Eritematoso, Líquen plano, Dermatomiosite, Líquen Escleroso e Atrófico e\nErupção Medicamentosa Fixa; ( ) Presente em doenças congênitas com alteração de\nqueratinização como eritrodermia ictiosiforme bolhosa, queratodermia palmo plantar e nevo\nverrucoso. A alternativa que contém a sequência correta, de cima para baixo, é .","options":{"A":"1 2 3 5 4","B":"1 5 3 2 4","C":"2 1 5 4 3","D":"5 4 3 2 1","E":"4 2 1 3 5"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-249716","number":"249716","sourceNumber":"249716","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre as dermatoses infecciosas que acometem os pés, é correto afirmar que","options":{"A":"o bacilo de Koch pode levar a úlcera e lúpus vulgar.","B":"os dermatófitos podem causar lesões de paroníquia aguda e impetigo, provocadas por má\nhigiene e manipulação que levem a trauma local.","C":"o estafilococos causa dactilite bolhosa distal e erisipela, em decorrência de porta de entrada\naberta ou manipulação, levando a trauma.","D":"o estreptococos pode levar a eritrasma e queratose plantar sulcada, com erosões circulares nos\nporos que fluorescem à lâmpada de Wood.","E":"a corinebactéria causa lesões plantares, interdigitais e ungueais. Em pacientes jovens, ocorre\npor uso de calçado fechado. Em idosos,\nacontece assimetricamente e afeta, geralmente, o espaço\nentre o quarto e quinto pododáctilos."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-249733","number":"249733","sourceNumber":"249733","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre Onicopatias e seus achados clínicos, é correto afirmar que","options":{"A":"na Psoríase, há a presença de depressões lineares, com superfície e sem brilho.","B":"na Doença de Darier, verifica-se a presença de unhas atróficas com pterígio, cristas e sulcos na\nlâmina ungueal.","C":"nas doenças renais, observa-se a presença de linhas de Muehrcke, que são estrias brancas\ntransversais nas unhas.","D":"na Alopecia Areata, observam-se depressões cupuliformes, onicólise, hiperqueratose\nsubungueal e lesão em mancha de óleo.","E":"no Líquen plano, observam-se a presença de estria ou estrias brancas ou avermelhada da\ncutícula à borda livre, terminando com unha pequena com chanfradura triangular."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-249734","number":"249734","sourceNumber":"249734","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre Síndrome de Sweet, é correto afirmar que","options":{"A":"após a resolução das lesões, há formação de cicatriz no local.","B":"as citocinas, como IL-1, IL-3, IL-8 e INF-gama parecem não ter papel etiológico nesta dermatose.","C":"é uma dermatose neutrofílica febril, com lesões eritematosas indolores, e que tem resposta lenta\nà terapia com corticosteroides.","D":"a aparência pseudovesiculosa, secundária à edema pronunciado na derme superior, é incomum\nna forma associada à malignidade.","E":"sobre a etiologia, uma teoria sugere reação isomórfica de Koebner, outra propõe mecanismos\nassociados a raios UVB com ativação de neutrófilos, e produção epidérmica de fator de necrose\ntumoral alfa e IL-8."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-162475","number":"162475","sourceNumber":"162475","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente chega à Unidade de Saúde da Família apresentando sinais flogísticos (calor,\ndor, rubor, edema), além de um nódulo\neritematoso com sinais de flutuação em região de joelho\ndireito há dois dias. Ao fazer a avaliação, o médico da equipe percebe tratar-se de um abcesso. Em\nrelação à técnica de drenagem que deve ser utilizada, é CORRETO afirmar que:","options":{"A":"Um dreno de Penrose deve ser introduzido no local da incisão com 1 ou 2 cm para fora.","B":"A incisão deve ser pequena com o intuito de possibilitar a drenagem espontânea da secreção\npurulenta do interior do abcesso.","C":"A pele circunjacente deve ser espremida depois da drenagem espontânea, com o objetivo de\nque a secreção acumulada em loculações possa\nse exteriorizar.","D":"Um anestésico como técnica de bloqueio de campo regional deve ser utilizado, com objetivo de\nevitar que o paciente sinta dor durante a realização do procedimento.","E":"O uso de campo estéril, assim como de luvas estéreis, máscara e óculos de proteção não se\nfazem necessários, porque se trata de uma lesão infectada, assim não é necessário que o\nprocedimento seja asséptico."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-162488","number":"162488","sourceNumber":"162488","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao tratamento das lesões do molusco contagioso, é correto afirmar que","options":{"A":"a remoção mecânica é o tratamento de escolha.","B":"a remoção mecânica das lesões não deve ser imposta às pessoas imunocompetentes.","C":"a transmissão do Molluscipoxvirus causador do molusco contagioso é via fômites, por isso não\nse faz necessário que a remoção mecânica\nseja feita de maneira asséptica.","D":"antes da remoção mecânica via curetagem, deve-se colocar espessa camada de creme\nanestésico sob bandagem oclusiva, com tempo de contato mínimo de 15min.","E":"a conduta adequada, nos casos de pessoas com molusco contagioso na atenção básica, é o\nencaminhamento responsável ao dermatologista para a realização do tratamento adequado."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-162500","number":"162500","sourceNumber":"162500","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Cecília leva a filha Ana para o acolhimento na Unidade de Saúde da Familia (USF) e é\nacolhida pela residente médica. Relata que apreceu na filha uma \"vermelhidão\" na parte interna das\ncoxas e \"bumbum\". Ao exame físico, a médica confirma o relato e percebe um eritema intenso, sem\npresença de pústulas ou descamação. Sobre a patologia de Ana, analise as assertivas e identifique\ncom V as verdadeiras e com F as falsas; ( ) Trata-se de dermatite das fraldas; ( ) Pode evoluir para\nnecessidade de uso de um antifúngico; ( ) Será, possivelmente, necessário o uso de corticoide\ntópico; ( ) O tratamento preventivo consiste em manter a pele seca e úmida, trocar com frequência\nas fraldas e evitar deixar a crianças sem fraldas. A alternativa que contém a sequência correta, de\ncima para baixo, é:","options":{"A":"V V V F","B":"V F F V","C":"V F V F","D":"F V V F","E":"F V F V"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-139760","number":"139760","sourceNumber":"139760","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O senhor Antônio é portador de hanseníase e está recebendo os cuidados na USF da\nVila Tabajara. Sobre hanseníase, que continua sendo um importante problema de saúde pública,\nassinale a alternativa CORRETA.","options":{"A":"O diagnóstico da hanseníase é essencialmente clínico, com base nos sinais e sintomas\ne história epidemiológica, pois a\n\nbaciloscopia negativa não afasta o seu diagnóstico.","B":"Nas formas clínicas indeterminada, tuberculoide e algumas vezes na forma dimorfa, a\nbaciloscopia positiva é de fato o resultado\n\nesperado.","C":"O senhor Antônio, cujo caso foi diagnosticado na USF, deve ser notificado ao SINAN e\niniciar, imediatamente, o tratamento\n\npoliquimiterápico: rifampicina e clofazimina, para os multibacilares, e rifampicina e dapsona, para\nospaucibacilares.","D":"Embora grande número de indivíduos possa estar infectado, apenas pequeno número deles\ndesenvolve ossintomas da doença, como é o caso do senhorAntônio, considerando-se o M.\nlepraede baixa virulência."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-134757","number":"134757","sourceNumber":"134757","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa INCORRETA relacionada à hanseníase.","options":{"A":"Apresenta longo período de incubação.","B":"O Mycobacterium leprae é parasita intracelular obrigatório, residindo nos macrófagos.","C":"O Mycobacterium leprae é cultivado em meios especiais de cultura laboratoriais.","D":"O Mycobacterium leprae cresce seletivamente nas porções mais frias do corpo."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-350819","number":"350819","sourceNumber":"350819","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No ambulatório, uma criança de 3 anos de idade apresenta a seguinte lesão de pele:\npápula amarelada com ponto escuro central. Logo no início, tinha edema, eritema, prurido e dor.\nEstavam localizadas nos pés e na região glútea. Qual o diagnóstico mais provável?","options":{"A":"Tungíase.","B":"Escabiose.","C":"Molusco contagioso.","D":"Larva migrans cutânea."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-321326","number":"321326","sourceNumber":"321326","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente, 1 ano, vem à consulta de puericultura com queixa de lesão avermelhada em\ndobra anterior do pescoço há 2 semanas. Nega febre. Nega casos semelhantes na família. Ao\nexame: presença de lesão eritematosa em face anterior do pescoço com algumas lesões satélites,\nconforme figura a seguir. Qual é o diagnóstico mais provável?","options":{"A":"Tinea corporis.","B":"Dermatite seborreica.","C":"Dermatite de contato.","D":"Intertrigo candidiásico."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-321337","number":"321337","sourceNumber":"321337","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em seu turno de demanda espontânea na sua UBS, você atende Cleodécio, de 54\nanos, que refere estar fazendo uma consulta\nde retorno. Ele relata que ?o pé esquerdo está morto,\no olho esquerdo está muito seco e há manchas na pele? e traz o resultado de um exame de\nbaciloscopia de raspado intradérmico para pesquisa de BAAR que foi solicitado por outro médico. O\nresultado do exame é negativo. Em seu exame físico, apresenta face infiltrada e madarose. Há oito\nlesões papulares escuras, endurecidas, não dolorosas e não pruriginosas em tórax, dorso e\nmembros inferiores. Em membro inferior esquerdo, você observa espessamento do nervo fibular\ncomum. O exame dermatoneurológico mostra alteração de sensibilidade em face, região medial do\nantebraço à direita, região lateral da perna esquerda e dorso de pé esquerdo. A avaliação de\nfunções motoras evidencia garra ulnar à direita e perda da dorsiflexão de pé esquerdo. Para fins de\nconduta terapêutica, qual classificação funcional da Hanseníase de Cleodécio e por quanto tempo a\nPoliquimioterapia Única (PQT-U) deve ser adotada?","options":{"A":"Multibacilar, pois há mais de cinco lesões de pele. O esquema terapêutico deve ser mantido por\nseis meses, tendo em vista a baciloscopia negativa.","B":"Multibacilar, pois há mais de cinco lesões de pele. O esquema terapêutico deve ser mantido por\ndoze meses, tendo em vista a classificação funcional.","C":"Paucibacilar, pois a baciloscopia está negativa. O esquema terapêutico deve ser mantido por\nseis meses, tendo em vista a classificação funcional.","D":"Paucibacilar, pois a baciloscopia está negativa. O esquema terapêutico deve ser mantido por\ndoze meses, pois o paciente apresenta acometimento neural."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-321338","number":"321338","sourceNumber":"321338","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em seu turno de demanda espontânea na sua UBS, você atende Cleodécio, de 54\nanos, que refere estar fazendo uma consulta\nde retorno. Ele relata que ?o pé esquerdo está morto,\no olho esquerdo está muito seco e há manchas na pele? e traz o resultado de um exame de\nbaciloscopia de raspado intradérmico para pesquisa de BAAR que foi solicitado por outro médico. O\nresultado do exame é negativo. Em seu exame físico, apresenta face infiltrada e madarose. Há oito\nlesões papulares escuras, endurecidas, não dolorosas e não pruriginosas em tórax, dorso e\nmembros inferiores. Em membro inferior esquerdo, você observa espessamento do nervo fibular\ncomum. O exame dermatoneurológico mostra alteração de sensibilidade em face, região medial do\nantebraço à direita, região lateral da perna esquerda e dorso de pé esquerdo. A avaliação de\nfunções motoras evidencia garra ulnar à direita e perda da dorsiflexão de pé esquerdo. Próximo de\nconcluir a PQT-U iniciada, Cleodécio procura novo atendimento. Ele relata início súbito de febre,\nartralgia múltipla, queda de estado geral, nódulos e placas eritematosos difusos dolorosos. Ele\nrefere também episódios de ?sensação de dor em choque nos nervos?, parestesia difusa e piora\naguda de função motora. Em breve revisão de prontuário, está registrado que Cleodécio não possui\ncomorbidades cardiovasculares, nem endócrino-metabólicas. Qual é a principal hipótese\ndiagnóstica e qual conduta terapêutica?","options":{"A":"Reação hansênica tipo 1. Não iniciar tratamento medicamentoso, mas encaminhar para centro\nde referência.","B":"Reação hansênica tipo 2. Iniciar tratamento medicamentoso com metilprednisolona EV e\nencaminhar para centro de referência.","C":"Reação hansênica tipo 1. Iniciar profilaxia para estrongilodíase, iniciar Prednisona 1mg/kg/dia,\niniciar Amitriptilina 25mg/dia e aumento gradativo,\nse persistência de sintomas neurológicos.\nEncaminhar para centro de referência.","D":"Reação hansênica tipo 2. Iniciar profilaxia para estrongilodíase, iniciar Prednisona 1mg/kg/dia,\niniciar Amitriptilina 25mg/dia, com aumento\ngradativo, se persistência de sintomas neurológicos.\nEncaminhar para centro de referência."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-292827","number":"292827","sourceNumber":"292827","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 52 anos, procura a unidade básica de saúde, por apresentar lesão pigmentada\nassintomática em membro inferior, percebida há 8 meses (figura). A lesão possui 0.9 cm de\ndiâmetro e está localizada na região lateral da coxa direita. Em relação ao próximo passo na\nabordagem da lesão em questão, marque a alternativa CORRETA.","options":{"A":"Encaminhar para cirurgião para realizar excisão com margens de 1 cm.","B":"Acompanhar clinicamente a lesão com foto e visitas periódicas semestrais.","C":"Encaminhar para dermatologista para realizar dermatoscopia e biópsia excisional.","D":"Realizar biópsia incisional na própria unidade básica para elucidação diagnóstica."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/292827.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-292833","number":"292833","sourceNumber":"292833","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente lactente de 1 ano e dois meses foi levado ao ambulatório de Puericultura com\nquadro de lesões papulares eritematosas pruriginosas e vesículas disseminadas em palmas das\nmãos, plantas dos pés, nos espaços interdigitais, antebraço, axilas e região glútea. Mãe nega febre\nou outros comemorativos e relata estar apresentando quadro de prurido corporal há 3 semanas.\n\nNega contato do paciente com animais. De acordo com o quadro clínico exposto, qual o diagnóstico\ne tratamento?","options":{"A":"Pediculose / Ivermectina 200 mcg/kg em dose única.","B":"Escabiose / Permetrina em loção cremosa a 1 ou 5%.","C":"Miíase / Aplicação de vaselina sólida e retirada com pinça.","D":"Larva migrans / Tiabendazol a 5%, 2x/dia, por 2 semanas."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-292856","number":"292856","sourceNumber":"292856","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Durante sua primeira semana de atendimento em sua Unidade de Saúde, você\nparticipa de uma reunião de equipe envolvendo\ntodas as equipes e gestores. Dentre os pontos de\nfragilidade que são trazidos pela gestão, você percebe que não constam pacientes com\nHanseníase nas microáreas das suas Agentes Comunitárias de Saúde. Posteriormente, em uma\nreunião somente com sua equipe (enfermeira e agentes comunitários de saúde), você decide\nreabordar a temática, trazendo algumas sugestões para a Investigação Epidemiológica para o\ndiagnóstico precoce de casos. Assinale a alternativa que contempla um componente da\nInvestigação Epidemiológica.","options":{"A":"Busca ativa de todos os casos do território, incluindo antigos e novos casos.","B":"Vigilância de contatos somente de pacientes de classe operacional Multibacilar.","C":"Vigilância de contatos de pacientes independentemente de classe operacional: seja Paucibacilar\nou Multibacilar.","D":"Realização de atendimento com exame dermatoneurológico para dermatoses e/ou neuropatias\nperiféricas de todos os moradores da microárea."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-259721","number":"259721","sourceNumber":"259721","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 26 anos, comparece a consulta ambulatorial com queixa de lesões cutâneas\nem face que surgiram há 8 meses. O único\ntópico que fez uso foi pomada contendo neomicina e\nbacitracin, sem melhora alguma das lesões. Nega lesões em outras áreas do corpo. Considerando\no quadro clínico descrito e o exame dermatológico da paciente (figura), trata-se de qual lesão\nelementar, características secundárias e principal hipótese diagnóstica?","options":{"A":"Placas eritematosas e descamativas em nariz e região malar, cuja simetria sugere diagnóstico\nde psoríase.","B":"Placas eritematosas, com discreta atrofia e descamação malar e discromia em dorso nasal,\nsugerindo lupus cutâneo.","C":"Manchas eritematosas e áreas de hipercromia em dorso nasal e malar, representando fase\ninflamatória de melasma.","D":"Placas eritematosas e descamativas, cuja liquenificação, discromia, e distribuição, sugerem\neczema seborreico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/259721.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-259728","number":"259728","sourceNumber":"259728","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 20 anos, com história de asma intermitente, sem uso de medicamentos\nregularmente, foi levada à Unidade de Pronto\nAtendimento pelos familiares por apresentar prurido\ncutâneo e eritema de face e de tórax anterior há cerca de 1 hora. Há 30 minutos iniciou edema de\nlábios, acompanhado de tontura e náuseas. Ao exame físico: estado geral regular, hipocorada\n(2+/4+), ECG 15, Temperatura 37,2ºC; ausculta cardíaca: sem alterações, PA 70 x 40 mmHg em\nmembros superiores e FC 110 bpm; Pele: placas eritematosas e edematosas com leve palidez\ncentral em tronco e membros superiores e eritema e edemas periocular bilateral e labial; ausculta\npulmonar: murmúrio vesicular universal com sibilos inspiratórios difusos, FR 32 ipm e SatO? 87%\nem ar ambiente; Extremidades: pulsos finos com enchimento capilar maior que 5 segundos. A\npaciente foi encaminhada para sala de monitorização cardíaca, iniciadas suplementação de\noxigênio e expansão volêmica com solução isotônica. LEGENDA: ECG: escala de coma de\nGlasgow; PA: pressão arterial; FC: frequência cardíaca; FR: frequência respiratória; SatO?:\nsaturação de oxigênio. Qual deverá ser a conduta imediata?","options":{"A":"metilprednisolona 125mg e adrenalina 0,3 mg, ambos via endovenosa.","B":"ceftriaxona 2g e noradrenalina 0,05 mcg/kg/min, ambos via endovenosa.","C":"manter paciente em posição supina e adrenalina 0,3 mg via intramuscular.","D":"metilprednisolona 60mg via endovenosa e fenoterol 20 gotas via inalatória."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-234013","number":"234013","sourceNumber":"234013","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 53 anos foi referido a um servic?o de cirurgia ambulatorial com uma\nlesa?o pigmentada, escurecida, protuberante e na?o ulcerada em face anterior da coxa direita. O\ncirurgia?o avaliou e achou ser segura a si?ntese da ferida sem a necessidade de retalho e\nprocedeu a ressecc?a?o com margem de 1 cm. Na consulta po?s-operato?ria, a ferida estava\ntotalmente cicatrizada, sem evide?ncias de leso?es residuais e o resultado do histopatolo?gico\nevidenciou um melanoma nodular ni?vel II de Clark e Breslow de 0,7mm. Diante deste resultado, a\nmelhor conduta e?:","options":{"A":"Indicar nova cirurgia com ampliac?a?o de margem oncolo?gica para 3 cm.","B":"Considerar que a cirurgia foi adequada e orientar o seguimento ambulatorial.","C":"Indicar a realizac?a?o de linfadenectomia regional, interferon ?-2b e radioterapia.","D":"Indicar e encaminhar o paciente para realizac?a?o de pesquisa de linfonodo sentinela."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-234028","number":"234028","sourceNumber":"234028","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 32 anos procurou assiste?ncia me?dica, ha? 10 dias, por quadro de disu?ria\ne polaciu?ria, sendo tratada com sulfametoxazol e\ntrimetoprim. Ha? 5 dias, passou a apresentar\nfebre alta, dor em orofaringe e eritema em conjuntivas bilateralmente. Apo?s um dia do ini?cio do\nquadro, percebeu manchas eritematosas inicialmente em tronco que, em menos de 24 horas,\nacometeram tambe?m extremidades. Em a?reas de atrito, as leso?es evolui?ram com\nescurecimento central e bolhas. Procurou novamente atendimento, apresentando leso?es\nvisualizadas na figura A. Diante do prova?vel diagno?stico, qual o cena?rio adequado e quais as\nmedidas de tratamento, respectivamente?","options":{"A":"Enfermaria ? imunoglobulina endovenosa e corticoterapia sistêmica.","B":"Unidade de Terapia Intensiva ? antibioticoterapia endovenosa e tópica.","C":"Unidade de queimados ? cuidados de suporte e vigilância para infecções secundárias.","D":"Unidade de Terapia Intensiva ? corticoterapia endovenosa e depois oral até resolução."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/234028.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-234029","number":"234029","sourceNumber":"234029","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem de 48 anos iniciou, há 20 dias, uso de poliquimioterapia (PQT) multibacilar,\nincluindo dapsona, clofazimina e rifampicina, para\ntratamento de hanseníase forma dimorfa\nvirchowiana. Há 2 dias, passou a apresentar febre baixa, astenia, dor ocular bilateral, mialgia e\nlesões cutâneas dolorosas. Nega perda de força muscular. Ao exame, apresentava-se febril,\nnormocorado, anictérico, acianótico e exame dermatológico revelava nódulos eritematosos em\nmembros. Diante do provável diagnóstico do quadro mais recente apresentado pelo paciente, qual\na conduta mais recomendada neste momento?","options":{"A":"Manter PQT e iniciar talidomida oral.","B":"Manter PQT e iniciar prednisona 1mg/kg.","C":"Suspender dapsona e substituir por ofloxacina.","D":"Suspender dapsona e iniciar azul de metileno venoso."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-234071","number":"234071","sourceNumber":"234071","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 72 anos comparece à Unidade Básica de Saúde queixando-se de dor\nmoderada, em queimação, em faces dorsal,\nlateral e anterior do hemitórax esquerdo há dois dias.\nNega comorbidades ou outros sintomas. Ao exame: Peso = 70 kg; Estado geral regular; à inspeção,\nsão vistas as lesões a seguir (foto). Restante do exame físico normal. Está em uso de dipirona e\nanti-inflamatório não hormonal com controle parcial da dor. Qual das opções define corretamente o\ntratamento recomendado para este caso?","options":{"A":"Aciclovir 800 mg via oral cinco vezes ao dia por uma semana.","B":"Valaciclovir 500 mg via oral duas vezes ao dia por uma semana.","C":"Ganciclovir 350 mg intravenoso duas vezes ao dia por três semanas.","D":"Fanciclovir 500 mg via oral três vezes ao dia até a cicatrização das lesões."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/234071.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-199756","number":"199756","sourceNumber":"199756","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, masculino, 38 anos, agricultor, procedente de Baturité, procura atendimento\nmédico por apresentar, há 4 meses, nódulo\neritematoso em perna esquerda de crescimento\nprogressivo. Apesar de ter evoluído para úlcera há 1 semana, a lesão continua sendo\nassintomática. Nega outras lesões cutâneas. Nega sintomas sistêmicos. Ao exame dermatológico,\nobserva-se úlcera arredondada com 2 cm de diâmetro, localizada no terço médio de região\n\npré-tibial da perna esquerda. A lesão é bem delimitada e possui bordas eritematosas elevadas e\nfirmes, além de fundo recoberto parcialmente por fina camada de fibrina. Diante do diagnóstico\nprovável para o paciente descrito acima, qual a técnica de primeira escolha para a confirmação\nlaboratorial do diagnóstico, nesse caso?","options":{"A":"Sorologia para leishmania, por apresentar alta sensibilidade e especificidade.","B":"Intradermoreação de montenegro, por sua elevada sensibilidade em lesões precoces.","C":"Reação de Polimerase em Cadeia (PCR), por permitir identificação da espécie do parasita.","D":"Escarificação da lesão para pesquisa direta do parasita, por ser rápido e ter alta\nsensibilidade."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-199710","number":"199710","sourceNumber":"199710","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um adolescente comparece à unidade de atenção primária com queixa de manchas\navermelhadas pruriginosas difusas de surgimento há cerca de duas horas. Evolui há 2 dias com\nfebre baixa, coriza hialina e tosse seca. A mãe informa que está fazendo uso de lambedor e\ndipirona gotas para melhorar os sintomas e que o filho encontra-se ansioso porque necessita\nestudar para uma prova no colégio. Relata que já apresentou outros episódios em que inchou o\nlábio superior e olho direito com antitérmico. Ao exame: placas eritematosas, edemaciadas,\npredominantemente em tronco e membros superiores. Frequência respiratória = 16 rpm; pulso = 82\nbpm; pressão arterial = 110 x 70 mmHg. Ausculta cardiorrespiratória sem anormalidades. Qual\nmedicação deve ser utilizada inicialmente para tratamento dos sintomas cutâneos?","options":{"A":"Prometazina.","B":"Prednisona.","C":"Loratadina.","D":"Epinefrina."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-199671","number":"199671","sourceNumber":"199671","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem, 71 anos, em situação de rua, procura unidade de saúde com queixa de dor\nconstante em queimação na região dorsal\nesquerda há 6 meses. Relata que no início do quadro\napresentou febre baixa, mal-estar e astenia, associado a dor, hipersensibilidade ao contato com a\nroupa e dormência na mesma localização da dor atual, uma faixa na região dorsal esquerda. Relata\nque após 1 dia do início do quadro surgiram lesões na pele nesta mesma localização. Descreveu as\nlesões como pequenas bolhas que evoluíram para crostas e desapareceram após 3 semanas. Ao\nexame físico, apresenta alodínia em território de T4 sem lesões atuais. Para o manejo da dor, qual\ndeve ser a terapêutica medicamentosa de primeira escolha?","options":{"A":"Tramadol.","B":"Fluoxetina.","C":"Prednisona.","D":"Amitriptilina."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-199734","number":"199734","sourceNumber":"199734","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança, 6 anos, é levada pela mãe à consulta de demanda espontânea em unidade\nbásica de saúde devido a coceira e\nvermelhidão em calcanhar direito após fim de semana em casa\nde praia. Observando a imagem, qual a melhor conduta medicamentosa?","options":{"A":"Loratadina 5 mg/dia durante 5 dias.","B":"Griseofulvina 10 mg/kg/dia durante 4 semanas.","C":"Aciclovir 20 mg/kg/dose 4 vezes ao dia durante 5 dias.","D":"Albendazol 400 mg/dia durante 3 dias."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/199734.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172994","number":"172994","sourceNumber":"172994","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, masculino, 58 anos, procura atendimento médico, após esposa ter percebido\nnódulo no dorso com crescimento progressivo há 3 meses. Nega lesões prévias ou trauma nesta\ntopografia. Nega sintomas locais associados. Ao exame dermatológico, observa-se lesão nodular\nexofítica eritematosa de consistência firme, com superfície exulcerada, medindo aproximadamente\n2 cm em seu maior diâmetro. Não apresenta alteração de cor ou de textura ao redor da lesão.\n\nConsiderando o diagnóstico diferencial da lesão descrita no caso acima, responda corretamente.","options":{"A":"A evolução e a localização sugerem o diagnóstico de um carcinoma basocelular nodular","B":"O diagnóstico de melanoma nodular prejudica a utilização da regra ABCDE para detecção\nprecoce.","C":"O diagnóstico de melanoma é pouco provável por se tratar de área exposta ao sol de forma\nesporádica.","D":"O diagnóstico de melanoma é pouco provável, pela ausência de nevo melanocítico antecedendo\na lesão"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172984","number":"172984","sourceNumber":"172984","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em visita puerperal, a equipe de saúde observa que um recém-nascido de 15 dias\napresenta irritabilidade e dificuldade em mamar.\nNão há febre ou sintomas respiratórios, e as\nfunções eliminatórias estão normais. Ao exame, observa-se eritema máculo-papular em face,\nregião occipital, dorso e tórax (foto). A mãe apresenta lesões semelhantes nas mãos, mamas e\nsulcos inframamários com prurido mais intenso a noite. Qual a melhor opção terapêutica para essa\ncriança?","options":{"A":"Loção de Permetrina a 5%.","B":"Creme de Cetoconazol a 2%.","C":"Creme de Dexametasona a 0,1%.","D":"Loção de Enxofre Precipitado a 5%."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/172984.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-150835","number":"150835","sourceNumber":"150835","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 45 anos, com antecedente familiar de melanoma cutâneo, apresentando\nlesão hipercrômica em coxa, 0,5 cm de diâmetro (foto),\nsem linfonodos suspeitos na região de\ndrenagem. (VER IMAGEM) Qual a conduta mais adequada?","options":{"A":"Biópsia com 1 mm de margem cirúrgica.","B":"Biópsia com 5 mm de margem cirúrgica.","C":"Biópsia com 10 mm de margem cirúrgica.","D":"Ressecção com estudo do linfonodo sentinela."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/150835.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-150810","number":"150810","sourceNumber":"150810","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem de 50 anos procura unidade básica de saúde por lesões de pele percebidas há\nseis meses. Ao exame, duas placas eritematosas em tórax, de bordos infiltrados e bem definidos,\ncom rarefação pilosa. Teste de sensibilidade térmica alterado. Resultados de exames prévios feitos\nem outra unidade de saúde: hemograma: normal; testes de função hepática e renal: normais;\n\nanti-HIV: não reagente; exame micológico direto e cultura para fungos: negativos; baciloscopia da\nlinfa e lesões: negativa. Diante do quadro apresentado, qual a conduta recomendada?","options":{"A":"Repetir baciloscopia e solicitar teste de Mitsuda.","B":"Iniciar dapsona diária e dapsona + rifampicina mensais.","C":"Repetir baciloscopia e solicitar biópsia com histopatológico.","D":"Iniciar clofazimina diária e clofazimina + rifampicina mensais."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-150821","number":"150821","sourceNumber":"150821","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma criança de dois anos de idade chega ao pronto-socorro nos braços de seu genitor\ncom cianose central e periférica, além de\nestridor inspiratório. Com poucas perguntas o médico fica\nsabendo que o quadro de estridor iniciou há cerca de 20 minutos, logo após o despertar da criança;\na mesma estava bem de saúde, sem quadro infeccioso e nunca havia tido quadro semelhante. Não\nse evidenciou alterações na pele nem se chegou a ideias plausíveis sobre o provável\ndesencadeante. A criança recuperou após de injeções de adrenalina intramuscular. Qual a principal\nhipótese diagnóstica?","options":{"A":"Estridor por anafilaxia.","B":"Estridor por laringite viral.","C":"Estridor por laringite espasmódica.","D":"Estridor por aspiração de corpo estranho."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-150869","number":"150869","sourceNumber":"150869","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adolescente é atendido no serviço de atenção primária, por lesão na região periungueal\nno segundo quirodáctilo direito que teve início\nhá menos de 48 horas. Há dor à manipulação e se\npercebe intenso edema em região proximal e lateral da prega ungueal. Não se observa abcesso.\n\nQual a primeira conduta a ser feita para o tratamento da lesão?","options":{"A":"Antibiótico tópico em associação com corticoide.","B":"Antibiótico oral com cobertura para estafilococos.","C":"Imersões em água morna três a quatro vezes ao dia.","D":"Compressas frias e manutenção da área sob proteção."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-126937","number":"126937","sourceNumber":"126937","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 38 anos queixa-se de prurido intenso em dobras cutâneas nos\nmembros superiores e inferiores, sobretudo nas\nregiões dos antebraços (VER IMAGEM). O\nquadro já dura cerca de dois meses sem melhora substancial com uso de hidratantes.\n\nRelata fazer tratamento frequente para crises de rinite alérgica e teve asma na infância. Qual o\ndiagnóstico mais provável?","options":{"A":"Psoríase.","B":"Líquen plano.","C":"Dermatofitose.","D":"Dermatite atópica."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/126937.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-126975","number":"126975","sourceNumber":"126975","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma criança de quatro anos de idade vem apresentando há alguns meses\nprurido na pele com inquietação e\ndificultando o sono; grande parte das superfícies do tronco e\ndo abdome estão com pele ressecada, crostas e eritema. Há lesões similares na face. Das\nopções abaixo, que grupo de medicamentos tópicos são úteis no tratamento para essa criança?","options":{"A":"Antiparasitários.","B":"Imunomoduladores.","C":"Antifúngicos.","D":"Ceratolíticos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-127017","number":"127017","sourceNumber":"127017","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 27 anos de idade, masculino, com diagnóstico de hanseníase, chega para\no seguimento com seu médico de família e\ncomunidade, no quarto mês de tratamento com\npoliquimioterapia. Ele demonstra muita preocupação, pois surgiram novas lesões do tipo\neritematosas, edemaciadas, que alternam com áreas de pele sadia. Apresenta bom estado geral,\nsem história de febre. (VER IMAGEM) Qual a conduta medicamentosa para esse paciente?","options":{"A":"Prescrever prednisona (1-1,5 mg/kg/dia) e suspender a poliquimioterapia específica.","B":"Prescrever prednisona (1-1,5 mg/kg/dia) e manter a poliquimioterapia específica.","C":"Prescrever talidomida (100-400 mg/dia) e suspender a poliquimioterapia específica.","D":"Prescrever talidomida (100-400 mg/dia) e manter a poliquimioterapia específica."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/127017.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-127011","number":"127011","sourceNumber":"127011","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em uma atividade de extensão com pessoas em situação de rua, você é chamado por\num dos estudantes para avaliar Emanuel, 35 anos, que apresenta várias lesões papulonodulares\ncom pontos enegrecidos no centro, medindo de 4 a 8 mm de diâmetro na região ventral dos\npododáctilos e na região plantar de ambos os membros inferiores (VER IMAGEM). Qual o\ntratamento indicado?","options":{"A":"Realizar biópsia das lesões.","B":"Realizar cauterização das lesões.","C":"Realizar enucleação de algumas das lesões e prescrever ivermectina.","D":"Cobrir as lesões com vaselina para removê-las no dia seguinte e prescrever antimicrobianos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/127011.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-102158","number":"102158","sourceNumber":"102158","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Escolar de sete anos é trazido à Unidade Básica de Saúde apresentando lesão de pele\nem braço direito há três semanas, tendo usado creme de dexametasona e pomada de neomicina,\nsem resultados. As lesões são eritemato-descamativas de bordos circinados. Apresenta discreto\nprurido e nenhum dos familiares está acometido (VER IMAGEM). Qual o diagnóstico e qual a\nmelhor opção terapêutica?","options":{"A":"Ptiríase alba ? loção hidratante e protetor solar.","B":"Impetigo ? creme de mupirocim ou ácido fusídico.","C":"Tinea corporis ? creme de miconazol ou ciclopirox.","D":"Escabiose ? solução de permetrina a 2% em todos os familiares."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/102158.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-81246","number":"81246","sourceNumber":"81246","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, de 72 anos, agricultora e fumante desde os 16 anos, tem história pregressa\nde transplante renal há 10 anos, apresentando\ntumoração de pele com ulceração central,\ncrescendo há 2 anos (VER IMAGEM). Assinale a alternativa correta quanto ao provável\ndiagnóstico, prognóstico e conduta.","options":{"A":"Parece uma lesão maligna, mas nem todos os dados da história corroboram para o diagnóstico.\n\nPrognóstico de cura é baixo após ressecção com margem de 10 mm, se as células forem bem\ndiferenciadas.","B":"Parece um carcinoma basocelular e todos os dados da história corroboram com o diagnóstico.\n\nPrognóstico de cura é alto após ressecção com margem de 05 mm, se as células forem bem\ndiferenciadas.","C":"Parece um querato-acantoma e todos os dados da história corroboram com o diagnóstico.\n\nPrognóstico\n\nde cura é alto após ressecção com margem de 05 mm, se as células forem bem diferenciadas.","D":"Parece um carcinoma espino-celular e todos os dados da história corroboram com o diagnóstico.\n\nPrognóstico de cura é alto após ressecção com margem de 10 mm, se as células forem bem\ndiferenciadas."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/81246.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-81274","number":"81274","sourceNumber":"81274","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 50 anos queixa-se de lesões em membros inferiores (VER IMAGEM) de\ninício há duas semanas, associadas à febre\ndiária de 38°C ao fim das tardes, e dores em joelhos e\ntornozelos. Refere ter concluído tratamento de hanseníase há 1 ano (fez uso de poliquimioterapia\npor 12 meses) e não teve problemas de saúde desde então. Não faz uso de medicações ou de\nsubstâncias ilícitas. Qual dos tratamentos abaixo é o mais recomendado nesse caso?","options":{"A":"Dapsona 100 mg/dia.","B":"Prednisona 10 mg/dia.","C":"Talidomida 300 mg/dia.","D":"Rifampicina 600 mg/dia + dapsona 100 mg/dia."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-81261","number":"81261","sourceNumber":"81261","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Escolar é trazido à Unidade de Saúde após várias tentativas de tratamento de\nlesões pruriginosas que apresentaram agravamento\nnos últimos dias. Sua mãe relata que a\ncriança faz uso contínuo de corticoide por Síndrome Nefrótica. Recebeu diagnóstico de escabiose\ne algumas pessoas da casa estão acometidas. As lesões tornaram-se descamativas, crostosas,\ncom queratodermia, acometendo couro cabeludo, mãos e pés, como na imagem abaixo. (VER\nIMAGEM). Qual o diagnóstico e tratamento corretos?","options":{"A":"Dermatite Atópica; hidratação e creme de corticoide.","B":"Sarna norueguesa; permetrina tópica e ivermectina oral.","C":"Dermatite seborreica; compressas de água boricada e creme de corticoide.","D":"Impetigo; compressas de Permanganato de Potássio 1:40.000 e creme de antibiótico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/81261.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-81302","number":"81302","sourceNumber":"81302","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um garoto de 12 anos de idade apresenta lesão intensamente pruriginosa na face\nlateral do pé direito. (VER IMAGEM). Ele acha\nque tudo começou após um jogo de futebol, do qual\nparticipou há cerca de 10 dias num campo de grama. Qual o tratamento adequado?","options":{"A":"Griseofulvina, via oral.","B":"Tiabendazol, pomada.","C":"Monossulfiram diluído, tópico.","D":"Permanganato de potássio diluído a 1:40.000, tópico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/81302.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-65750","number":"65750","sourceNumber":"65750","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 72 anos procurou médico com lesão escurecida de pele, de pigmentação e\nbordas irregulares, de crescimento lento. A biópsia mostrou melanoma com 1 mm de espessura. O\ndiagnóstico e prognóstico mais prováveis são:","options":{"A":"Melanoma nodular; pior prognóstico em relação aos demais.","B":"Melanoma lentiginoso acral; pior prognóstico em relação aos demais.","C":"Melanoma lentiginoso benigno; melhor prognóstico em relação aos demais.","D":"Melanoma lentiginoso maligno; melhor prognóstico em relação aos demais.","E":"Melanoma extensivo superficial; melhor prognóstico em relação aos demais."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-65788","number":"65788","sourceNumber":"65788","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"<p>Mulher de 32 anos, com hepatite C crônica, apresenta pápulas violáceas,\npruriginosas, com fina rede de linhas\nbranco-acinzentadas na superfície, acometendo as faces\nflexoras dos punhos. As unhas das mãos estão acometidas, sobretudo as dos polegares. Qual o\ndiagnóstico mais compatível com este quadro? (VER IMAGEM)</p>","options":{"A":"Psoríase.","B":"Líquen plano.","C":"Pitiríase rósea.","D":"Dermatofitose.","E":"Eczema disidrótico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/65788.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-65715","number":"65715","sourceNumber":"65715","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 12 anos, internada com quadro de edema, eritema e dor na região\nperiorbitária do olho esquerdo, refere que,\nnos últimos dias, de modo estranho, não consegue\nmovimentar o olho esquerdo, preferindo mantê-lo fechado, evitando com isso ver duas imagens.\nQuando examinado, o paciente encontra-se com as pupilas centradas, e a diplopia piora ao olhar\npara a direita ou para a esquerda; demonstra também deficiência na abdução do olho esquerdo.\nDiante do descrito, qual o diagnóstico clínico, a causa da complicação observada e a\nantibioticoterapia indicada?","options":{"A":"Celulite orbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-positivas.","B":"Celulite periorbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-negativas.","C":"Celulite periorbital; paralisia do III par craniano por extensão do processo; cobertura para\ncepas\nGram-positivas e Gram-negativas.","D":"Celulite orbital; paralisia do III par craniano por extensão do processo; cobertura para cepas\nGram-positivas, Gram-negativas e anaeróbias.","E":"Celulite orbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-positivas, Gram-negativas e anaeróbias."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-65692","number":"65692","sourceNumber":"65692","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adulto, sexo masculino, em acompanhamento na atenção primária para tratamento de\nhanseníase iniciado há 2 meses, em uso de rifampicina, dapsona e clofazimina, comparece ao\ncentro de saúde da família, relatando aparecimento recente de nódulos vermelhos e dolorosos em\nface, tronco e membros superiores associados à febre, astenia, mialgia e artralgia. Ante o\nenunciado, qual o tratamento farmacológico mais indicado?","options":{"A":"Prednisona.","B":"Itraconazol.","C":"Talidomida.","D":"Azatioprina.","E":"Ciclofosfamida."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51173","number":"51173","sourceNumber":"51173","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem de 46 anos comparece para consulta com quadro de bolhas e erosões nos\nolhos e boca, junto com lesões eritematosas\nmultiformes em face e tronco. Exame físico: lesões de\npele descritas e adenomegalia cervical. Qual o diagnóstico mais provável?","options":{"A":"Lúpus bolhoso.","B":"Dermatite herpetiforme.","C":"Pênfigo paraneoplásico.","D":"Dermatose bolhosa com IgA linear."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51174","number":"51174","sourceNumber":"51174","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 30 anos, portador de HIV, apresenta lesões de pele eritematosas e\ndescamativas, com escamas amareladas em couro cabeludo, região retroauricular, pálpebras,\nsobrancelhas e sulco nasolabial. Nega prurido. Iniciou terapia antirretroviral há seis meses, por\nredução do número de linfócitos CD4+ no sangue e correlaciona o período do início do tratamento\ncom a piora das lesões. Qual a etiologia mais provável para estas lesões?","options":{"A":"Psoríase.","B":"Dermatite seborreica.","C":"Foliculite eosinofílica.","D":"Reação aos antirretrovirais."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51172","number":"51172","sourceNumber":"51172","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente é trazido ao Posto de Saúde por sua mãe, que relata o surgimento de lesões\nde pele na região do queixo e narinas, as\nquais se disseminam em pouco tempo para as mãos e\ntronco, com vermelhidão e pus. Refere que há 48 horas a criança vem apresentando febre e\n\"íngua\". Quais os agentes etiológicos e o tratamento deste caso?","options":{"A":"Candida albicans ? nistatina oral por 7 dias, compressas de permanganato de potássio a\n1:40.000 e pomada de nistatina nas lesões.","B":"Escherichia coli e Klebsiella pneumoniae ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de nistatina nas lesões.","C":"Escherichia coli e Staphylococcus aureus ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de nistatina ou miconazol nas lesões.","D":"Streptococcus do grupo A e Staphylococcus ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de neomicina, mupirocin ou ácido fusídico nas\nlesões."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51209","number":"51209","sourceNumber":"51209","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sabe-se que os melanomas possuem uma incidência mais elevada em homens e\nnegros, ocorre significativamente entre a 3ª e\n4ª décadas de vida e que a exposição solar excessiva\naumenta o risco de desenvolver melanoma nas populações suscetíveis. Qual das alternativas\nabaixo corresponde a um fator adicional que aumenta mais ainda o risco de desenvolvimento de\num melanoma?","options":{"A":"Ceratose actínica.","B":"Doença de Bowen.","C":"Papiloma verrucoso.","D":"Xerodermia pigmentosa."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51295","number":"51295","sourceNumber":"51295","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao ?Fenômeno de Lúcio? na hanseníase, podemos afirmar o seguinte:","options":{"A":"Caracteriza-se como vasculite e paniculite com muitos linfócitos, poucos bacilos e sem área de\nnecrose.","B":"Representa uma variante da reação hansênica tipo 1 que pode ocorrer no início do tratamento\ncom poliquimioterapia.","C":"Trata-se de reação observada mais comumente na forma virchowiana no início do tratamento\ncom poliquimioterapia.","D":"Caracteriza-se clinicamente por múltiplas placas purpúricas dolorosas e bolhas hemorrágicas\nque evoluem para lesões necróticas e ulceradas."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51213","number":"51213","sourceNumber":"51213","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pré-escolar é trazido ao Centro de Saúde apresentando lesões no couro cabeludo,\nconforme imagem. (VER IMAGEM) Qual o diagnóstico e tratamento adequados?","options":{"A":"Eczema atópico ? loção de corticoide durante 1 semana.","B":"Tinha do couro cabeludo ? griseofulvina 10-20 mg/kg/dia durante 45 dias.","C":"Piodermite do couro cabeludo ? cefalosporina oral 40 mg/kg/dia durante 7 dias.","D":"Dermatite seborreica ? xampu de sulfeto de selênio a 2,5% em dias alternados, durante 30 dias."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/51213.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-51264","number":"51264","sourceNumber":"51264","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente adulto comparece à unidade básica de saúde relatando aparecimento de\nlesões em braços e dorso nos últimos 60\ndias. Ao exame, o médico de família detecta 8 lesões de\npele, todas com alteração de sensibilidade. Além disso, identifica espessamento de nervos ulnares.\nNenhum grau de incapacidade física foi identificado. Considerando o caso acima, qual deve ser a\nconduta terapêutica?","options":{"A":"Poliquimioterapia com rifampicina + dapsona por 6 meses.","B":"Poliquimioterapia com rifampicina + dapsona por 12 meses.","C":"Poliquimioterapia com rifampicina + dapsona + clofazimina por 12 meses.","D":"Poliquimioterapia com rifampicina + dapsona + clofazimina por 18 meses."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-36975","number":"36975","sourceNumber":"36975","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a cicatrização de feridas, qual a assertiva correta?","options":{"A":"Infecção de ferida operatória pode resultar em cicatrização por terceira intenção.","B":"As três fases da cicatrização são denominadas inflamatória, proliferativa e regenerativa.","C":"Hemoglobina de 9 g/dl é um fator que inibe a cicatrização da ferida operatória.","D":"Cicatriz hipertrófica ou queloide está associada com excessiva degradação do colágeno."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-37434","number":"37434","sourceNumber":"37434","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às lesões de pele, assinale a alternativa correta:","options":{"A":"A coloração das lesões, a localização, seu arranjo e número são fundamentais para o\nestabelecimento da etiologia. Na dermatite atópica as lesões são eritematosas, enquanto que a\nfoliculite aparece como pequenas pápulas em áreas cobertas (glúteos e abdome).","B":"A aparência morfológica das lesões, sua localização, seu arranjo e número são fundamentais\npara o estabelecimento da etiologia. Na\ndermatite de contato aparecem vesículas maiores de 1 cm\ncom conteúdo seroso, enquanto que na urticária as lesões são lineares.","C":"A aparência morfológica das lesões, sua localização, seu arranjo e número são fundamentais\npara o estabelecimento da etiologia. Na\npsoríase as lesões são coalescentes e localizadas nos\nmembros, enquanto que a ceratose actínica aparece nas áreas expostas ao sol.","D":"A coloração das lesões, a localização, seu arranjo e número são fundamentais para o\nestabelecimento da etiologia. Nos xantomas\nas lesões são bolhas com conteúdo branco, enquanto\nque o Herpes-zóster se manifesta por pústulas coalescentes.","E":"A aparência morfológica das lesões, sua localização, seu arranjo e número são fundamentais\npara o estabelecimento da etiologia. O\ncarcinoma basocelular aparece como lesão\npapuloescamosa, enquanto que o vitiligo apresenta placas hipocrômicas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-37638","number":"37638","sourceNumber":"37638","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Recentemente, foi validado por Williams e colaboradores, um conjunto de critérios para\naplicação na prática diária do diagnóstico da dermatite atópica. Nessa forma de classificação, o\npaciente tem prurido junto com mais três dos seguintes achados, exceto:","options":{"A":"história de dermatite flexural;","B":"pele seca;","C":"colonização pelo Staphylococcus aureus;","D":"eczema presente;"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-30902","number":"30902","sourceNumber":"30902","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 56 anos procura atendimento por lesões cutâneas dolorosas no tórax. Há 72\nhoras passou a apresentar dor em queimação na região torácica inferior esquerda. Desde então\nvem fazendo uso regular de comprimidos de cetoprofeno com melhora parcial. Há cerca de 24\nhoras passou a apresentar lesões na zona inframamária esquerda, impedindo-a de usar sutiã. Ao\nexame físico apresenta vesículas tensas e agrupadas em região inferior à aréola esquerda e\nsuperior ao rebordo costal esquerdo, desde o esterno até a região dorsal posterior esquerda; sem\noutros achados. Qual o tratamento isoladamente mais apropriado para este caso?","options":{"A":"Aciclovir 200mg VO 8/8h.","B":"Prednisona 20mg VO 1x/dia.","C":"Hidrocortisona creme tópico 2x/dia.","D":"Valaciclovir 1g VO 3x/dia.","E":"Suspender uso de cetoprofeno."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27758","number":"27758","sourceNumber":"27758","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à transmissão da hanseníase, assinale a FALSA.","options":{"A":"O homem é o único reservatório conhecido","B":"São fontes de infecção somente os doentes que apresentam bacterioscopia positiva","C":"O doente de hanseníase deixa de ser fonte de infecção após dois meses de tratamento com\nmedicamentos bactericidas","D":"Em geral, considera-se que as vias respiratórias superiores sejam a principal porta de entrada","E":"É possível a penetração do bacilo pela pele com solução de continuidade"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25303","number":"25303","sourceNumber":"25303","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Cicatrizes hipertróficas e queloides são processos anormais de cicatrização\ncaracterizados por alterações: Qual a melhor resposta?","options":{"A":"na migração e proliferação de células, alteração no remodelamento da matriz sintetizada.","B":"na migração e proliferação de células, inflamação, aumento na síntese de citocinas.","C":"na proliferação de células, inflamação, aumento na síntese de citocinas e proteínas da matriz\nextracelular.","D":"na migração e proliferação de células, proteínas da matriz extracelular.","E":"na migração e proliferação de células, inflamação, aumento na síntese de citocinas e proteínas\nda matriz extracelular e remodelamento da matriz\nsintetizada."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-29465","number":"29465","sourceNumber":"29465","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Para o diagnóstico de hanseníase, é necessária a presença de uma ou mais das\nseguintes características, EXCETO:","options":{"A":"Madarose com baciloscopia positiva;","B":"Dor e espessamento dos nervos periféricos;","C":"Presença de cinco ou mais lesões hipocrômicas com baciloscopia negativa;","D":"Lesão (ões) de pele com alteração de sensibilidade com baciloscopia negativa."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25311","number":"25311","sourceNumber":"25311","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Nos enxertos, qual o tempo em que se processa a sua revascularização:","options":{"A":"12h","B":"24h","C":"36h","D":"48h","E":"60h"},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25312","number":"25312","sourceNumber":"25312","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ainda sobre enxertos, qual das afirmações abaixo é correta?","options":{"A":"a velocidade normal de fluxo sanguíneo no enxerto é atingida em 20 a 30 dias.","B":"a reinervação nunca ocorre.","C":"a reinervação ocorre nos primeiros meses nos enxertos de pele total.","D":"a reinervação ocorre nos primeiros dias e a espessura do enxerto não é importante.","E":"a velocidade normal de fluxo sanguíneo no enxerto é atingida em 7 a 10 dias."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-29447","number":"29447","sourceNumber":"29447","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pedro Paulo, 32 anos, casado, engenheiro agrônomo, residente em Sobral, procura seu\nmédico de família com queixa de lesão eritematoescamosa com bordas nítidas em região inguinal,\nextensa, acometendo o períneo e a região glútea, bilateral. Referiu prurido intenso que provocou\nliquenificação e escurecimento da área. Baseando-se no caso acima e em seus conhecimentos,\nassinale a alternativa CORRETA:","options":{"A":"O diagnóstico mais provável é tungíase e o tratamento consiste em remoção da pulga com a\nagulha esterelizada;","B":"O diagnóstico mais provável é miíase furunculóide e o tratamento consiste em asfixia da larva\natravés de oclusão do orifício com esparadrapo largo por 24 horas;","C":"O diagnóstico mais provável é tinha do corpo e um dos tratamentos mais efetivos é o itraconazol\nem pulsos de 400 mg/dia, sete dias por mês,\ndurante dois meses;","D":"O diagnóstico mais provável é tinha crural e um dos tratamentos mais efetivos é o itraconazol\n100 mg/dia, de um a dois meses."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-29460","number":"29460","sourceNumber":"29460","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Cláudia, 15 anos, procurou seu médico de família com queixa de acne. Cláudia refere\nque a acne a incomoda muito, pois sente-se\nfeia. Ao examiná-la, o médico encontrou peso: 50 Kg,\nestatura: 1,58 cm, Tanner M4P4, presença de comedões, pápulas eritematosas e pústulas. Após a\nleitura do caso acima assinale a alternativa CORRETA:","options":{"A":"Cláudia possui acne papulopustulosa, doença inflamatória aguda da unidade pilosebácea;","B":"O médico de família deve encaminhá-la para serviço de dermatologia, visto que o tratamento\nconsiste na administração oral de\nisotretinoína;","C":"O médico de família deve solicitar RX de punho esquerdo, pois a classificação de Tanner revela\npuberdade precoce;","D":"Nenhuma das alternativas acima."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27679","number":"27679","sourceNumber":"27679","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma menina de 4 anos de idade é atendida apresentando febre e erupção cutânea. A\nfebre apareceu há 6 dias, junto com uma dor de garganta, olhos secos e lábios rachados. Hoje, a\ncriança se apresenta cansada e com temperatura de 38,8°C. As conjuntivas estão edemaciadas\nbilateralmente, e não há linfoadenopatia cervical e eritema das mãos e dos pés. A pele dos pés\nestá descascando, como se tivesse sido gravemente queimada. A primeira conduta a tomar neste\ncaso é:","options":{"A":"administrar ácido acetilsalicílico 80 mg/kg/dia por 48 horas, via intravenosa (IV) e\ngamaglobulina\npor 2 semanas.","B":"colher hemocultura e iniciar ampicilina e ceftriaxona IV, agora.","C":"altas doses de corticosteroide IV agora.","D":"administrar gamaglobulina e ácido acetilsalicílico 80 mg/kg/dia agora.","E":"realizar eletroforese de proteínas na urina e no plasma."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25400","number":"25400","sourceNumber":"25400","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual o tipo histológico mais comum do câncer de pênis?","options":{"A":"Sarcoma","B":"Melanoma","C":"Carcinoma de células escamosas","D":"Adenocarcinoma","E":"Carcinoma verrucoso"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25360","number":"25360","sourceNumber":"25360","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 55 anos é acompanhada por hipertensão arterial sistêmica (HAS) em uso\nde hidroclorotiazida há 5 anos. Nos últimos 6\nmeses, vem apresentado mau controle da pressão\narterial e decide-se associar captopril após avaliação que não detectou sinais de HAS secundária.\nApós 1 mês de uso da combinação, paciente evolui com angioedema facial. Assinale o item abaixo\nque descreve a conduta adequada nesta paciente:","options":{"A":"Deve-se suspender o captopril e reintroduzi-lo aos poucos após 4 a 6 semanas","B":"Deve-se substituir o captopril por outra droga da mesma classe","C":"Deve-se suspender permanentemente o uso de inibidores da ECA nesta paciente","D":"Deve-se manter o esquema e administrar anti-histamínicos até resolução completa","E":"Deve-se associar o captopril a outra droga que não a hidroclorotiazida"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-25362","number":"25362","sourceNumber":"25362","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 23 anos procura atendimento por lesões cutâneas compatíveis com\ndermatite herpetiforme. Avaliação laboratorial\nevidenciou hemoglobina de 9 g/dL, VCM = 67 fL.\nSem outros achados alterados. Dos exames abaixo, selecione o melhor teste inicial para a provável\npatologia deste paciente:","options":{"A":"Pesquisa de anticorpo antigliadina","B":"PCR para Herpes vírus","C":"PCR para Varicela-zóster vírus","D":"Pesquisa de anticorpo IgA antitransglutaminase","E":"Pesquisa de anticorpo IgG antiendomísio"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-7298","number":"7298","sourceNumber":"7298","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente de 55 anos apresenta prurido generalizado, principalmente nas regiões\nplantar e palmar há dois anos, há um ano, notou xantelasma bilateralmente. Durante exames\nlaboratoriais, a positividade de anticorpos antimitocondriais favorece a hipótese de:","options":{"A":"hepatite crônica persistente.","B":"amiloidose hepática.","C":"cirrose biliar primária.","D":"carcinoma hepático.","E":"N.R.A."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-9121","number":"9121","sourceNumber":"9121","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Forma clínica da hanseníase, dita forma instável da doença, que se situa entre os tipos\ntuberculoide e virchowiano, e sendo instáveis quanto à sua resistência, alguns desses doentes\nsomente irão definir sua forma clínica ao longo do tempo:","options":{"A":"Dimorfa.","B":"Virchowiana.","C":"Indeterminada.","D":"Tuberculoide."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-13461","number":"13461","sourceNumber":"13461","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, sexo feminino, 47 anos, há 4 meses usando dapsona, clofazimina e\nrifampicina. Há 4 dias, refere piora das\ntrês lesões de pele no abdome e braço direito (hiperemiadas\ne bordas elevadas). A palpação da goteira epitrocleana direita é muito dolorosa. Qual a conduta\nmais adequada?","options":{"A":"Prednisona.","B":"Talidomida.","C":"Suspender dapsona.","D":"Suspender clofazimina.","E":"Itraconazol."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-6980","number":"6980","sourceNumber":"6980","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Durante reunião de avaliação da sua equipe, identifica-se que ectoparasitoses como a\nescabiose, a pediculose, a ftiríase e a tungíase vêm representando um problema de difícil controle\nna comunidade. Tomando como referência o manejo dessas condições, pode-se afirmar que:","options":{"A":"Após o tratamento específico da escabiose com ivermectina em dose única, deve-se afastar o\ncaso da escola ou do trabalho até 24 horas após o término do tratamento. No caso de paciente\ninternado, recomenda-se o isolamento durante 24 a 48 horas após o término do tratamento.","B":"O tratamento específico para pediculose com o uso de xampu de permetrina (5%) ou\ndeltametrina (0,2%) deve ser realizado em\naplicação única e repetição após sete dias. Como os\npiolhos podem viver até três dias em fômites, recomenda-se desinfestação mecânica e/ou química.","C":"O tratamento da ftiríase pode ser realizado por meio de retirada manual dos parasitas com\nauxílio de vaselina. Uma alternativa, o tratamento específico com benzoato de benzila tópico, é\nbastante eficaz pela baixa toxidade e por atuar em todas as formas do parasita.","D":"O tratamento da tungíase consiste na retirada das pulgas penetradas com uma agulha estéril e\ntratamento de infecções secundárias com antibiótico. Esse tratamento deve estar associado ao uso\nde antiparasitários por via oral, em especial o tiabendazol.","E":"O tratamento de todas as ectoparasitoses discutidas pela equipe deve estar associado a\nmedidas de melhoria das condições de higiene da família, basicamente: cuidado com utensílios\ndomésticos, com roupas de uso pessoal ou de uso comum."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-6983","number":"6983","sourceNumber":"6983","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ao chegar em uma unidade básica de saúde do Município de Fortaleza para assumir a\nsua nova função de residente, você toma\nconhecimento que terá de acompanhar alguns casos de\nhanseníase que estão em tratamento para estados reacionais. Em relação a essas reações\nimunológicas na hanseníase, pode-se afirmar que:","options":{"A":"Ocorrem principalmente durante a fase final do tratamento da hanseníase, mas também podem\nocorrer antes ou após a poliquimioterapia\n(após a cura).","B":"Os estados reacionais representam a principal causa de lesões dos nervos e de incapacidades\nfísicas provocadas pela hanseníase.","C":"A reação tipo I ou reação reversa caracteriza-se pelo aparecimento de novas lesões\ndermatológicas e é tratada com talidomida.","D":"A reação tipo II ou eritema nodoso tem comprometimento sistêmico pouco frequente e é tratada\ncom corticosteroides orais.","E":"A evolução da reação tipo I é rápida enquanto a tipo II é lenta, o que mostra a necessidade de\ntratamento mais prolongado nessa última."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-6989","number":"6989","sourceNumber":"6989","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ao chegar em uma nova unidade básica de saúde do Município de Fortaleza para\nassumir a sua nova função de residente, você\ntoma conhecimento que terá de acompanhar alguns\ncasos de hanseníase que estão em tratamento para estados reacionais. Em relação a essas\nreações imunológicas na hanseníase, pode-se afirmar que:","options":{"A":"Ocorrem principalmente durante a fase final do tratamento da hanseníase, mas também podem\nocorrer antes ou após a poliquimioterapia\n(após a cura).","B":"Os estados reacionais representam a principal causa de lesões dos nervos e de incapacidades\nfísicas provocadas pela hanseníase.","C":"A reação tipo I ou reação reversa caracteriza-se pelo aparecimento de novas lesões\ndermatológicas e é tratada com talidomida.","D":"A reação tipo II ou eritema nodoso tem comprometimento sistêmico pouco frequente e é tratada\ncom corticosteroides orais.","E":"A evolução da reação tipo I é rápida, enquanto a tipo II é lenta, o que mostra a necessidade de\ntratamento mais prolongado nessa última."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-349748","number":"349748","sourceNumber":"349748","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual é a coloração utilizada na baciloscopia para investigação de hanseníase?","options":{"A":"Tinta da China.","B":"Ziehl-Neelsen.","C":"Vermelho congo.","D":"Azul da Prússia.","E":"Grocott."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-349771","number":"349771","sourceNumber":"349771","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 37 anos, com pele e olhos claros e história familiar de melanoma,\npossui uma lesão pigmentada em região da mão\nesquerda de, aproximadamente, 1 cm. Nesse\ncaso, a melhor conduta a ser seguida para esse paciente é realizar","options":{"A":"biópsia incisional da lesão e sutura em pontos simples com fio absorvível.","B":"tratamento precoce, com ressecção da lesão com margens amplas devido ao histórico familiar,\ncom sutura contínua após ressecção.","C":"biópsia excisional da lesão e sutura em pontos simples com fio inabsorvível.","D":"ressecção da lesão com margem de 1 cm devido à alta suspeita de melanoma e sutura contínua\ncom fio inabsorvível.","E":"biópsia com 5 mm de margem e enxerto em mão com sutura contínua."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-349695","number":"349695","sourceNumber":"349695","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Menina de três anos de idade foi levada ao pronto-socorro após ser picada por uma\nabelha. Ela apresentou sintomas de uma reação alérgica grave que pode ser fatal se não tratada\nrapidamente. Nesse caso, a conduta mais adequada é","options":{"A":"usar injeção de adrenalina na coxa da criança, evitando complicações mais graves.","B":"administrar um antialérgico oral e encaminhar a criança para o hospital mais próximo.","C":"remover o ferrão da abelha com uma pinça e prescrever pomada anti-inflamatória no local.","D":"aplicar uma compressa fria no local da picada e observar a evolução dos sintomas.","E":"transferir para a UTI pediátrica e iniciar dobutamina."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-322132","number":"322132","sourceNumber":"322132","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 27 anos possui uma lesão pigmentada e assimétrica, de\naproximadamente 7mm, localizada em pele do\ndorso. Procurou um médico que indicou biópsia.\nQual é o melhor tipo de biópsia a ser indicada para esse paciente?","options":{"A":"Biópsia incisional.","B":"Biópsia excisional.","C":"Biópsia em shaving superficial.","D":"Biópsia com agulha fina.","E":"Biópsia com agulha grossa."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-322186","number":"322186","sourceNumber":"322186","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Você está atendendo uma criança de 6 anos com queixa de lesões de pele, com\nprurido intenso, que ocorre principalmente à\nnoite, há alguns dias. O paciente não apresentou febre\nou qualquer outro sintoma. As lesões são papulovesiculares eritematosas, localizadas em espaços\ninterdigitais, axilas, punhos, regiões glútea e genital. Os pais estão presentes na consulta, e a\nmãe\nrefere os mesmos sintomas, com lesões semelhantes, mas com presença de lesões em túnel. O\npai está assintomático e sem lesões. Qual é a conduta adequada em relação ao paciente e aos\nseus pais?","options":{"A":"Prescrever tratamento para a criança e para os familiares, independentemente da presença de\nsintomas.","B":"Prescrever o tratamento para a criança e para os familiares sintomáticos.","C":"Prescrever o tratamento apenas para a criança, que é sua paciente.","D":"Prescrever o tratamento para a criança e para a mãe.","E":"Prescrever o tratamento para a criança e indicar avaliação com dermatologista para a mãe."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-322213","number":"322213","sourceNumber":"322213","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paulo foi encaminhado ao dermatologista pelo médico da família com suspeita de\ncarcinoma basocelular. Nessa patologia, a forma\nclínica mais comum apresenta qual das seguintes\ncaracterísticas?","options":{"A":"nódulo, com posterior ulceração recoberta por crosta.","B":"lesão eritematodescamativa, não infiltrada, com bordas regulares.","C":"placa acastanhada endurecida, às vezes com telangiectasia.","D":"úlcera destrutiva, com bordas peroláceas.","E":"pápulas claras que evoluem para vesículas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-305268","number":"305268","sourceNumber":"305268","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa que melhor representa o conjunto de características que sugerem\npior prognóstico e estadiamento mais avançado em\ncasos de melanoma maligno e qual deve ser a\nabordagem inicial mais CORRETA em uma lesão suspeita dessa neoplasia.","options":{"A":"Presença de ulceração, Breslow de 0,2 mm e nível I de Clark/biópsia incisional.","B":"Breslow de 2,5 mm, linfonodo sentinela positivo, ausência de ulceração/biópsia excisional.","C":"Índice mitótico de 4/mm², Breslow de 1,3 mm e invasão angiolinfática/biópsia incisional.","D":"Presença de ulceração, Breslow de 0,3 cm e linfonodo sentinela positivo / biópsia excisional.","E":"Nível II de Clark, Breslow de 0,18 cm e invasão angiolinfática/biópsia tipo shaving."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-305323","number":"305323","sourceNumber":"305323","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre as picadas de abelhas, assinale a alternativa correta.","options":{"A":"Nos acidentes causados por enxame, a retirada dos ferrões da pele deve ser feita por\npinçamento.","B":"Mais de 70% dos indivíduos que apresentaram grandes reações localizadas terão reações\nsistêmicas, com anafilaxia 2 a 3 minutos após a picada.","C":"A intensidade da reação inicial não está relacionada com a sensibilização e maior risco às\nexposições subsequentes.","D":"Os acidentes com enxames podem desencadear quadro tóxico generalizado, com\nmanifestações como hemólise intravascular e\nrabdomiólise, alterações neurológicas e insuficiência\nrenal aguda.","E":"Os glicocorticoides e anti-histamínicos são a melhor opção terapêutica para controlar reações\ncomo urticária gigante e broncoespasmo."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-300368","number":"300368","sourceNumber":"300368","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A respeito da imunoterapia alérgeno-específica, julgue o item a seguir. Proporciona\nbenefícios duradouros mesmo após a sua descontinuação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-261210","number":"261210","sourceNumber":"261210","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente de 35 anos de idade apresenta mancha de cor marrom-enegrecida de\n1,2 cm, assimétrica, com bordas irregulares\ne coloração heterogênea em coxa direita. Não se\nobservou adenomegalia no exame físico ou de imagem. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A conduta inicial mais apropriada é uma\nbiópsia excisional da lesão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-261211","number":"261211","sourceNumber":"261211","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente de 35 anos de idade apresenta mancha de cor marrom-enegrecida de\n1,2 cm, assimétrica, com bordas irregulares\ne coloração heterogênea em coxa direita. Não se\nobservou adenomegalia no exame físico ou de imagem. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Caso a biópsia evidencie índice de\nBreslow de até 1,2 mm, dispensa-se a realização de pesquisa de linfonodo sentinela, pois não há\nevidência de adenomegalia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-274393","number":"274393","sourceNumber":"274393","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na dermatite atópica, a hidratação da pele é o tratamento de primeira linha. Os\nhidratantes são compostos por combinações\nvariáveis de emolientes, umectantes e substâncias\noclusivas e podem ser produzidos em loções, cremes e pomadas. Assinale a alternativa correta\nsobre os tipos de hidratantes.","options":{"A":"Os emolientes aumentam a hidratação da camada córnea, preservando sua estrutura.","B":"Os umectantes preenchem os espaços entre os corneócitos, mantendo a hidratação.","C":"As loções são uma emulsão bifásica de água em óleo ou óleo em água.","D":"As substâncias oclusivas formam um filme hidrofóbico sobre a epiderme, que retarda a\nevaporação da água e a penetração de agentes irritantes.","E":"Os cremes têm alto teor de água, o que permite maior tolerância e evaporação."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-261316","number":"261316","sourceNumber":"261316","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O rastreio e o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede\nde Atenção Primária. Considerando isso,\nsuponha que uma mulher de 53 anos de idade procure\numa unidade básica de saúde para realização de exames de rotina, e o médico da Atenção\nPrimária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto \"perolado\",\ncom finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão\napresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Trata-se de uma lesão suspeita de carcinoma\nbasocelular, um tipo de câncer de pele não melanoma que apresenta comportamento mais\nagressivo, com maior possibilidade de metástases.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-255785","number":"255785","sourceNumber":"255785","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere aos conhecimentos relacionados a bioética, saúde mental,\nendocrinologia, dermatologia e cardiologia, julgue\no item a seguir. O ciclopirox e o sulfeto de selênio\nxampu são opções para tratamento tópico da pitiríase versicolor.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-211916","number":"211916","sourceNumber":"211916","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente de 75 anos de idade, de etnia caucasiana, trabalhadora braçal por 50\nanos (capinava na roça da família), apresenta\nlesão de pele em região do dorso, próxima à\nescápula direita, de aproximadamente 3 cm de diâmetro, de coloração enegrecida, com bordos\nirregulares, diagnosticada como melanoma após biópsia. Acerca desse caso clínico e com base\nnos conhecimentos médicos correlatos, em relação às lesões de pele, assinale a alternativa\ncorreta.","options":{"A":"O câncer de pele é uma das formas menos frequentes de câncer.","B":"O nevo displásico é uma lesão cutânea geralmente sem pigmentação, áspera, de 3 mm a 5 mm,\ncom margens bem delimitadas.","C":"A ocupação da paciente não constitui um fator de risco para o desenvolvimento de melanoma.","D":"Nevos displásicos são considerados lesões precursoras do câncer de pele.","E":"Na exérese cirúrgica do melanoma in situ, as margens preconizadas são de pelo menos 5 cm."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-177604","number":"177604","sourceNumber":"177604","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. O rastreamento do câncer de pele não é\nindicado, por tratar-se de uma paciente negra.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-177690","number":"177690","sourceNumber":"177690","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. O uso de protetor solar durante as caminhadas é prudente, sobretudo, em indivíduos\ncom pele clara.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-154356","number":"154356","sourceNumber":"154356","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente O. L. S., 65 anos de idade, sexo masculino, branco, trabalhador rural,\ncomparece ao serviço de atendimento com\nqueixa de mancha na fronte de crescimento progressivo\nnos últimos oito anos, tendo se originado de uma pinta na região. O paciente negou dor no local ou\nprurido. Clinicamente trata-se de lesão plana e assimétrica, com bordos irregulares e heterocromia\nem tons de marrom medindo 4,5 cm no maior diâmetro. Na região cervical sobressaem alguns\nlinfonodos de consistência amolecida, indolores e imóveis. Quanto a esse caso clínico, assinale a\nalternativa que apresenta a hipótese diagnóstica e a lesão originária corretas:","options":{"A":"Melanoma lentigo maligno com origem em lentigo maligno.","B":"Melanona acral lentiginoso com origem em nevo atípico.","C":"Melanoma nodular com origem em nevo amelanótico.","D":"Nevo displásico com origem em nevo melanocítico.","E":"Melanoma desmoplásico com origem em nevo de Spitz ."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-154325","number":"154325","sourceNumber":"154325","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente F. N. M., 43 anos de idade, sexo masculino, trabalhador da construção civil,\ncomparece ao serviço de atendimento com queixa de manchas na pele. Aponta que o quadro tem\nevolução aproximada de três anos, lento e progressivo, com manchas distribuídas por todo o corpo\ne sensação de queimação e de formigamento em mãos e pés. Essas manchas eram pálidas\ninicialmente, havendo acentuação da tonalidade para avermelhadas e queda de fâneros cutâneos\nem face. Clinicamente observam-se múltiplas máculas mal delimitadas, hiperemiadas e\ndifusamente distribuídas em tronco e membros, associadas a espessamento dos nervos ulnar\nesquerdo e sural direto. Na pesquisa laboratorial de Barr para a linfa removida de uma das lesões,\no resultado foi positivo (+++). Considerando o quadro clínico apresentado, assinale a alternativa\nque apresenta, respectivamente, a classificação do paciente pelos critérios da OMS e o tratamento\npreconizado pelo Ministério da Saúde.","options":{"A":"Forma tuberculoide e tratamento com seis doses mensais e supervisionadas de rifampicina\nassociada a dapsona e clofazimina, conforme esquema.","B":"Forma dimorfa e tratamento com 12 doses mensais de rifampicina associada a dapsona e\nclofazimina, conforme esquema.","C":"Forma indeterminada e tratamento com seis doses mensais e supervisionadas de dapsona e\nclofazimina, conforme esquema.","D":"Forma multibacilar e tratamento com 12 doses mensais e supervisionadas de rifampicina\nassociada a dapsona e clofazimina, conforme esquema.","E":"Forma virchowiana e tratamento com 12 doses supervisionadas de pirazinamina e etambutol\nassociadas a rifampicina."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-152123","number":"152123","sourceNumber":"152123","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. Acerca do caso clínico do\nPaciente 2, aproximadamente 80% dos pacientes que desenvolvem melanoma são curados, e a\ndoença recorrente pode ser observada nos sítios locais, regionais, sistêmicos ou combinados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-105569","number":"105569","sourceNumber":"105569","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As manifestações clínicas na hipersensibilidade alimentar são variadas e acometem\nvários órgãos. Em relação ao diagnóstico,\nassinale a alternativa CORRETA:","options":{"A":"As manifestações predominantemente respiratórias, como tosse e broncoespasmo, geralmente\nsão isoladas, o que dificulta muito o diagnóstico.","B":"As manifestações gastrointestinais incluem comumente diarreia aguda ou crônica, entretanto,\nraramente acarretam retardo do crescimento, dado\nimportante para o diagnóstico diferencial no\nacompanhamento do crescimento e desenvolvimento.","C":"As manifestações cutâneas são incomuns, sendo principal a dermatite atópica.","D":"Os principais alimentos responsáveis por alergia alimentar, nos dois primeiros anos de vida, são\no leite de vaca e o trigo, por isso o leite\nde soja tem sido amplamente indicado como substituto.","E":"A reação mais grave é a anafilaxia, ocorrendo logo após a ingestão do alimento, podendo levar\nao choque. Tem diagnóstico diferencial com aspiração broncopulmonar."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-108171","number":"108171","sourceNumber":"108171","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Para definir o esquema terapêutico mais adequado a cada paciente portador de\nhanseníase, a Organização Mundial de Saúde\nutiliza uma classificação que se baseia no número\nde lesões cutâneas. Com referência a essa classificação, julgue o item subsequente. Os indivíduos\nque possuem de uma a cinco lesões são paucibacilares, os que têm seis ou mais lesões são\nmultibacilares. Para o tratamento dos paucibacilares, são utilizadas a poliquimioterapia com\nprevisão de alta por cura após seis doses mensais supervisionadas de rifampicina e dapsona e\ndoses diárias de dapsona autoadministradas em até nove meses.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-82022","number":"82022","sourceNumber":"82022","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Acerca da hanseníase, julgue o item subsecutivo: A presença de mácula eritematosa\nmal delimitada hipoestésica localizada nas\nnádegas, pode ser detectada na fase inicial da doença.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-82085","number":"82085","sourceNumber":"82085","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A respeito do diagnóstico clínico e etiológico das dermatoses na infância, julgue o item\nseguinte: Um escolar apresenta manchas hipocrômicas no tronco, no pescoço e na face extensora\ndos braços e antebraços. Ao exame de fricção da pele, observa-se uma fina descamação\nfurfurácea. O agente etiológico mais provável, nessa situação, é a Malassezia furfur.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-88724","number":"88724","sourceNumber":"88724","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Julgue o próximo item, relativo à hanseníase. A hanseníase virchowiana manifesta-se\npor lesões cutâneas e lesões viscerais; a\nhanseníase na forma paucibacilar é a única forma de\nhanseníase que se caracteriza pela presença de manifestações neurológicas; e a hanseníase nas\nformas tuberculoides é caracterizada pelo comprometimento tardio e atenuado dos nervos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-45726","number":"45726","sourceNumber":"45726","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma senhora de 32 anos de idade procurou atendimento médico com relato de que há\nseis meses passou a apresentar fadiga, dispneia aos grandes esforços, edema de membros\ninferiores, dor no hipocôndrio direito e a sensação de empachamento pós-prandial. Negou doenças\nanteriores, tabagismo, e etilismo. Seu exame físico mostrou: paciente emagrecida, frequência\ncardíaca de 90 bpm, pressão arterial de 100 x 80 mmHg, com evidência de pulso paradoxal,\nturgência jugular observada com cabeceira do leito elevada a 40°, aumento da pressão venosa\njugular durante a inspiração profunda, presença de retração intercostal (simultânea com a sístole\ncardíaca) observada no décimo primeiro e décimo segundo espaços intercostais esquerdos, ritmo\ncardíaco regular em dois tempos, bulhas hipofonéticas, com presença de knock após a segunda\nbulha cardíaca em área tricúspide. Aparelho respiratório sem anormalidades. Abdome:\nhepatomegalia dolorosa sem ascite. Extremidades: edema de membros inferiores, mole, frio e\nindolor. O eletrocardiograma apresentou: ritmo sinusal, frequência ventricular média de 92 spm,\nSÂQRS = + 120°, onda P entalhada em derivação D2, baixa voltagem do complexo QRS no plano\nfrontal e alterações difusas e inespecíficas da repolarização ventricular. Com base nessa situação\nclínica hipotética, assinale a alternativa que apresenta a principal hipótese diagnóstica.","options":{"A":"Pericardite constritiva.","B":"Cor pulmonale.","C":"Mixoma atrial.","D":"Cardiomiopatia hipertrófica.","E":"Miocardite viral."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27567","number":"27567","sourceNumber":"27567","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Avalie as seguintes afirmativas quanto à hanseníase. I. As principais causas de\nmorbidade da hanseníase decorrem do fato de\nque o Mycobacterium leprae apresenta tropismo\ncaracterístico pelos nervos periféricos acrescido a que certos estados reacionais são mediados\nimunologicamente. II. Define-se como caso de hanseníase indivíduo que apresente uma ou mais de\numa das seguintes características e que requer quimioterapia: lesão(ões) de pele com alteração de\nsensibilidade; acometimento de nervo(s) com espessamento neural e baciloscopia positiva. III. O\nMycobacterium leprae tem baixa infectividade e alta patogenicidade, isto é, infecta muitas pessoas,\nno entanto só poucas adoecem. IV. A poliquimioterapia padronizada pela Organização Mundial de\nSaúde inclui os seguintes agentes de escolha no tratamento da hanseníase: dapsona, clofazimina e\nrifampicina. V. Os estados reacionais ocorrem, principalmente, durante os últimos meses do\ntratamento quimioterápico da hanseníase, mas também podem ocorrer antes ou depois do mesmo\nnesse caso após a cura do paciente. Assinale a alternativa correta.","options":{"A":"Somente as assertivas I e V estão corretas.","B":"Somente as assertivas I, II e IV estão corretas.","C":"Somente as assertivas II, III e IV estão corretas.","D":"Somente a assertiva II está correta.","E":"Somente as assertivas I, II e III estão corretas."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-352405","number":"352405","sourceNumber":"352405","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Durante uma consulta oftalmológica, após a administração intraocular de um\nmedicamento, um paciente desenvolve prurido\ngeneralizado intenso, rubor, edema labial e eritema\nurticariforme. Além disso, apresenta rinorreia hialina, disfonia, estridor, dor abdominal e náusea.\n\nDiante dessa situação, o paciente é imediatamente encaminhado para a Sala de Emergência.\nDurante a avaliação, é observada a presença\nde sibilos difusos à ausculta e hipoxemia à\nmonitorização (SpO?: 88%) em ar ambiente, acompanhada de hipotensão arterial (80x60 mm Hg).\nCom base nesse caso clínico hipotético, julgue o item a seguir. Os principais desencadeadores da\nanafilaxia incluem alimentos, aditivos, drogas (com destaque para antibióticos e\nanti-inflamatórios) e\npicadas de insetos da ordem Hymenoptera.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-343403","number":"343403","sourceNumber":"343403","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 74 anos, lavradora desde os 15 anos, procurou a UBS de seu bairro referindo\nlesão cutânea em MSE (conforme figura), com\ncrescimento progressivo há 7 meses. O Tratamento\nmais indicado para a hipótese diagnóstica é:","options":{"A":"Curetagem e eletrocoagulação.","B":"Terapia Fotodinâmica.","C":"Radioterapia Superficial.","D":"Exérese com margens de segurança."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/343403.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334887","number":"334887","sourceNumber":"334887","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma criança com 7 anos de idade apresenta, há quatro dias, lesões que se iniciaram\nna face e no couro cabeludo, as quais\nrapidamente se disseminaram para o tronco. As lesões são\ncaracterizadas por prurido intenso, polimorfismo (mácula, pápula, vesícula e crosta) e são\naltamente contagiosas. A mãe procurou o posto de saúde, e o médico que a examinou prescreveu\nsintomáticos. Acerca do diagnóstico do citado quadro, assinale a alternativa correta.","options":{"A":"O exantema papulovesicular acomete muito as extremidades, e o contágio ocorre através de\nfômites.","B":"Nas crianças, há um pródromo muito longo, em geral 10 dias, para depois as lesões iniciarem-se\ncomo crostas.","C":"Não é frequente o aparecimento de lesões em mucosa, como no palato e (ou) na mucosa\nvulvovaginal.","D":"A evolução lenta da doença faz com que tenhamos lesões pleomórficas, ou seja, em um estágio\nde lesão elementar.","E":"A incidência de complicações é relativamente maior em crianças menores de 1 ano de idade e\nem adultos."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-343413","number":"343413","sourceNumber":"343413","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A Dermatite Atópica (DA), ou eczema atópico, é uma doença de caráter inflamatório,\ncrônico e recidivante, clinicamente\ncaracterizada por eczema associado a prurido intenso, de\ndistribuição peculiar e variável com a idade. Com relação à DA, é INCORRETO afirmar:","options":{"A":"As alergias respiratórias não tem relação com a dermatite atópica, pois são resultantes de\nmecanismos imunológicos diferentes.","B":"Os fatores ambientais que podem contribuir para a piora do quadro de DA são alérgenos\nalimentares (os mais implicados são clara de ovo, leite de vaca e trigo).","C":"As características clínicas comuns a todos os atópicos são prurido intenso e xerose cutânea.","D":"Defeitos na barreira lipídica da pele do atópico facilitam a penetração de bactérias, permeando\nos espaços intercelulares."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-343414","number":"343414","sourceNumber":"343414","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A Anafilaxia é sempre uma emergência médica que se caracteriza por imprevisibilidade,\nrápida instalação e risco real de morte. Com\nrelação à Anafilaxia, é CORRETO afirmar:","options":{"A":"Com base nos sintomas inicias, é possível prever com segurança a gravidade e o tempo de\nevolução do evento anafilático.","B":"A avaliação laboratorial é essencial para o diagnóstico precoce da Anafilaxia.","C":"A hipersensibilidade ao veneno de insetos da ordem Hymenoptera é o desencadeante mais\ncomum de reações anafiláticas.","D":"A adrenalina é a droga-chave na Anafilaxia e a sua rápida administração garante diminuição da\nmortalidade."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317748","number":"317748","sourceNumber":"317748","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatite herpetiforme, assinale a alternativa CORRETA.","options":{"A":"A presença de lesões urticadas é comum.","B":"O infiltrado inflamatório é constituído predominantemente de eosinó los.","C":"O depósito de IgA nas papilas dérmicas é linear.","D":"Anticorpos antiendomísio são encontrados na minoria dos pacientes."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317749","number":"317749","sourceNumber":"317749","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto à angiomatose bacilar, assinale a alternativa INCORRETA.","options":{"A":"Os agentes etiológicos mais comuns são a Bartonella henselae e Bartonella quintana.","B":"É mais observada em pacientes infectados pelo HIV com CD4+ menor que 200 células/µl.","C":"As lesões cutâneas são dérmicas superficiais e o acometimento extracutâneo é incomum.","D":"A histopatologia mostra proliferação lobular de capilares e vênulas, células endoteliais\narredondadas e protuberantes e denso infiltrado neutrofílico."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317750","number":"317750","sourceNumber":"317750","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à utilização da luz de Wood (365 nm) como método semiológico auxiliar\npara o diagnóstico de algumas dermatoses,\nnumere a COLUNA II de acordo com a COLUNA I,\nrelacionando os diagnósticos às colorações mais frequentemente encontradas com o uso dessa\ntécnica. COLUNA I; 1. Tinea capitis, causada pelo Mycrosporum canis; 2. Pitiríase versicolor; 3.\nEritrasma; 4. Carcinoma espinocelular; COLUNA II; ( ) róseo dourada; ( ) verde; ( ) vermelho coral;\n(\n\n) vermelho brilhante (\"em brasa\"); Assinale a sequência CORRETA.","options":{"A":"2 1 3 4","B":"1 2 4 3","C":"4 3 1 2","D":"3 4 2 1"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317751","number":"317751","sourceNumber":"317751","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto ao vírus varicela zoster, é CORRETO afirmar:","options":{"A":"Um paciente com herpes-zóster pode infectar outra pessoa, e esta ter varicela, caso seja\nsusceptível.","B":"A síndrome de Ramsay-Hunt ocorre devido à reativação do vírus nos gânglios das cadeias para\nvertebrais torácicas.","C":"A vacina feita com vírus atenuado (cepa de Oka) tem baixa taxa de soro conversão em crianças.","D":"Um indivíduo imunocomprometido, em contato com o fluído das vesículas de paciente com\nherpes-zóster, pode desenvolver herpes-zóster."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317752","number":"317752","sourceNumber":"317752","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às afecções da glândula sudorípara, assinale a alternativa INCORRETA.","options":{"A":"A doença de Grover é mais comum em homens caucasianos com mais de 40 anos de idade.","B":"A queratólise esfoliativa, ou disidrose lamelar, não é precedida de vesículas nem tem pápulas\nconcomitantes.","C":"Na histopatologia da disidrose, há uma dermatite espongiótica com vesículas associadas aos\nductos sudoríparos.","D":"A doença de Fox-Fordyce é uma alteração crônica e pruriginosa das glândulas sudoríparas\napócrinas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317753","number":"317753","sourceNumber":"317753","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O retalho de Spear é utilizado para a reconstrução de defeitos:","options":{"A":"profundos na região fronto-temporal.","B":"de espessura total da asa nasal.","C":"de espessura total do lábio inferior.","D":"da hélixe da concha auricular."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317754","number":"317754","sourceNumber":"317754","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto à criocirurgia, assinale a alternativa INCORRETA.","options":{"A":"No tratamento das lesões neoplásicas, devem-se atingir temperaturas de cerca de 60 graus\nnegativos dentro do tecido a ser destruído.","B":"Quando se utiliza a ponteira de spray, a aplicação deve ser intermitente para facilitar a frente\nde\ncongelamento.","C":"A ponteira fechada e congelada possibilita menor congelamento em profundidade, não sendo\nbem indicada para neoplasias malignas.","D":"É contraindicada em casos de tumores muito espessos e fixos aos planos profundos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317755","number":"317755","sourceNumber":"317755","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à terapêutica sistêmica, assinale a alternativa CORRETA.","options":{"A":"A excreção do fluconazol é feita principalmente pelo fígado, sendo necessário o ajuste da\ndosagem em hepatopatas.","B":"Os barbitúricos aumentam os níveis plasmáticos da griseofulvina.","C":"O posaconazol tem o maior espectro dentre os azois, sendo eficaz no tratamento da zigomicose.","D":"O micofenolato de mofetil estimula a proliferação de linfócitos T e B que dependem da via de\nsíntese das purinas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317756","number":"317756","sourceNumber":"317756","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a fototerapia, assinale a alternativa INCORRETA.","options":{"A":"A UVB de banda estreita (narrow band) é inefetiva nos casos graves de dermatite atópica e de\ndermatite seborreica.","B":"Os tratamentos repetidos, prolongados e com altas doses cumulativas de PUVA podem induzir\nlentiginose.","C":"A UVB de banda estreita (narrow band) tem boa eficácia em casos de prurido idiopático, no de\norigem hepática e do diabetes mellitus.","D":"Nos pacientes tratados com PUVA, o risco de ocorrência de carcinoma espinocelular é\nsignificativamente maior que nos controles."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317757","number":"317757","sourceNumber":"317757","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto aos antibióticos de uso tópico, assinale a alternativa INCORRETA.","options":{"A":"A neomicina é um polipeptídio cíclico isolado da cepa Tracey I do Bacillus subitilis.","B":"A clindamicina tanto pode ser bacteriostática quanto bactericida, dependendo da\nsusceptibilidade do organismo infectante e da concentração obtida no local.","C":"A retapamulina é o primeiro fármaco da nova classe de pleuromutilinas.","D":"A mupirocina é derivada da Pseudomonas fluorescens."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317758","number":"317758","sourceNumber":"317758","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa que não é considerada uma dermatose paraneoplásica.","options":{"A":"Erythema gyratum repens","B":"Hipertricose lanuginosa adquirida","C":"Acroqueratose de Bazex","D":"Ictiosis hystrix"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317759","number":"317759","sourceNumber":"317759","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise o caso clínico a seguir. Paciente, sexo feminino, caucasiana, 40 anos de idade,\npreviamente hígida, queixa de alopecia de supercílios há um ano, tendo sido tratada com\ninfiltrações intralesionais de triancinolona com repilação temporária. À dermatoscopia da área\nacometida, notam-se pontos amarelos e pontos pretos. Considerando esse caso, assinale a\nalternativa INCORRETA.","options":{"A":"As principais hipóteses diagnósticas incluem: alopecia areata, tricotilomania, alopecia frontal\nbrosante, sí lis e micose fungoide.","B":"A ausência de pelos peládicos à dermatoscopia não exclui a possibilidade de alopecia areata.","C":"O exame dermatoscópico da linha de implantação frontotemporal do couro cabeludo contribui\npara o diagnóstico de alopecia frontal\nbrosante.","D":"A repilação induzida pelo tratamento con rma o diagnóstico de alopecia areata."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317760","number":"317760","sourceNumber":"317760","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação aos enxertos cutâneos, é CORRETO afirmar que:","options":{"A":"estão melhor indicados na correção de defeitos cirúrgicos provenientes da retirada de tumores\npouco agressivos.","B":"a vascularização da área receptora pode ser fator limitante na sobrevida do enxerto; e a derme,\nmúsculo e tendões são excelentes leitos para o enxerto.","C":"o fenômeno de embebição ocorre nas primeiras 24 horas após a colocação do enxerto no sítio\nreceptor, e se traduz por edema do enxerto em virtude da absorção de nutrientes e exsudato.","D":"a neovascularização do enxerto ocorre entre o 10o e o 14o dia de pós-operatório, com formação\nde um novo complexo vascular."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317761","number":"317761","sourceNumber":"317761","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise o quadro clínico a seguir. Paciente de 32 anos, sexo masculino, é portador de\nhanseníase boderline-boderline, apresentando reação mista, em uso de esquema MDT (sulfona,\nclofazimina e rifampicina) no quarto mês de tratamento, associado a prednisona (60 mg/dia) e\ntalidomida (200 mg/dia). Após duas horas da administração da dose supervisionada, apresenta\nquadro de febre, calafrios, cefaleia e osteoalgias, evoluindo para choque. Na investigação\nlaboratorial, foram identificados anemia hemolítica, púrpura trombocitopênica e insuficiência renal.\nAssinale a alternativa que apresenta o diagnóstico para o quadro descrito.","options":{"A":"Pielonefrite evoluindo para sepse.","B":"Síndrome sulfona.","C":"Síndrome pseudo gripal causada por rifampicina.","D":"Reação anafilática a sulfona ou rifampicina."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317762","number":"317762","sourceNumber":"317762","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As manifestações clínicas da psoríase variam de acordo com os seus subtipos. A esse\nrespeito, assinale a alternativa INCORRETA.","options":{"A":"A psoríase em placas ou vulgar pode ser observada em até 90% dos doentes.","B":"Na psoríase rupiácea, as escamas são finas e pouco aderentes, e é observada mais\nfrequentemente na infância.","C":"A psoríase em gotas é mais comum em crianças, adolescentes e adultos jovens, podendo ser\nprecedida por infecção estreptocócica.","D":"A psoríase dos idosos ocorre principalmente nos membros inferiores e no couro cabeludo, de\nforma leve a moderada."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317763","number":"317763","sourceNumber":"317763","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à pitiríase rubra pilar, assinale a alternativa INCORRETA:","options":{"A":"É uma dermatose inflamatória crônica caracterizada por queratoses foliculares circunscritas,\nplacas eritemato-alaranjadas e queratodermia palmoplantar.","B":"É rara, acometendo igualmente ambos os sexos com picos de incidência nas duas primeiras\ndécadas de vida e por volta da quinta e sexta décadas de vida.","C":"Apresenta duas formas clínicas: familiar (início geralmente na adolescência) e esporádica\n(adultos, sem antecedente familiar e grave).","D":"A forma familiar apresenta provável herança autossômica dominante e existe a expressão de\nqueratinas K6/K16 como marcador de proliferação epidérmica."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-307103","number":"307103","sourceNumber":"307103","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente foi atendida no pronto-socorro com manifestação de alergia por ter\ncomido um empanado com frutos do mar. Chegou\ncom exantema morbiliforme, prurido ocular,\nedema palpebral, coriza nasal, com congestão, prurido nasal e por todo corpo. Foi prontamente\natendida e realizado prometazina intramuscular, mas como não obteve resposta, começou a\napresentar taquicardia, irritabilidade e cefaleia. Então administrou-se outra dose de prometazina\nendovenosa. A paciente evolui com sonolência excessiva e hipotensão. Acerca desse caso clínico,\nassinale a alternativa correta. Alternativas:","options":{"A":"O uso de epinefrina aquosa, no início do tratamento na dose 0,3 mg a 0,5 mg, teria piorado o\nquadro hemodinâmico.","B":"Essa paciente não precisa de suportes. Após realizar o controle da reação anafilática e da\nagitação, nesse momento a indicação é somente de deixá-la descansar e observar.","C":"Uma droga como difenidramina 25 mg a 50 mg, endovenosa, não tem indicação nesse caso.","D":"A prometazina com anti-histamínico, antagonista H? são considerados segunda linha no\ntratamento da anafilaxia.","E":"O uso de anti-inflamatórios esteroides está muito bem indicado, nesse caso, em monoterapia."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317764","number":"317764","sourceNumber":"317764","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o líquen nítido, está CORRETO afirmar que:","options":{"A":"o principal fator etiológico é a infecção por vírus Epstein-Barr.","B":"há maior associação com diabetes mellitus.","C":"são descritas as variantes hemorrágica, perfurante e generalizada.","D":"as lesões poupam a área genital."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317765","number":"317765","sourceNumber":"317765","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o prurigo nodular de Hyde, é INCORRETO afirmar:","options":{"A":"É uma dermatose que raramente acomete crianças.","B":"As picadas de insetos podem estar relacionadas ao seu aparecimento.","C":"O prurido é intenso e persistente.","D":"É caracterizado por pápulas e urticas assimétricas."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317766","number":"317766","sourceNumber":"317766","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às linhas de Beau, assinale a alternativa INCORRETA.","options":{"A":"Ocorrem por alteração inflamatória do leito ungueal.","B":"A profundidade da linha indica a gravidade do acometimento.","C":"Microtraumas e doenças sistêmicas são fatores etiológicos.","D":"A margem distal bem delimitada indica dano agudo."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317767","number":"317767","sourceNumber":"317767","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às possíveis complicações relacionadas ao uso da toxina botulínica tipo A,\né CORRETO afirmar:","options":{"A":"Têm menos chance de ocorrer com a utilização da droga mais concentrada.","B":"É frequente a ocorrência de reações alérgicas, e o procedimento deve ser contraindicado em\npacientes com história prévia de atopia.","C":"A formação de anticorpos neutralizadores da ação da toxina ocorre invariavelmente após duas\naplicações para fins cosmiátricos.","D":"Para minimizar a difusão da toxina para músculos indesejados, após o procedimento, o paciente\ndeve ser orientado a permanecer deitado\ndurante um período de duas horas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317768","number":"317768","sourceNumber":"317768","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao carcinoma basocelular, tumor maligno cutâneo mais frequente no nosso\nmeio, assinale a alternativa INCORRETA.","options":{"A":"Quando cresce ao longo dos vasos ou do perineuro, a área de invasão é maior e não detectada\nclinicamente, e as recidivas são frequentes.","B":"O risco de metástase é de 2% e é observado nos padrões histológicos agressivos como o\nesclerodermiforme e o queratótico.","C":"O superficial e multicêntrico é mais frequente no tronco, mas também ocorre na face.","D":"O infiltrativo mostra células basaloides com arranjo em forma de cordões ou como espículas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317769","number":"317769","sourceNumber":"317769","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando o carcinoma espinocelular (CEC), assinale a alternativa CORRETA.","options":{"A":"A papulose bowenoide é o CEC in situ dentro de verrugas genitais, geralmente devido a uma\ninfecção viral com cepas oncogênicas.","B":"O carcinoma verrucoso é uma variante mal diferenciada do CEC, que tende a ocorrer em adultos\nmais idosos e localiza-se na superfície plantar.","C":"A dermatoscopia do CEC invasivo revela vasos lineares irregulares, vasos em grampo,\narboriformes e glomerulares e, quando\npigmentados, há presença de glóbulos azul- acinzentados.","D":"O uso do micofenolato de mofetil e do sirolimus tem contribuído para o aumento da sua\nincidência."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317770","number":"317770","sourceNumber":"317770","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando o dermatofibroma, que é um tumor fibro-histiocitário benigno de etiologia\ndesconhecida, assinale a alternativa CORRETA.","options":{"A":"Lesão de crescimento rápido e que se assemelha a um tumor vascular; corresponde ao tipo\nhistológico aneurismático.","B":"A realização do estudo imunoistoquímico é essencial para diferenciar de tumores\nbro-histiocitários malignos (fator VIIIA e CD34 positivos).","C":"A variante celular, denominada de bro-histiocitoma, caracteriza-se pela grande quantidade de\ncolágeno presente.","D":"Na histopatologia, observam-se hiperplasia de epiderme, hipopigmentação da camada basal,\nseparada por uma zona escura (Grenz) da derme."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317771","number":"317771","sourceNumber":"317771","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise as informações a seguir. Tumor que predomina no sexo masculino, em torno da\nsexta e sétima décadas de vida. As áreas fotoexpostas são, frequentemente, as mais acometidas.\nNo exame histopatológico, há presença de células alongadas e amelanóticas envoltas por estroma\ndensamente fibroso. Apesar de apresentar pouca atipia citológica, seu comportamento é agressivo,\ncom grande tendência à recidiva local. Considerando essas informações, assinale a alternativa que\nindica a que tipo de melanoma elas estão relacionadas.","options":{"A":"Dérmico primário","B":"Desmoplásico","C":"Nevoide","D":"Spitizoide"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317772","number":"317772","sourceNumber":"317772","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao melanoma cutâneo, assinale a alternativa que corresponde a um pior\nprognóstico.","options":{"A":"índice de Breslow de 3,0 mm, fase vertical de crescimento, com regressão.","B":"índice de Breslow de 1,2 mm, ausência de mitoses, com satelitose.","C":"índice de Breslow de 0,8 mm, infiltrado linfocítico, com ulceração.","D":"índice de Breslow de 1,0 mm, nível de Clark IV, 3 mitoses/mm2"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317773","number":"317773","sourceNumber":"317773","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre os procedimentos a seguir, assinale a alternativa INCORRETA.","options":{"A":"Está contraindicado o uso da radiofrequência em pacientes portadores de marca-passo e nas\náreas de implantes metálicos.","B":"Os melhores resultados na remoção dos pelos são obtidos nos pacientes com pele clara\n(fototipos l-lll) e pelos marrom-escuros a pretos.","C":"As tatuagens amadoras, que contêm mais pigmentos pretos e azuis, baseados em carbono, são\nmais difíceis de serem removidas com laser.","D":"Pulsed Dye Laser (PDL) com comprimento de onda de 585 e 595 nm é o mais eficaz no\ntratamento das manchas vinho do Porto."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317774","number":"317774","sourceNumber":"317774","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Linfocitoma cútis é um pseudolinfoma de células B que ocorre em resposta a estímulos\nconhecidos e desconhecidos. A maioria dos casos é idiopática. Em relação aos aspectos a seguir,\nassinale a alternativa INCORRETA.","options":{"A":"Ocorre em qualquer idade, sendo mais frequente em mulheres acima dos 60 anos.","B":"Lesões de localização extrafacial são mais comuns no tronco e nos membros superiores.","C":"Manifestações com pápulas medindo alguns milímetros de diâmetro, disseminadas, são\ndenominadas como linfocitoma miliar cútis.","D":"Lesões papulosas ou nodulares, únicas ou múltiplas, de forma localizada, são mais frequentes\nque a forma generalizada."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317775","number":"317775","sourceNumber":"317775","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Hiperqueratose e papilomatose, com agregados de células pequenas em meio à\nepiderme (fenômeno de Borst Jadassohn), são encontradas no seguinte subtipo de queratose\nseborreica:","options":{"A":"clonal.","B":"acantótico.","C":"melanoacantoma.","D":"adenoide."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317776","number":"317776","sourceNumber":"317776","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto à má-formação vascular, assinale a alternativa CORRETA.","options":{"A":"Ocorre com mais frequência nos prematuros.","B":"O ciclo das células endoteliais é normal.","C":"Há tendência à involução espontânea.","D":"A resposta é adequada à corticoterapia."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317777","number":"317777","sourceNumber":"317777","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatomiosite, assinale a alternativa INCORRETA.","options":{"A":"As lesões do couro cabeludo fazem diagnóstico diferencial com a dermatite seborreica e a\npsoríase.","B":"A perfuração de septo nasal, o líquen plano, a doença de Degos e o eritema centrífugo flagelado\npodem estar associados à dermatomiosite.","C":"Os quadros de artralgia são frequentes, e artrites, quando presentes, são geralmente erosivas e\ndeformantes e com intensa sinovite.","D":"O acometimento dos músculos faciais e bulbares geralmente ocorre quando há associação com\nneoplasia ou miastenia."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317778","number":"317778","sourceNumber":"317778","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao lúpus eritematoso, numere a COLUNA II de acordo com a COLUNA I.\nCOLUNA I 1. Anticorpo Anti-Ds-DNA; 2. Anticorpo Anti-Sm; 3. Anticorpo Anti-MA; 4. Anticorpo\n\nAnti-RO-ssA; COLUNA II ( ) Lúpus neonatal; ( ) Específico LE sistêmico; ( ) Maior probabilidade de\nlesão neurológica; ( ) Acometimento renal. Assinale a sequência CORRETA.","options":{"A":"4 2 3 1","B":"2 4 1 3","C":"4 1 3 2","D":"1 3 4 2"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317779","number":"317779","sourceNumber":"317779","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às micobacterioses, assinale a alternativa INCORRETA.","options":{"A":"A produção do fator de necrose tumoral alfa é fundamental para a formação de granulomas,\nevitando a disseminação de micobactérias.","B":"A relação linfócitos CD4+/CD8+ está aumentada no lúpus vulgar e diminuída no escrofuloderma.","C":"O Mycobacterium szulgai é o principal agente do granuloma das piscinas, sendo uma espécie de\ncrescimento rápido em meio de cultura.","D":"A infecção por Mycobacterium fortuitum pode ocorrer em implantes mamários e ablações com\nlaser de CO?."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317780","number":"317780","sourceNumber":"317780","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A respeito da coinfecção hanseníase e AIDS, assinale a alternativa CORRETA.","options":{"A":"As reações do tipo 2 da hanseníase são muito mais frequentes nos pacientes com coinfecção\ncom AIDS, comparados àqueles com hanseníase\nisolada.","B":"Devido à de ciência da imunidade celular decorrente da AIDS, a maioria dos casos de\ncoinfecção com hanseníase se dá na forma virchowiana.","C":"Os pacientes com AIDS, sob uso de TARV (tratamento antiretroviral), podem desenvolver\nquadros agudos de hanseníase pauci ou\nmultibacilares, que se enquadram na de nição de\nsíndrome da restauração imunológica.","D":"Nos casos de coinfecção, frequentemente há necessidade de tratamento mais prolongado para\na hanseníase."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317781","number":"317781","sourceNumber":"317781","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O mecanismo não imunológico envolvido nas reações adversas à drogas, caracterizado\npelas modificações do meio ambiente que favorecem o\ndesenvolvimento de certos microrganismos,\né denominado:","options":{"A":"distúrbio ecológico.","B":"intolerância.","C":"efeito colateral.","D":"biotropismo."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317782","number":"317782","sourceNumber":"317782","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere às formas clínicas da sarcoidose, assinale a alternativa CORRETA.","options":{"A":"A forma rosaceiforme simula a rosácea granulomatosa, diferindo desta pela infiltração localizada\ne super ciai.","B":"A forma angiolupoide caracteriza-se por placa eritêmato-in Itrada e ovalada na região\nnasopalpebral ou na vertente nasal, bem delimitada, de consistência endurecida, acometendo\nquase que exclusivamente o sexo masculino.","C":"O lúpus pérnio caracteriza-se por lesão localizada que acomete principalmente o tronco, com in\nItração bem de nida e pouquíssimos vasos na superfície.","D":"A manifestação hipodérmica corresponde aos antigos sarcoides subcutâneos de Darrier-Roussy,\ne é representada por nódulos bem\ncircunscritos, recobertos por pele de cor normal ou rósea."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317783","number":"317783","sourceNumber":"317783","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação ao erythema marginatum, assinale a alternativa INCORRETA.","options":{"A":"Ocorre em aproximadamente 20% dos casos de febre reumática aguda.","B":"Inicia-se como pápula ou mácula eritematosa, com forma policíclica, enquanto o centro retorna\nao normal, com bordas não induradas, que\ndesaparecem à pressão.","C":"As lesões são proeminentes pela manhã, persistentes, e desaparecem após cerca de 10 dias.","D":"São diagnósticos diferenciais: eritema anular centrífugo, eritema necrolítico, urticária anular,\neritroqueratodermia variablis e doença de Kawasaki."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317784","number":"317784","sourceNumber":"317784","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"São características clínicas da síndrome de Proteus, EXCETO:","options":{"A":"Crescimento progressivo e assimétrico de extremidades.","B":"Áreas de atro a dérmica com acentuação do padrão venoso.","C":"Hiperplasia palmoplantar cerebriforme.","D":"Ausência de acometimento de órgãos internos."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317785","number":"317785","sourceNumber":"317785","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Numere a COLUNA II de acordo com a COLUNA I, relacionando os critérios\ndermatoscópicos com suas respectivas\nrepresentações histopatológicas. COLUNA I 1. Pontos\ncinza-azulado; 2. Ninhos ovoides; 3. Pseudocomedões; 4. Estrias brancas brilhosas ou crisálidas;\nCOLUNA II ( ) Massas de células basaloides na derme. ( ) Melanófagos na derme papilar. ( ) Feixes\nde colágeno birrefringentes observados apenas com a luz polarizada. ( ) Acúmulo de queratina nas\naberturas foliculares dilatadas. Assinale a sequência CORRETA.","options":{"A":"1 2 3 4","B":"2 1 4 3","C":"4 1 3 2","D":"3 4 2 1"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317786","number":"317786","sourceNumber":"317786","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando um paciente com uma ferida cutânea pouco exsudativa, qual curativo é\nmais indicado?","options":{"A":"Alginato de cálcio.","B":"Combinado com colágeno.","C":"Hidrocoloide.","D":"Carvão ativado."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317787","number":"317787","sourceNumber":"317787","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na dermatite atópica, é CORRETO afirmar que ocorre aumento da:","options":{"A":"resposta de hipersensibilidade retardada.","B":"sensibilização (dinitroclorobenzeno) pelo DNCB","C":"atividade da enzima fosfodiesterase.","D":"resposta in vitro dos linfócitos a antígenos microbianos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317788","number":"317788","sourceNumber":"317788","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatite seborreica, assinale a alternativa INCORRETA.","options":{"A":"A incidência está elevada na doença de Parkinson, na epilepsia, no infarto agudo do miocárdio e\nnos pacientes em uso de cimetidina.","B":"O aumento dos triglicerídeos e do colesterol com diminuição do esqualeno e ácidos graxos livres\né observado na secreção sebácea.","C":"A exposição ao Sol diminui sua intensidade, enquanto o frio, o stress emocional e físico agravam\no quadro clínico.","D":"A forma infantil tem correlação com a dermatite seborreica do adulto."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317789","number":"317789","sourceNumber":"317789","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"São critérios diagnósticos para a dermatite infectiva, EXCETO:","options":{"A":"Rinorreia crônica.","B":"Febre elevada.","C":"Pronta resposta à terapia antibacteriana.","D":"Soro positividade para HTLV-1."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317790","number":"317790","sourceNumber":"317790","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando os retalhos cutâneos, é CORRETO afirmar:","options":{"A":"Na dinâmica dos retalhos, existem dois movimentos: o primário, que representa seu próprio\nmovimento, e o secundário, gerado pelo deslocamento da pele ao redor do defeito cirúrgico.","B":"A elasticidade e a mobilidade da pele a ser utilizada são maiores em pacientes jovens quando\ncomparadas a dos idosos.","C":"A relação entre o comprimento do retalho e o tamanho do pedículo deve ser em torno de 3:1,\nmas quando há uma artéria na base do pedículo, esta relação deve ser menor.","D":"De acordo com a movimentação, os retalhos são classificados em parcial e total."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317791","number":"317791","sourceNumber":"317791","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação ao eritema nodoso, é INCORRETO afirmar:","options":{"A":"Trata-se de uma paniculite lobular. Septal","B":"Pode estar associado à sarcoidose e à hanseníase.","C":"Há infiltrado neutrofilico nas lesões iniciais.","D":"Representa uma resposta hipersensibilidade retardada."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317792","number":"317792","sourceNumber":"317792","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa que não apresenta uma característica das erupções acneiformes.","options":{"A":"Surgem abruptamente.","B":"Há ausência de comedões.","C":"Ocorrem em áreas típicas da acne vulgar.","D":"As lesões são pápulo-pustulosas, de caráter monomorfo."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317793","number":"317793","sourceNumber":"317793","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Numere a COLUNA I de acordo com a COLUNA II, relacionando a droga com seu efeito\ncolateral. COLUNA I 1. Ciclofosfamida 2. Isotretinoína; 3. Hidantoína; 4. Cloroquina; COLUNA II ( )\nEflúvio telógeno; ( ) Hipertricose; ( ) Alterações da cor do cabelo; ( ) Eflúvio anágeno; Assinale a\nsequência CORRETA.","options":{"A":"1234","B":"2341","C":"3412","D":"4123"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317794","number":"317794","sourceNumber":"317794","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a acne da mulher adulta, assinale a alternativa INCORRETA.","options":{"A":"As lesões inflamatórias localizam-se especialmente no terço inferior da face.","B":"O grau de oleosidade facial é menor do que nos casos da acne juvenil.","C":"O surgimento é súbito com ou sem história de acne na adolescência.","D":"Quando associada à síndrome do ovário policístico, há diminuição da relação LH/FSH."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317795","number":"317795","sourceNumber":"317795","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à acne fulminans, assinale a alternativa INCORRETA.","options":{"A":"Há associação com hepatoesplenomegalia.","B":"O acometimento ósseo é frequente.","C":"Ocorre mais no tórax e dorso.","D":"É mais comum em jovens do sexo feminino."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317796","number":"317796","sourceNumber":"317796","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre as dermatozoonoses, assinale a alternativa INCORRETA.","options":{"A":"Na miíase migratória, há a deposição de ovos da Dermatobia hominis que provoca uma erupção\nserpiginosa na pele humana.","B":"Na tungíase, o quadro clínico é produzido pela fêmea da Tunga penetrans que se fixa na pele do\nhospedeiro com a finalidade de ovulação.","C":"Na dermatite vesicante por Paederus, a responsável pelo surgimento das lesões é a pederina\nque é liberada quando o inseto é tocado ou\nesmagado.","D":"Na demodecidose, o Demodex foliiculorum é observado no infundíbulo folicular, e o Demodex\nbrevis, nos duetos sebáceos e nas glândulas de Meibomio."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317797","number":"317797","sourceNumber":"317797","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à escabiose, assinale a alternativa INCORRETA.","options":{"A":"A sarna crostosa ocorre em indivíduos neuropatas e pode ser uma manifestação da infecção\npelo HTLV-1.","B":"O prurido é desencadeado por um mecanismo alérgico e outro mecânico.","C":"O efeito antabuse associado ao monosulfiram pode ocorrer quando da ingesta de álcool até 10\ndias após a aplicação da medicação.","D":"A ivermectina oral está indicada no tratamento de crianças, a partir dos 6 meses de idade."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317798","number":"317798","sourceNumber":"317798","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise o caso clínico a seguir. Paciente, sexo masculino, agricultor, apresenta, há\ncerca de seis meses, aumento do volume do pé\nesquerdo acompanhado de lesões nodulares e\ngomosas que eliminam material espesso e grãos de coloração preta. O exame microscópico direto\na fresco demonstrou grãos compostos por filamentos micelianos de parede dupla, clamidósporos\nabundantes e ausência de clavas. A cultura em ágar Sabouraud dextrose apresentou-se como\nbranca com micélio aéreo curto cinza e na microcultura observou-se conidióforos simples e\nconídios ovais. O exame histopatológico demonstrou processo inflamatório supurativo ao redor do\ngrão. Considerando esse caso, assinale a alternativa que apresenta o agente etiológico desse\nmicetoma eumicótico.","options":{"A":"Madurella grisea","B":"Madurella mycetomatis","C":"Acremonium recifeii","D":"Pseudallescheria boydii"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317799","number":"317799","sourceNumber":"317799","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre as dermatofitoses, é CORRETO afirmar:","options":{"A":"Na tinha do couro cabeludo microspórica, as lesões são múltiplas enquanto na tricofítica é\núnica.","B":"A tinha do corpo tem como variante clínica o granuloma de Majocchi, usualmente causado pelo\nTrichophyton Rubrum.","C":"A tinha favosa causada pelo Trichophyton concentricum é considerada rara nos dias de hoje.","D":"A tinha imbricada, também denominada de ?chimberê?, tem como agente etiológico o\nMicrosporum gypseum."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317800","number":"317800","sourceNumber":"317800","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando o diagnóstico etiológico da cromoblastomicose, é CORRETO afirmar:","options":{"A":"No Brasil, o agente etiológico predominante é Chadophialophora carrionii.","B":"Os agentes etiológicos apresentam aspecto macromorfológico semelhante na cultura, sendo\nnecessário o microcultivo para o diagnóstico da espécie.","C":"A espécie Fonsecaea pedrosoi apresenta mais frequentemente a esporulação tipo phialophora.","D":"Na espoluração tipo cladosporium, o conidióforo tem aspecto de vaso, e os esporos se agrupam\nno topo ou ao seu redor."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317801","number":"317801","sourceNumber":"317801","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às psicodermatoses, é CORRETO afirmar:","options":{"A":"A dismorfofobia assemelha-se à distorção da imagem corporal da anorexia.","B":"A tricotilomania da criança é mais comum em meninos, sendo incomum a resolução espontânea.","C":"Na dermatite artefacta, observam-selesões simétricas ao alcance do membro superior\ndominante.","D":"Na pantomínia, o paciente agrava uma lesão já existente, que passa a ter aspecto bizarro."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317802","number":"317802","sourceNumber":"317802","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança do sexo masculino, branca, nascida a termo, bom estado geral, afebril,\napresenta no terceiro dia de vida quadro\ncutâneo composto de máculas eritematosas localizadas\nno tronco, algumas delas encimadas por pústulas de nítida localização folicular. O exame\nhistopatológico revelou acúmulo intrafolicular maciço de eosinófilos, e o quadro apresentou\nregressão espontânea aos 15 dias de vida. Diante desse quadro, assinale a alternativa que\napresenta a hipótese diagnóstica desse paciente.","options":{"A":"Melanose pustulosa transitória","B":"Miliária rubra","C":"Eritematóxicodorecém-nascido","D":"Foliculitepustulosaeosinofílica"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317723","number":"317723","sourceNumber":"317723","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto à foliculite dissecante, assinale a alternativa CORRETA.","options":{"A":"Ao exame anatomopatológico, o infiltrado é predominantemente neutrofílico.","B":"Os fios íntegros estão presentes em todas as fases da doença.","C":"O tratamento inicial de eleição é a corticoterapia sistêmica.","D":"É mais frequente em mulheres caucasianas com cabelos lisos."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317803","number":"317803","sourceNumber":"317803","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O achado de vasos em coroa à dermatoscopia é característico de:","options":{"A":"melanoma fino.","B":"hiperplasia sebácea.","C":"doença de Bowen.","D":"granuloma piogênico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317724","number":"317724","sourceNumber":"317724","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre as lesões elementares ungueais e suas características clínicas, numere a\nCOLUNA II de acordo com a COLUNA I. COLUNA\nI 1. Traquioníquia 2. Onicomadese 3. Linhas de\nBeau 4. Coiloníquia; COLUNA II ( ) Placa ungueal destacada da prega ungueal proximal ( ) Sulcos\ntransversais da placa ungueal ( ) Placa ungueal fina e côncava ( ) Estrias longitudinais finas com\naspecto rugoso Assinale a sequência CORRETA.","options":{"A":"2 3 4 1","B":"3 2 1 4","C":"4 2 1 3","D":"2 3 1 4"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317804","number":"317804","sourceNumber":"317804","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às características clínicas da síndrome de Sweet, assinale a alternativa\nINCORRETA.","options":{"A":"O estado geral é comprometido, com febre, prostração e mialgia.","B":"As lesões cutâneas acometem preferencialmente os membros inferiores.","C":"O fenômeno de patergia ocorre, assim como no pioderma gangrenoso.","D":"O acometimento oral é mais comum quando há doença hematológica associada."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317725","number":"317725","sourceNumber":"317725","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As alterações ungueais mais frequentemente encontradas em pacientes com alopecia\nareata são:","options":{"A":"pitting geométrico, lúnulas estriadas e traquioníquia.","B":"pitting grosseiro, onicólise e linhas de beau.","C":"hiperqueratose subungueal, onicólise e traquioníquia.","D":"espessamento da placa ungueal, coiloníquia e cavitações da placa."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317805","number":"317805","sourceNumber":"317805","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Diante de uma suspeita clínica de mastocitose, qual tipo de coloração pode auxiliar no\nexame histopatológico?","options":{"A":"Vermelho Congo.","B":"Azul de toluidina.","C":"Sudan (Sudan black).","D":"Tricrômico de Masson."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317726","number":"317726","sourceNumber":"317726","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As deficiências de vitaminas do complexo B podem causar diferentes quadros\ncutâneos. A esse respeito, numere a COLUNA\nII de acordo com a COLUNA I, correlacionando as\ndermatoses citadas às deficiências das vitaminas. COLUNA I 1. Vitamina B1 (tiamina) 2. Vitamina\nB2 (riboflavina) 3. Vitamina B3 (niacina) 4. Vitamina B12(cianocobalamina); COLUNA II ( ) Pelagra (\n\n) Dermatite seborreica, queilite angular, queratodermia palmoplantar ( ) Hiperpigmentação, glossite,\nestomatite angular, canice ( ) Síndrome óculo-oro-genital Assinale a sequência CORRETA.","options":{"A":"3 1 4 2","B":"2 3 1 4","C":"3 1 2 4","D":"4 2 1 3"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317806","number":"317806","sourceNumber":"317806","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa cujo marcador imunoistoquímico é indicativo de proliferação\ncelular.","options":{"A":"CK7","B":"Melan A","C":"Ki67","D":"CD34"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317727","number":"317727","sourceNumber":"317727","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à acroceratose paraneoplásica de Bazex, assinale a alternativa CORRETA.","options":{"A":"A doença acompanha o curso da neoplasia, mas as lesões podem persistir mesmo após a cura\ndo tumor.","B":"Acomete preferencialmente o tronco, apresentando lesões vesicobolhosas pruriginosas.","C":"O exame histopatológico é considerado padrão ouro, sendo mandatório e essencial para o\ndiagnóstico.","D":"Associa-se preferencialmente com tumores localizados no trato digestivo baixo."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317807","number":"317807","sourceNumber":"317807","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa que representa o padrão clínico que pode ser encontrado no\nmosaicismo cutâneo.","options":{"A":"Filoide","B":"Anular","C":"Zosteriforme","D":"Reticular"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317728","number":"317728","sourceNumber":"317728","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere às escalas de avaliação de severidade para psoríase, assinale a\nalternativa CORRETA.","options":{"A":"O PASI avalia o grau de descamação, eritema e infiltração das placas de cada segmento\ncorpóreo, multiplicado pela área de acometimento.","B":"O BSA considera a área corporal comprometida em qualquer tipo de psoríase.","C":"Um PASI de 8 corresponde à psoríase grave.","D":"Um BSA de 11 corresponde à psoríase leve."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317808","number":"317808","sourceNumber":"317808","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatose bolhosa crônica da infância, assinale a alternativa\nINCORRETA.","options":{"A":"Há presença de bolha subepidérmica.","B":"Há acometimento mucoso.","C":"A imuno fluorescência direta é positiva para IgG.","D":"Há tendência à remissão."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317729","number":"317729","sourceNumber":"317729","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual dos seguintes imunobiológicos inibe diretamente a IL-23?","options":{"A":"Adalimumab","B":"Infliximab","C":"Ustekinumab","D":"Secukinumab"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317809","number":"317809","sourceNumber":"317809","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando o xantogranuloma juvenil, é CORRETO afirmar:","options":{"A":"A dislipidemia pode preceder as lesões cutâneas.","B":"O encontro de células de Touton na histopatologia é característico.","C":"As células são CD1a positivas na imunoistoquímica.","D":"Ocorre mais frequentemente nos membros inferiores."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317730","number":"317730","sourceNumber":"317730","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à cirurgia micrográfica de Mohs, assinale a alternativa INCORRETA.","options":{"A":"Nos tumores recidivados, o emprego dessa cirurgia resulta em maiores índices de cura.","B":"Tem indicação nos casos de CBC metatípicos e esclerodermiformes.","C":"Permite uma melhor preservação tecidual em tumores localizados nas extremidades.","D":"No dermatofibrossarcoma protuberante, os índices de cura são semelhantes aos obtidos com a\ncirurgia convencional."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317810","number":"317810","sourceNumber":"317810","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A mastocitose pode ser desencadeada por algumas substâncias. Assinale a substância\nque não está associada à exacerbação do quadro\ncutâneo.","options":{"A":"Álcool","B":"Hioscina","C":"Contrastes iodados","D":"Cromoglicato de sódio"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317731","number":"317731","sourceNumber":"317731","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação ao tratamento cirúrgico dos carcinomas basocelulares, assinale a\nalternativa INCORRETA.","options":{"A":"O conhecimento prévio do tipo histológico do tumor por meio de biópsia está indicado,\npodendo-se utilizar um punch ou shaving da lesão.","B":"A técnica de shaving no diagnóstico de tumores pode resultar em resultado falso-negativo,\nprincipalmente tratando-se de lesões recidivadas, em\nque existe a possibilidade de crescimento da\nlesão para planos mais profundos, como no subcutâneo.","C":"São consideradas áreas de risco para recidiva dos tumores: nariz, orelha, fronte, couro cabeludo\ne sulcos embrionários (sulco nasogeniano,\npré-auricular e canto interno dos olhos).","D":"A curetagem e a eletrocoagulação são técnicas amplamente utilizadas pelos dermatologistas e\npodem ser usadas em casos de carcinomas\nbasocelulares nodulares e esclerodermiformes, já que\nos estromas desses tumores são ricos em fibrose."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317811","number":"317811","sourceNumber":"317811","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à neuropatia hansênica, é INCORRETO afirmar:","options":{"A":"Na forma tuberculoide, a lesão neural cursa com reação granulomatosa e, em alguns casos,\nnecrose dos nervos super ciais e profundos.","B":"Na forma borderline, vários troncos nervosos podem ser afetados, com maior incidência de\nmononeuropatias múltiplas.","C":"Na forma indeterminada, os ramos super ciais dos nervos são comprometidos, sendo poupados\nos troncos neurais.","D":"Na forma virchowiana, o comprometimento neural é, na maioria dos casos, assimétrico, isolado\ne unilateral."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317732","number":"317732","sourceNumber":"317732","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No pós-operatório da fenolização da matriz ungueal para correção da unha encravada,\né comum a ocorrência de alguns sinais e\nsintomas. Assinale a alternativa que apresenta o sinal /\nsintoma menos provável de ocorrer nesse caso.","options":{"A":"Inflamação da dobra ungueal lateral e proximal.","B":"Exsudação da ferida cirúrgica por, em média, 15 dias.","C":"Dor intensa por 10 dias.","D":"Queimadura da borda da ferida em caso de excesso de fenol no aplicador."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317812","number":"317812","sourceNumber":"317812","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à imunologia da hanseníase, assinale a alternativa CORRETA.","options":{"A":"Os pacientes com a forma tuberculoide desenvolvem vigorosa resposta imune celular do tipo\nTh1, com produção, em grande magnitude, das citocinas IL-10, TGF-?, TNF-? e IL-2.","B":"Os pacientes com a forma virchowiana desenvolvem resposta imune do tipo Th2, com\nimportante produção das citocinas IFN-Y, IL2, TNF-?, IL-4.","C":"Os pacientes com formas multibacilares apresentam maior soropositividade de anticorpos\nanti-PGL-1 que os pacientes paucibacilares.","D":"Na reação tipo 1, ocorre exacerbação da resposta imune do tipo Th2, capaz de produzir danos\nirreversíveis aos nervos periféricos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317733","number":"317733","sourceNumber":"317733","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na dermatite de contato alérgica a luvas de borracha, o sensibilizante mais comum é:","options":{"A":"parabenos.","B":"tiuram mix.","C":"prometazina.","D":"butilfenol-p-terciário."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317813","number":"317813","sourceNumber":"317813","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Numere a COLUNA II de acordo com a COLUNA I, relacionando as colorações\nespeciais com as suas possíveis aplicações nos\nseguintes diagnósticos. COLUNA I 1. Alcian blue;\n\n2. Verhoeff; 3. Azul da Prússia; 4. Tricrômio de Masson; COLUNA II; ( ) Leiomiomas; ( ) Granuloma\nanular; ( ) Sarcoma de Kaposi; ( )\nAnetodermia; Assinale a sequência CORRETA.","options":{"A":"1 4 2 3","B":"2 3 1 4","C":"3 1 4 2","D":"4 2 3 1"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317734","number":"317734","sourceNumber":"317734","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere à dermatite atópica, assinale a alternativa CORRETA.","options":{"A":"A IL-4 atua na expressão da filagrina, colaborando no defeito de barreira.","B":"A polarização para resposta Th1 é promovida pelas células de Langerhans.","C":"Os ceratinócitos produzem baixos níveis de linfopoietina estromal tímica.","D":"O IFN-? e o IL-12 predominam nas lesões agudas da doença."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317814","number":"317814","sourceNumber":"317814","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A respeito da acrodermatite enteropática, assinale a alternativa INCORRETA.","options":{"A":"Quando hereditária, tem caráter autossômico recessivo.","B":"As lesões surgem após a retirada do leite materno.","C":"O crescimento e o desenvolvimento do indivíduo são normais.","D":"Há maior predisposição às infecções fúngicas e bacterianas."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317735","number":"317735","sourceNumber":"317735","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa que contém fungos demáceos.","options":{"A":"Acremonium recifei e Aspergilllus spp","B":"Scytalidium dimidiatum e Alternaria spp","C":"Scopulariopsis brevicallis e Penicillium spp","D":"Fusarium spp e Scedosporium spp"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317815","number":"317815","sourceNumber":"317815","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a unidade epidermo-melânica, assinale a alternativa CORRETA.","options":{"A":"É formada pela associação do melanócito com queratinócitos presentes apenas na camada\nbasal da epiderme.","B":"A interação entre os melanócitos e os queratinócitos se dá através da via das caderinas.","C":"A densidade dos melanócitos na epiderme por milímetro quadrado não varia de acordo com a\nlocalização anatômica no mesmo indivíduo.","D":"O principal fator determinante da cor da pele normal é a densidade dos melanócitos na\nepiderme."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317736","number":"317736","sourceNumber":"317736","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere às formas clínicas da candidíase, assinale a alternativa CORRETA.","options":{"A":"A aguda atrófica eritematosa ocorre na mucosa vaginal.","B":"A mucocutânea crônica familiar é de herança autossômica dominante.","C":"A hiperplásica crônica ocorre em adultos associada ao fumo.","D":"A da área das fraldas tem pico de incidência entre o 6o e 7o mês de vida."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317816","number":"317816","sourceNumber":"317816","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à adiponecrose do recém-nascido, assinale a alternativa INCORRETA.","options":{"A":"A resolução espontânea é comum.","B":"As lesões têm uma distribuição frequentemente simétrica.","C":"Há associação com hipercalcemia.","D":"Ocorre mais comumente em recém-nascidos pré-termo."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317737","number":"317737","sourceNumber":"317737","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à paracoccidioidomicose, assinale a alternativa CORRETA.","options":{"A":"Na parede celular do fungo, o polissacarídeo ?1-3 glucana ocorre na fase miceliana.","B":"A forma clínica aguda-subaguda ocorre em jovens, sendo o quadro mucoso frequente.","C":"A colônia do P. brasiliensis em temperatura ambiente é de cor creme e de aspecto cerebriforme.","D":"Nível a partir de 200 mg% de ureia é indicativo de redução da dose diária de anfotericina B."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317817","number":"317817","sourceNumber":"317817","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à doença de Kyrle, assinale a alternativa INCORRETA.","options":{"A":"Acomete frequentemente pacientes renais crônicos ou diabéticos com algum grau de nefropatia.","B":"Ocorre em associação com doenças pruriginosas, como escabiose, picadas de inseto ou\nlinfoma.","C":"Surge em regiões previamente sujeitas a traumatismos ou em pacientes que fazem uso de\ninibidores do TNF alfa ou indinavir.","D":"O sítio anatômico frequentemente acometido é o dorso e o abdome."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319759","number":"319759","sourceNumber":"319759","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às variantes clínicas do líquen plano, assinale a alternativa correta.","options":{"A":"A hipertrófica localiza-se principalmente nos membros superiores e costuma regredir deixando\nsequelas hipertróficas ou hipopigmentação.","B":"A folicular é mais frequente nos homens e apresenta duas alterações típicas à dermatoscopia:\nalargamento dos óstios foliculares e pontos pretos.","C":"A das mucosas compromete mais a mucosa bucal, sendo a forma clínica reticulada a\napresentação mais comum.","D":"A ungueal apresenta-se comumente como a única manifestação da doença, apresentando\nfissuras e pterígio quando compromete o leito\nungueal."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317738","number":"317738","sourceNumber":"317738","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação às reações adversas a drogas, assinale a alternativa CORRETA.","options":{"A":"O intertrigo induzido por droga é caracterizado por eritema assimétrico na região glútea e / ou\nperianal, acompanhado de prurido.","B":"O pênfigo induzido por drogas apresenta caracteristicamente lesões da forma vulgar, com\nimunofluorescência direta em pele perilesional negativa.","C":"O penfigoide bolhoso induzido por drogas apresenta lesões semelhantes à forma clássica da\ndoença ou ao eritema polimorfo.","D":"O lúpus eritematoso sistêmico induzido por droga, à semelhança da forma clássica da doença, é\nmais comum em mulheres."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317818","number":"317818","sourceNumber":"317818","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a síndrome do choque tóxico estafilocócico, é CORRETO afirmar:","options":{"A":"A enterotoxina C? é a mais frequentemente envolvida.","B":"Há eritema difuso acompanhado de edema palmoplantar.","C":"Em geral, não há comprometimento muscular nem hepático.","D":"A maioria dos casos ocorre no sexo masculino."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319760","number":"319760","sourceNumber":"319760","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação ao sarampo, assinale a alternativa correta.","options":{"A":"A sorologia para anticorpos IgM é o teste padrão ouro para o diagnóstico, o qual também pode\nse dar com RT-PCR em swab da nasofaringe e\nsorologia para anticorpos IgG, com aumento de\ntítulos em mais de quatro vezes em coletas seriadas.","B":"É causado por um vírus DNA, de hélice dupla, com 28 genótipos, que, quando expelido por\ngotículas de saliva, pode permanecer vivo por até dois dias em superfície ou no ar.","C":"O período de incubação varia de dois a cinco dias até o surgimento da febre e até sete dias para\no início do exantema, sendo o período de\ntransmissão de dois dias antes do início do exantema até\ndois dias após o desaparecimento deste.","D":"O sinal de Koplik surge cerca de três dias após o início do exantema, o qual é\ncaracteristicamente máculo-pápulo-vesiculoso, iniciando no\ntronco e podendo durar de oito a dez\ndias, quando começa o período de convalescença."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317739","number":"317739","sourceNumber":"317739","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O eflúvio anágeno induzido por drogas pode estar associado a:","options":{"A":"heparina.","B":"colchicina.","C":"arsênico.","D":"piroxican."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317819","number":"317819","sourceNumber":"317819","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 4 meses apresenta hemangioma infantil combinado ocupando toda a região\nperiorbital direita. Devido ao risco de complicações oftalmológicas, o tratamento de escolha para\nesse caso é:","options":{"A":"interferon.","B":"vincristina.","C":"exérese cirúrgica.","D":"betabloqueador oral."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319761","number":"319761","sourceNumber":"319761","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à epidemiologia das micobacterioses não tuberculose, assinale a\nalternativa incorreta.","options":{"A":"O complexo Mycobacterium fortuitum infecta pacientes imunocompetentes, por meio de\nimplantes mamários, cateteres e laser de CO2.","B":"O complexo Mycobacterium avium acomete ossos, linfonodos e pele, ocorrendo comumente em\npacientes com AIDS em estágio terminal.","C":"O M. ulcerans é encontrado em regiões de temperaturas mais baixas. As lesões evoluem em\npoucos dias para úlceras, mas não acometem\nossos ou músculos.","D":"O M. marinum,é responsável pela doença chamada de granuloma de piscina ou doença dos\naquários, e possui patogênese semelhante ao M. tuberculosis."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317740","number":"317740","sourceNumber":"317740","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto às reações adversas às drogas utilizadas no tratamento da infecção pelo HIV,\nassinale a alternativa CORRETA.","options":{"A":"A hiperpigmentação palmoplantar está relacionada ao didanosina.","B":"A lipodistrofia está associada ao tenofovir.","C":"O abacavir é associado à pigmentação marrom azulada das unhas.","D":"A paroníquia é observada em pacientes usando o lamivudina."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317820","number":"317820","sourceNumber":"317820","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre os nevos melanocíticos adquiridos na infância, é CORRETO afirmar que:","options":{"A":"quando S-100 positivos, o risco de malignização na vida adulta é maior.","B":"a maioria corresponde histologicamente a nevos intradérmicos.","C":"o padrão dermatoscópico globular é o mais comumente identi cado.","D":"o couro cabeludo é um local raramente acometido."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319762","number":"319762","sourceNumber":"319762","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às dermatoses pruriginosas de causas sistêmicas, assinale a alternativa\ncorreta.","options":{"A":"O prurido urêmico ocorre em 5 a 10% dos pacientes dialíticos, sendo mais importante em\nmembros inferiores, e tende a melhorar no momento da diálise.","B":"O prurido colestático é localizado, predominantemente no tronco, e responde bem ao uso da\ncolestiramina nos casos de obstrução completa das vias biliares.","C":"O prurido do linfoma de Hodgkin precede o linfoma em alguns anos, predominando em membros\ninferiores, sendo proporcional ao avanço da doença.","D":"O prurido gravídico está relacionado à diminuição da função renal, à maior produção de\nprogesterona e ocorre no início da gravidez."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317741","number":"317741","sourceNumber":"317741","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere à incontinência pigmentar, assinale a alternativa INCORRETA.","options":{"A":"É de herança dominante ligada ao X.","B":"As lesões distribuem-se seguindo as linhas de Blaschko.","C":"Na fase vesicular, há lesões principalmente nos membros inferiores.","D":"Histologicamente, na fase macular há espongiose e infiltrado de neutrófilos."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317821","number":"317821","sourceNumber":"317821","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à sífilis, assinale a alternativa INCORRETA.","options":{"A":"Na neurosí lis parenquimatosa, a demência paralítica é uma meningoencefalite crônica com\ncomprometimento progressivo das funções psíquicas.","B":"Na tabes dorsalis, a presença do sinal de Romberg é pouco frequente.","C":"Na forma tardia, a presença de goma localizada na região peniana constitui o chamado\npseudocancro redoux.","D":"Na forma cardiovascular, a porção ascendente da aorta é a região mais acometida,\nespecialmente sua raiz, por ser a parte mais rica em vasa vasorum."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319763","number":"319763","sourceNumber":"319763","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à infecção pelo citomegalovírus (CMV), assinale a alternativa correta.","options":{"A":"É considerada a principal causa infecciosa de surdez congênita e retardo mental, fazendo parte\ndas doenças congênitas conhecidas como TORCH.","B":"Mesmo em hospedeiros imunocompetentes, cerca de 95% das infecções são sintomáticas,\ncomumente evoluindo para doença grave.","C":"No diagnóstico, a histopatologia é mais sensível que a cultura do CMV, com células endoteliais\npequenas e o achado conhecido como","D":"As lesões específicas da citomegalovirose são lesões pitiríase rósea like, acompanhadas de\nlesões papulonodulares, conhecidas como redberry muffin."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317742","number":"317742","sourceNumber":"317742","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere às atrofodermias, assinale a alternativa CORRETA.","options":{"A":"AdenominaçãoAtrophoderma vermiculatum é reservada aos casos de atrofodermia folicular, nos\nquais as lesões são observadas apenas nas regiões malares.","B":"A síndrome Bazex-Dupré-Christol é caracterizada por atrofodermia em placa, hipertricose e\nhipoidrose localizada no tronco.","C":"Atrofia maculosa varioliforme cutis é caracterizada pela presença de pequenas depressões\nlineares na região pré-esternal.","D":"A síndrome de Conradi-Hünermann-Happle apresenta na infância lesões papulosas, que são\nsubstituídas na adolescência por atrofodermias segmentares."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317822","number":"317822","sourceNumber":"317822","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto ao linfoma cutâneo de células B, assinale a alternativa que representa o tipo no\nqual o comportamento clínico é mais indolente.","options":{"A":"Centro-folicular","B":"Intravascular","C":"Difuso, tipo perna","D":"De células do manto"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319764","number":"319764","sourceNumber":"319764","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às formas clínicas da tuberculose cutânea, assinale a alternativa correta.","options":{"A":"O cancro tuberculoso, resulta da inoculação direta do bacilo em hospedeiro não infectado, sendo\no complexo primário tuberculoso formado pela\nlesão ulcerada seguida do acometimento ganglionar\nregional.","B":"A tuberculose verrucosa cútis resulta de inoculação exógena em indivíduos não infectados\npreviamente ao bacilo de Koch e com baixa imunidade contra esse bacilo.","C":"No escrofuloderma, onde é rara a coexistência deste com a tuberculose óssea, ocorre mais\nacometimento de idosos que crianças e adultos jovens, sendo geralmente o PPD e IGRA fracos\nreatores nos doentes.","D":"O lúpus vulgar resulta de inoculação exógena em indivíduos com baixa imunidade contra o\nbacilo, que apresentam PPD E IGRA fracos reatores, sendo mais prevalentes em mulheres."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317743","number":"317743","sourceNumber":"317743","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à PUVA terapia, assinale a alternativa INCORRETA.","options":{"A":"É contraindicada no tratamento de psoríase em HIV+ pela maior incidência de efeitos colaterais\nnessa população.","B":"O 8-MOP deve ser administrado oralmente 1 a 3 horas antes da exposição à radiação UVA.","C":"É contraindicada em portadores de hepatite e em nefropatas.","D":"A ciclosporina não deve ser utilizada concomitante ou subsequente a essa terapia"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317823","number":"317823","sourceNumber":"317823","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à epidemiologia da leishmaniose tegumentar Americana (LTA), é\nINCORRETO afirmar:","options":{"A":"A forma anérgica difusa da LTA ocorre na Amazônia brasileira, sendo causada pelas espécies\nLeishmania (Leishmania) amazonensis e Leishmania (Viannia) braziliensis.","B":"Devido ao seu caráter ocupacional, a LTA acomete mais indivíduos do sexo masculino, na faixa\netária de 20 a 40 anos.","C":"São três os per s epidemiológicos da LTA: LTA silvestre (áreas de desmatamento recente); LTA\nsilvestre modi cada (áreas de desmatamento antigo); LTA periurbana.","D":"A leishmaniose cutânea localizada é causada, no Brasil, na maioria das regiões, pela\nLeishmania (Viannia) braziliensis; podendo\ntambém ser causada, na região Norte, pela Leishmania\n(Viannia) guyanensis, Leishmania (Leishmania) amazonensis e outras de menor importância."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319765","number":"319765","sourceNumber":"319765","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise o quadro clínico a seguir. Paciente portador de hiperidrose axilar. Foi proposto\no uso da toxina botulínica do tipo A, uma vez\nque o principal neurotransmissor das terminações\nnervosas que inervam a glândula sudorípara écrina é:","options":{"A":"serotonina.","B":"dopamina.","C":"acetilcolina.","D":"adrenalina."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317744","number":"317744","sourceNumber":"317744","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às micobacterioses não tuberculosas, assinale a alternativa INCORRETA.","options":{"A":"São reservatórios dessas micobactérias: peixes, aves, bovinos, solo, água e macaco.","B":"As infecções causadas pelo Mycobacterium fortuitum podem se dar por meio de contatos com\nimplantes mamários, injeções, cateteres, objetos de manicures e pedicures e ablação com laser de\nCO?.","C":"Na infecção pelo Mycobacterium avium, pode surgir uma erupção semelhante à tubercúlide\npapulonecrótica, descrita em pacientes com AIDS.","D":"Na infecção pelo Mycobacterium ulcerans, o tratamento de escolha é a antibioticoterapia com\nclaritromicina, não ocorrendo benefícios com a excisão cirúrgica ou oxigênio hiperbárico."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317824","number":"317824","sourceNumber":"317824","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao nevo de Becker, assinale a alternativa CORRETA.","options":{"A":"Ao exame histopatológico, os ninhos de células névicas são predominantemente juncionais.","B":"Quando firme à palpação, sugere associação com hamartoma do músculo liso.","C":"A maioria surge na primeira década de vida.","D":"A hipertricose usualmente precede a hiperpigmentação."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319766","number":"319766","sourceNumber":"319766","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Analise o quadro clínico a seguir. Paciente na 36ª semana de gestação gemelar veio\npara atendimento queixando-se de prurido intenso\nque teve início nas palmas e plantas,\ngeneralizando-se a seguir. Ao exame dermatológico, múltiplas lesões por escoriação, secundárias\nao prurido. Na 37ª semana foi necessária a antecipação do parto para não comprometer a\nvitalidade do feto. Nesse caso, qual é o diagnóstico?","options":{"A":"Penfigoide gestacional.","B":"Colestase intra-hepática.","C":"Dermatite atópica.","D":"Erupção polimórfica da gestação."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317745","number":"317745","sourceNumber":"317745","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatite artefacta ou factícia, assinale a alternativa CORRETA.","options":{"A":"O paciente admite provocar as lesões, de modo involuntário, porém sem capacidade de conter o\ndesejo.","B":"As lesões clínicas são inespecíficas e podem variar em forma, localização e profundidade.","C":"O quadro clínico não ocorre em crianças, sendo exclusivo dos adultos.","D":"O exame histopatológico apresenta achados específicos da doença."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317825","number":"317825","sourceNumber":"317825","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação aos acidentes por animais peçonhentos, assinale a alternativa\nINCORRETA.","options":{"A":"Os Millepodes, ou \"\"piolhos de cobra\"\", liberam quinonas que provocam pigmentação escura e\nnecrose superficial da pele.","B":"A pederina, existente nos besouros do gênero Paederus, tem as mesmas propriedades irritantes\ncutâneas da cantaridina.","C":"Nos acidentes agudos com peixes venenosos, a melhor conduta é a imersão do membro em\nágua fria, uma vez que os venenos são potentes\nvasodilatadores.","D":"O veneno das serpentes do gênero Bothrops tem ação proteolítica, coagulante e hemorrágica."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319767","number":"319767","sourceNumber":"319767","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No que se refere ao vitiligo segmentar em uma criança de seis anos de idade, é correto\nafirmar:","options":{"A":"A dermatose tem alta associação com hipotireoidismo.","B":"É muito estável e dificilmente ocorre a generalização da discromia.","C":"Deve ser acompanhado para surpreender diabetes insulino-dependente.","D":"O melhor tratamento, na atualidade, é feito com PUVA."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317746","number":"317746","sourceNumber":"317746","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Numere a COLUNA II de acordo com a COLUNA I, relacionando a manifestação\ndermatológica ao animal causador. COLUNA I 1.\nErupção de pápulas eritematosas e pruriginosas.\n\n2. Placa marmórea que evolui com necrose e formação de úlcera. 3. Eritema, edema e equimose\nque evoluem com bolhas e necrose. 4. Várias\npápulas eritematosas que evoluem para pústulas\nestéreis. COLUNA II ( ) Jararaca Bothrops ( ) Formiga Solenopsis ( ) Água-viva Linuche unguiculata\n( ) Aranha marrom Loxosceles Assinale a sequência CORRETA.","options":{"A":"2 1 4 3","B":"3 1 4 2","C":"3 4 1 2","D":"2 4 1 3"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317826","number":"317826","sourceNumber":"317826","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Quanto às formas clínicas da esporotricose, é INCORRETO afirmar:","options":{"A":"A forma cutâneo-localizada re ete alto grau de imunidade do hospedeiro, sendo mais\ncomumente localizada na face e nos membros.","B":"A forma cutâneo-linfática é a mais comum no nosso meio, formando cordões rijos em trajeto\nlinear, com nódulos profundos, múltiplos, muito dolorosos, que raramente ulceram, sendo, na\ngrande maioria dos casos, bilaterais.","C":"A forma cutâneo-disseminada é rara, sendo mais comum em indivíduos imunocomprometidos,\ncom lesões múltiplas, sobretudo gomas e\nabscessos, podendo ainda apresentar pápulas, nódulos\nsubcutâneos, lesões verrucosas e úlcero-vegetantes.","D":"As formas extracutâneas acometem principalmente o sistema esquelético, a boca, a faringe, o\nnariz, os olhos, os pulmões e o sistema nervoso."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-319768","number":"319768","sourceNumber":"319768","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao pioderma gangrenoso, assinale a alternativa correta.","options":{"A":"A lesão poupa a aréola mamária no tipo pós-cirúrgico na mamoplastia.","B":"Os achados anatomopatológicos são patognomônicos da doença.","C":"A etiologia exlui as doenças autoinflamatórias.","D":"Patergia negativa exclui o diagnóstico."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317747","number":"317747","sourceNumber":"317747","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à escabiose, assinale a alternativa INCORRETA.","options":{"A":"Apermetrina atua bloqueando a transmissão nas sinapses nervosas do ácaro que utilizam o\nácido ?-aminobutírico.","B":"O Sarcoptes scabiei var. hominis completa todo o seu ciclo de vida de 30 dias dentro da\nepiderme do hospedeiro.","C":"Na histopatologia, observa-se infiltrado difuso com eosinófilos, linfócitos e histiócitos na\nderme\nreticular.","D":"A sarna crostosa pode ocorrer em pacientes idosos, soropositivos e transplantados."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317827","number":"317827","sourceNumber":"317827","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à síndrome da pele excitada ao teste de contato (angry back), assinale a\nalternativa CORRETA.","options":{"A":"A repetição do patch teste está contraindicada.","B":"Relaciona-se a um pior prognóstico, com eczemas mais crônicos.","C":"Representa uma possível causa de falso-positivo.","D":"O corticoide oral é indicado devido ao risco de anafilaxia."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-263377","number":"263377","sourceNumber":"263377","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um homem com 21 anos de idade comparece à Unidade de Saúde da Família para ser\nsubmetido a tratamento cirúrgico de onicocriptose em hálux direito. Com relação à técnica a ser\nadotada para esse procedimento cirúrgico, após anestesia local, é correto","options":{"A":"realizar exérese completa da unha encravada.","B":"descolar o leito ungueal, fazendo-se uma avulsão parcial do segmento encravado.","C":"preservar a matriz ungueal e fazer a exérese em cunha do tecido de granulação.","D":"retirar uma elipse de pele e tecido subcutâneo da borda com tecido de granulação e sinais de\ninfecção local."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-263401","number":"263401","sourceNumber":"263401","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um homem com 36 anos de idade comparece à Unidade Básica de Saúde\n\nqueixando-se de lesão cutânea localizada no membro superior direito. Ele informa que, cerca de 10\ndias após realizar atividades de jardinagem em seu sítio, utilizando a enxertia de algumas de suas\nlaranjeiras, observou o aparecimento de uma pápula dolorosa no 1.º quirodáctilo direito. Nos dias\nsubsequentes, essa lesão evoluiu com ulceração local, surgindo, posteriormente, lesões similares\nno mesmo antebraço. Durante o exame, são observadas pápulas ulceradas na região assinalada,\nhavendo aspecto sugestivo de disseminação linfangítica do processo. O médico suspeita de uma\ndeterminada dermatose de etiologia infecciosa. Com base na apresentação clínica e considerando\na história epidemiológica relatada, o agente etiológico e o meio de cultura em agar adequado para\nsua detecção são, respectivamente,","options":{"A":"Nocardia asteroídes e chocolate.","B":"Sporothrix schenckii e Sabouraud.","C":"Staphylococcus aureus e Sabouraud.","D":"Mycobacterium kansasii e chocolate."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-291557","number":"291557","sourceNumber":"291557","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um homem de 40 anos de idade, que trabalha com extrativismo florestal no interior do\nestado do Amazonas, onde passa a maior parte do ano, procurou atendimento médico em Unidade\nBásica de Saúde devido à lesão exulcerada em tórax há 6 meses, evoluindo com aumento\nprogressivo. Ao exame físico, não apresenta alterações, exceto a lesão única abaixo, a qual foi\nbiopsiada. O resultado do exame histopatológico esperado para esse caso e o tratamento proposto\ndevem ser","options":{"A":"infiltrado neutrofílico com aspecto verde maçã quando corado pelo Vermelho Congo; fluconazol.","B":"células de Kupffer acompanhadas de nódulos regenerativos com áreas de fibrose; prednisona.","C":"infiltrado inflamatório inespecífico com células de Hürthle e presença de invasão vascular;\nbenzonidazol.","D":"granulomas e estruturas arredondadas compatíveis com formas amastigotas; N-metilglucamina."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/291557.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-244475","number":"244475","sourceNumber":"244475","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 43 anos de idade, trabalhador rural, procurou atendimento na unidade\nbásica de saúde em razão do aparecimento\nde múltiplos nódulos faciais se desenvolvendo nos seis\núltimos meses, associado a manchas hipocrômicas em dorso (totalizando 10 manchas), com\ndificuldade de fechamento ocular associado a conjuntivite bilateral e perda da sensibilidade em\nmãos. Ele não tinha febre, calafrios e nem sudorese noturna. Em questionamentos adicionais, ele\nadmitiu que tinha um tio com lesões faciais semelhantes. Os testes de laboratório indicaram testes\npara HIV negativos e hemograma completo normal. O médico pegou um esfregaço de pele com\ncoloração ácido-rápida das fendas das orelhas e as enviou para microscopia que revelou\nMycobacterium leprae. Considerando esse caso clínico e os conhecimentos médicos correlatos,\nassinale a alternativa correta.","options":{"A":"O paciente é portador da forma paucibacilares (PB - presença de até cinco lesões de pele)\nconforme classificação da Organização Mundial da Saúde (OMS).","B":"O tratamento da hanseníase é realizado mediante a associação de medicamentos\n(poliquimioterapia - PQT) conhecidos como rifampicina, dapsona e clofazimina.","C":"As reações hansênicas são fenômenos de aumento da atividade da doença, com melhora\nclínica da neuropatia, que podem ocorrer de\nforma aguda no início do tratamento. Pacientes com\ncarga bacilar paucibacilar (virchowianos) geralmente apresentam reações de início mais precoce do\ntratamento.","D":"A inflamação em uma lesão de pele hansênica pode ser incômoda e grave, por motivo do risco\nde gangrena vascular e acometimento circulatório do membro.","E":"A talidomida deve ser evitada nos pacientes com reação hansênica em idade abaixo de 55 anos,\nnos homens, por causa do risco de\ninfertilidade."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-244478","number":"244478","sourceNumber":"244478","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adolescente de 12 anos de idade chegou ao pronto-socorro 25 minutos após ferroada\nde abelha, com quadro de urticária gigante,\nangioedema de lábios e pálpebras, rouquidão, tosse,\nfalta de ar, estridor, cianose labial e taquicardia. Nesse caso clínico, além de oxigênio\ninalatório, a\nmelhor conduta inicial é","options":{"A":"adrenalina intramuscular.","B":"adrenalina subcutâneo.","C":"prometazina intramuscular.","D":"dexametasona intramuscular.","E":"dexclorfeniramina via oral."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-244481","number":"244481","sourceNumber":"244481","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente de 7 anos de idade foi levado ao médico com queixa de prurido importante\nno corpo há duas semanas, principalmente à\nnoite, e que atrapalha o sono. Ao exame físico,\napresenta erupções, pápulas eritemato-crostosas, túneis e escoriações em regiões de punhos,\nmãos (dedos e palmas), axilas, abdome inferior e plantas dos pés. Está febril. O irmão dele, de 5\nanos de idade, apresenta lesões semelhantes, segundo a mãe, mas de intensidade mais branda e\nde início há quatro dias. Acerca desse caso clínico, assinale a alternativa que indica,\nrespectivamente a principal hipótese diagnóstica e o tratamento sugerido.","options":{"A":"Escabiose; ivermectina oral.","B":"Dermatite de contato; hidrocortisona tópico.","C":"Varicela; banho com permanganato de potássio.","D":"Impetigo; mupirocina tópico.","E":"Pitiríase Alba; fluconazol oral."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-230585","number":"230585","sourceNumber":"230585","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente grande queimado, em 67º dia de internação em leito de terapia intensiva em\ncentro de queimados, apresentando lesão ulcerada em calcâneo direito, grande, com aspecto\nnecrótico em algumas áreas, sem melhora com as terapias tópicas prescritas. Em um\ndesbridamento foi realizado exame histopatológico que evidenciou carcinoma espinocelular.\n\nAssinale a alternativa que descreve a típica degeneração maligna de feridas crônicas não\ncicatrizadas.","options":{"A":"Úlcera de Marjolin.","B":"Úlcera de Cushing.","C":"Úlcera de Curling.","D":"Úlcera de Jhonson."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-227450","number":"227450","sourceNumber":"227450","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue o\nitem que se segue. O tratamento da hanseníase\nnão deve ser iniciado antes que se confirme o diagnóstico por baciloscopia, a fim de garantir a\nsegurança do paciente e evitar tratamento desnecessário, garantindo-se, assim, a manutenção da\nprática de prevenção quaternária na atenção APS.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212096","number":"212096","sourceNumber":"212096","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma paciente de 34 anos de idade, com derme clara, apresenta uma mancha\npigmentada, escura e irregular, que foi\npercebida há três meses na panturrilha posterior direita.\nApós avaliação clínica, foi confirmado diagnóstico de melanoma maligno em estágio IV (com\nmetástases sistêmicas). Acerca do tratamento dessa paciente, julgue o item a seguir. É\nrecomendado o uso de imunoterapia com ipilimumabe, um anticorpo monoclonal bloqueador da via\nPD-1/PD-L1 (morte celular programada).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212080","number":"212080","sourceNumber":"212080","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Julgue o item subsequente, a respeito da hanseníase. A hanseníase faz parte das\ndoenças de notificação, e de investigação\nobrigatórias. A investigação epidemiológica tem a\nfinalidade de descobrir casos entre pessoas que convivem ou conviveram com o portador de\nhanseníase e as possíveis fontes de infecção relacionadas a esses casos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212084","number":"212084","sourceNumber":"212084","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Julgue o item subsequente, a respeito da hanseníase. Uma dose da vacina BCG -\nbacilo de Calmette-Guérin - deve ser administrada para todos os familiares que tiverem contato\ncom paciente diagnosticado com hanseníase.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-177241","number":"177241","sourceNumber":"177241","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 6 meses de idade, do sexo masculino, é atendido em um hospital com\nlesões eritematopapulosas localizadas no tórax, no\nabdome e nas regiões palmoplantares, com\nintenso prurido, principalmente à noite, ao ser deitado na cama. Com base no referido caso clínico\ne nos conhecimentos médicos relativos a ele, é correto afirmar que os prováveis diagnósticos e\ntratamento para o citado paciente são, respectivamente,","options":{"A":"escabiose e ivermectina oral.","B":"tinha cutânea e cetoconazol tópico.","C":"escabiose e permetrina a 5% tópico,","D":"prurigo e corticoide tópico.","E":"tinha cutânea e clotrimazol tópico."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-183879","number":"183879","sourceNumber":"183879","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A respeito das características clínicas da hanseníase, julgue o item seguinte. Na forma\nvirchowiana ou lepromatosa, a imunidade celular ao M. leprae é praticamente ausente, as lesões\ncutâneas caracterizam-se por placas infiltradas e nódulos (hansenomas) de coloração\n\neritemato-acastanhada ou ferruginosa, com limites externos mal definidos, com distribuição\nsimétrica e localização predominante nas áreas de\nmenor temperatura, como face e glúteos,\npodendo haver madarose superciliar e ciliar, além de comprometimento simétrico dos troncos\nnervosos (em \"meias\" ou \"luvas\", por exemplo).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-157967","number":"157967","sourceNumber":"157967","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 4 meses de idade apresenta hemangioma cutâneo, único, superficial de 4\ncm de diâmetro, localizado no flanco\ndireito. Considerando esse caso clínico, assinale a alternativa\nque corresponde à conduta a ser tomada em primeiro lugar.","options":{"A":"Solicitar hemograma, função hepática e coagulograma.","B":"Requisitar ultrassonografia abdominal total.","C":"Realizar biópsia da lesão.","D":"Solicitar tomografia contrastada de abdome e de cérebro.","E":"Explicar o caráter benigno e a resolução espontânea da lesão."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-168466","number":"168466","sourceNumber":"168466","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma mulher com 60 anos de idade, previamente hígida, relata, em atendimento\nmédico, lesões cultâneas muito dolorosas no dorso,\nsurgidas há menos de 24 horas. Ao exame\nfísico, evidência-se a presença de erupção vesiculosa sobre base eritermatosa de localização\nunilateral no trajeto do dermátomo T3. Com base nessas informações e na principal hipótese\ndiagnósticada para o caso, é correto afirmar que","options":{"A":"o tratamento antiviral oral previne a dor crônica por neuralgia.","B":"a dor crônica por neuralgia é uma complicação frequente e debilitante.","C":"a amitriptilina não deve ser indicada no controle da dor crônica por neuralgia.","D":"a dor intensa provocada por neurite aguda é característica raramente presente na apresentação\nclínica."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-168502","number":"168502","sourceNumber":"168502","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um trabalhador rural com 69 anos de idade, e história de exposição prolongada ao sol,\nprocura atendimento médico devido a lesão de face demonstrada na figura abaixo (conforme\nimagem no caderno de questão). Nesse caso, que tratamento médico subsequente à biopsia\nincisional da pele e ao exame histopatológico da lesão deve ser realizado?","options":{"A":"Ressecção da lesão, com margem de 1 cm.","B":"Ressecção da lesão, com margem de 0,5 cm.","C":"Encaminhamento do paciente para radioterapia.","D":"Encaminhamento do paciente para quimioterapia."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/168502.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-159605","number":"159605","sourceNumber":"159605","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O próximo item apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a respeito da violência contra\ncrianças e adolescentes. Um lactente de oito meses de idade,\nque apresenta bolhas de graus e formas variadas e erosões em áreas de atrito, foi levado ao\nmédico pela mãe. Essas lesões começaram a ocorrer aos dois meses de idade e coincidiram com a\nchegada de uma cuidadora para criança, razão pela qual a mãe desconfia de que a criança esteja\nsendo maltratada com queimaduras intencionais por cigarro. Nesse caso, as lesões,\nprovavelmente, foram causadas por uma doença congênita de pele, e não por queimaduras\nintencionais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-129025","number":"129025","sourceNumber":"129025","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Além da medicação específica para o eczema, a hidratação da pele é a base do\ntratamento da criança atópica. Considerando\nessa informação, assinale a alternativa que apresenta\nos compostos químicos indicados para manuntenção da hidratação da pele.","options":{"A":"Dexamentazona e vaselina","B":"Ureia e lactato de amônio","C":"Neomicina e hidrocortizona","D":"Cloranfenicol e vaselina","E":"Ácido hialurônico e dexamentazona"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-111306","number":"111306","sourceNumber":"111306","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à transmissão da hanseníase são consideradas formas fechadas:","options":{"A":"Indeterminada e tuberculoide, justificando a não transmissibilidade.","B":"Indeterminada e virchowiana, justificando a não transmissibilidade.","C":"Virchowiana e dimorfa, justificando a transmissibilidade.","D":"Tuberculoide e dimorfa, justificando a não transmissibilidade.","E":"Tuberculoide e indeterminada, justificando a transmissibilidade."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-97745","number":"97745","sourceNumber":"97745","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente com 66 anos de idade, trabalhador rural, vem à consulta devido à lesão de\npele que não cicatriza há várias semanas. Ao exame apresenta lesão de 1,5 cm em pescoço,\nnodular rósea e perolada nos bordos, com sinais de telangectasias, levemente ulcerada no centro,\ncom depressão central, não pruriginosa, sem sinais de infecção, sem sinais de queratose actínica.\nPara a paciente acima, o fator de risco mais importante é","options":{"A":"predisposição genética.","B":"exposição crônica a agrotóxicos.","C":"exposição crônica a radiação ionizante.","D":"exposição solar cumulativa prolongada."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-64442","number":"64442","sourceNumber":"64442","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A dermatite atópica acomete de 10 a 20% das crianças. Pode-se afirmar que:","options":{"A":"O processo agudo não é pruriginoso, apesar do aspecto inflamatório.","B":"As crianças com dermatite atópica são mais propensas a desenvolverem asma ou rinite alérgica.","C":"O processo alérgico não é mediado pela IgE.","D":"O mecanismo fisiopatológico explica a ausência de eosinofilia.","E":"Em lactentes jovens, o processo é desencadeado pelo contato da pele com irritantes (sabonetes\ne até fumaça de cigarros), mas não por\nalimentos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-75516","number":"75516","sourceNumber":"75516","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem com 45 anos de idade procurou a Unidade Básica de Saúde com queixa de\n\n?manchas brancas pelo corpo? que persistem há aproximadamente dois anos e que foram\naumentando em número e tamanho. Ao exame\nverificou-se a presença de quatro lesões, todas\napresentando as mesmas características, sendo duas máculas hipocrômicas na face anterior da\ncoxa direita e duas em região dorsal. As lesões apresentavam bordas bem definidas e ausência de\npelos. O teste de sensibilidade térmica demonstrou anestesia em toda a extensão das lesões e a\navaliação do grau de incapacidade física foi zero. A baciloscopia foi positiva. Em relação ao\ntratamento indicado para este paciente, podemos afirmar que:","options":{"A":"o tratamento deverá ser feito por seis meses, usando-se doses supervisionadas e\nautoadministradas.","B":"a dapsona deverá ser usada na dose de 50 mg/mês supervisionada e 50 mg/dia\nautoadministrada.","C":"a rifampicina deverá ser usada na dose de\n300 mg/mês supervisionada e 100 mg/dia\nautoadministrada.","D":"a clofazimina deverá ser usada na dose de\n300 mg/mês supervisionada e 50 mg/dia\nautoadministrada.","E":"a ofloxacina poderá ser usada em substituição a\nrifampicina nos casos de intolerância, na dose de\n200 mg/mês supervisionada e 200 mg/dia\nautoadministrada."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-137581","number":"137581","sourceNumber":"137581","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O médico de uma Unidade Básica de Saúde (UBS) recebe várias crianças de uma\nmesma escola da região, todas com idade entre\n9 e 10 anos. A queixa é semelhante: houve\nsurgimento, há cerca de 10 dias, de lesões vesico-papulosas associadas a prurido intenso,\nprincipalmente no horário noturno, em região interdigital, punhos, nádegas, axila e periumbilical.\nObserva-se, também, a presença de pústulas friáveis e crostas facilmente removíveis sobre\nalgumas das áreas pruriginosas. Além das medidas gerais de controle, qual o tratamento indicado?","options":{"A":"Nistatina e amoxicilina.","B":"Permetrina e cefalexina.","C":"Ivermectina e cloranfenicol.","D":"Aciclovir e penicilina benzatina","E":"Hexaclorobenzeno e ácido nalidíxico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-137539","number":"137539","sourceNumber":"137539","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem de 48 anos de idade, agricultor , procedente de zona rural, vem à\nconsulta no ambulatório com queixa de\nferida na perna surgida há cinco semanas. Nega\ntraumatismo no local e relata já ter feito curativos com pomadas de vários tipos nesse período, sem\nsucesso. Ao exame físico, encontra-se em bom estado geral, corado e hidratado. Presença de\nlesão ulcerada e única em membro inferior direito, medindo aproximadamente dois centímetros no\nmaior diâmetro, com bordas elevadas e hiperemiadas, fundo granuloso, úmido e com\n\nfibrina, levemente dolorosa ao toque. Com base no quadro acima, qual a principal suspeita\ndiagnóstica e a conduta para o caso?","options":{"A":"Úlcera cutânea traumática; prescrever curativo diário em Unidade Básica de Saúde.","B":"Úlcera varicosa; encaminhar a um especialista cirurgião vascular para tratamento médico.","C":"Infecção por bactéria resistente; colher cultura e\nantibiograma para antibioticoterapia dirigida","D":"Leishmaniose cutânea; realizar pesquisa de parasita através de raspado/curetagem ou de\nbiópsia da lesão.","E":"Hanseníase em sua forma virchowiana; investigar\n\npresença de bacilos álcool-ácido-resistentes por pesquisa direta ou biópsia da lesão."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-137601","number":"137601","sourceNumber":"137601","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma mulher de 37 anos de idade vem à consulta com queixa de febre (temperatura\naxilar = 38°C), náuseas, vômitos, mialgia,\ndor nos braços, pernas e nas articulações dos pés e\nmãos há cerca de dez dias. Refere já ter tido esse quadro há cerca de um mês, tendo obtido\nmelhora com o uso de analgésicos e anti-inflamatórios. Atualmente, refere piora do quadro clínico.\nAo exame físico, evidencia-se que a paciente se encontra em regular estado geral, descorada,\nanictérica, com dificuldade à deambulação ? tem sinais clínicos de polineurite, artralgia e artrite\nde\npequenas e médias articulações. Apresenta nódulos cutâneos de vários tamanhos e estádios\nevolutivos diferentes, róseo-eritemato-edematosos, violáceos, acastanhados, isolados e\nconfluentes, manchas acastanhadas, pústulas, vesículas hemorrágicas e nódulos\n\nnecrótico-ulcerativos, em especial nas coxas e pernas. Apresenta, ainda, cicatrizes de lesões\nanteriores e hepato-esplenomegalia dolorosa. Qual o diagnóstico mais provável nesse caso?","options":{"A":"Farmacodermia.","B":"Lúpus eritematoso sistêmico.","C":"Leishmaniose tegumentar americana.","D":"Eritema nodoso por doença reumática.","E":"Reação por imunocomplexos da hanseníase."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-138603","number":"138603","sourceNumber":"138603","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, com 57 anos de idade, vai à Unidade Básica de Saúde com queixa de\naparecimento, há um mês, de lesão\navermelhada em braço direito. Procurou atendimento médico,\nquando foi prescrita nistastina creme durante 14 dias e fluconazol 150 mg em dose única, sem\nmelhora do quadro. Relata que posteriormente apresentou dor no cotovelo direito, sendo feito\ndiagnóstico de tendinite e prescrito anti-infl amatório. Informa não ter outra doença e não faz uso\nde\nmedicamentos. O exame físico mostra mácula eritematosa com bordas eritematosas elevadas e\ncentro atrófi co. Qual a hipótese diagnóstica e a propedêutica a ser realizada? (VER IMAGEM)","options":{"A":"Psoríase e diagnóstico clínico.","B":"Paracoccidioidomicose e raspado da lesão.","C":"Cromomicose e biópsia.","D":"Hanseníase e Intradermorreação de Mitsuda.","E":"Liquen plano e biópsia."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":["question_bank/media/medcurso/medcurso-dermatologia-der-unico/138603.png"],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-22177","number":"22177","sourceNumber":"22177","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente com 19 anos de idade, trabalhador rural, procurou assistência médica\nambulatorial em virtude de apresentar, há 3 dias, quadro clínico caracterizado por intenso prurido\nem todo o corpo, mais intenso à noite. O exame físico mostrou a presença de vesículas e pápulas\nnas regiões interdigitais, periumbilical, pubiana e no pênis. Considerando a situação hipotética\ndescrita acima, julgue o item seguinte. O período mais provável de transmissão dessa doença\nocorre nos dois dias que antecedem às manifestações clínicas até o segundo dia de\nsintomatologia.","options":{"A":"certo","B":"errado"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-22179","number":"22179","sourceNumber":"22179","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente com 19 anos de idade, trabalhador rural, procurou assistência médica\nambulatorial em virtude de apresentar, há 3 dias, quadro clínico caracterizado por intenso prurido\nem todo o corpo, mais intenso à noite. O exame físico mostrou a presença de vesículas e pálpulas\nnas regiões interdigitais, periumbilical, pubiana e no pênis. Considerando a situação hipotética\ndescrita acima, julgue os itens seguintes. O tratamento dessa doença deve obedecer a dois ciclos\ncom intervalo de uma semana entre eles.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-22198","number":"22198","sourceNumber":"22198","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Nesta questão é apresentado um quadro clínico hipotético, seguido de uma assertiva a\nser julgada. Uma criança de 5 anos de idade apresenta lesão eritematosa com bordas\nsobrelevadas e palidez central, pouco pruriginosas, localizadas principalmente no tronco e na face.\nApresenta também edema na face e nas pálpebras sem sensação de parestesia. Não apresenta\nsinais de comprometimento respiratório. Os sintomas tiveram início há 18 horas e não evoluíram\ncom piora. Nessa situação, as drogas de escolha para o paciente são adrenalina e anti-histamínico\nH1. Caso não haja resposta, devem-se associar corticosteroides.","options":{"A":"certo","B":"errado"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-352157","number":"352157","sourceNumber":"352157","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O Ministério da Saúde adotou a partir de 2021 o esquema de poliquimioterapia único\n(PQT-U) para os casos diagnosticados com hanseníase. Qual a diferença dos esquemas\nterapêuticos entre os casos paucibacilares e multibacilares?","options":{"A":"Os esquemas terapêuticos são iguais, sem nenhuma diferença.","B":"Os esquemas terapêuticos são iguais, diferindo no tempo de tratamento, no qual os casos\npaucibacilares são tratados por 6 meses e os multibacilares por 12 meses.","C":"Os esquemas terapêuticos são iguais, diferindo na dose dos medicamentos, sendo os casos\npaucibacilares com doses mais baixas que os multibacilares.","D":"Os esquemas terapêuticos diferem no tipo de antibióticos entre os casos paucibacilares e\nmultibacilares, embora sejam da mesma classe."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-354109","number":"354109","sourceNumber":"354109","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O quadro clínico do herpes-zóster é, quase sempre, típico. A maioria dos doentes\nrefere, antecedendo às lesões cutâneas, dores\nnevrálgicas, além de parestesias, ardor e prurido\nlocais. Em relação ao quadro clínico do herpes-zóster e a sua descrição, assinale a alternativa\ncorreta:","options":{"A":"O quadro clínico é alomórfico manifestando-se como doença maligna, podendo manifestar-se\ncom outras formas graves, não evolui com êxito\nletal e as regiões mais comprometidas são a face,\no couro cabeludo e a lombossacra.","B":"Não ocorre disseminação hematogênica, o vírus atinge a pele, progride de forma centrípeta\npelos nervos periféricos até os gânglios\nnervosos, onde poderá permanecer, em latência, por toda\na vida.","C":"Infecção viral primária, aguda, altamente contagiosa, caracterizada por surgimento de exantema\nde aspecto maculopapular e distribuição\ncentrípeta, que, após algumas horas, torna-se vesicular,\nevolui rapidamente para pústulas.","D":"Decorre da reativação do vírus da varicela, que permanece em latência. A reativação ocorre na\nidade adulta ou em pessoas com comprometimento imunológico, portadores de doenças crônicas,\nneoplasias, aids e outras.","E":"A erupção é geralmente é bilateral, com frequência ultrapassa a linha mediana e segue o trajeto\nde um nervo. Surge de modo gradual e leva\nde 2 a 4 dias para se estabelecer."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-352160","number":"352160","sourceNumber":"352160","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pré-escolar, de dois anos, há sete dias iniciou prurido no corpo, que piora à noite, e,\nao\nexame físico, apresenta pápulas\neritematosas, vesículas, nódulos, túneis no tronco, palmas e\nplantas, regiões interdigitais, punhos, e na genitália, sendo que outras pessoas em casa\napresentam sintomas semelhantes. O irmão de oito meses apresenta lesões mais intensas nas\naxilas, regiões laterais e mediais dos pés, mas na face e no couro cabeludo também. O diagnóstico\nmais provável e tratamento medicamentoso mais adequado é:","options":{"A":"Impetigo; indicar para a família mupirocina 2% tópica, durante 7 dias.","B":"Estrófulo; indicar para a família hidrocortisona tópica a 1%, durante 7 dias.","C":"Enterovirose não-pólio; indicar para a família sintomáticos até a resolução dos sintomas.","D":"Escabiose; indicar para a família permetrina loção 5%, por 8 a 12 horas e 1 a 2 semanas após."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-351599","number":"351599","sourceNumber":"351599","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considere a situação a seguir: J.M.F, sexo masculino, 32 anos, procura o serviço de\nsaúde com quadro de dor intensa e ardor em\nregião lateral e posterior de tórax a direita. Negava\ntosse, febre, sintomas respiratórios e demais queixas. Ao exame físico, o médico notou vesículas\nsobre uma base eritematosa em faixa, no local da dor, sem demais alterações clínicas. Nesse\ncontexto, é CORRETO afirmar que:","options":{"A":"O exame laboratorial sempre deve ser solicitado ao paciente para confirmação do diagnóstico,\nsendo o mais indicado a imunofluorescência\nindireta (IFI).","B":"O tratamento indicado no caso acima é corticoide tópico para redução das lesões cutâneas e\nanalgesia para o quadro de dor.","C":"As doenças como hanseníase, sífilis primária e leishmaniose cutânea são importantes de se\nconsiderar no diagnóstico diferencial deste paciente.","D":"Uma possível complicação neste quadro pode ser a nevralgia pós-herpética, apesar de ser mais\nfrequente em mulheres."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-352206","number":"352206","sourceNumber":"352206","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Você atua na Estratégia de Saúde da Família e atende um homem de 23 anos que é\ncontato domiciliar de familiar com hanseníase paucibacilar. No momento, você não identifica sinais\nou sintomas sugestivos de hanseníase. Não há contraindicações a qualquer intervenção possível\npara o caso, não está em uso de medicamentos, não há história de ter tomado vacina no último\nano, não há história de hanseníase prévia, não há comorbidades identificadas ou qualquer outro\nelemento específico para o caso que modifique conduta clínica típica. Considerando que você\nidentificou 1 cicatriz de BCG no paciente, qual a conduta a ser tomada em relação à aplicação de\nBCG neste paciente?","options":{"A":"Nenhuma dose.","B":"1 dose.","C":"2 doses.","D":"3 doses."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334715","number":"334715","sourceNumber":"334715","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O Estado do Espirito Santo tem presenciado o aumento do número de casos como a da\npaciente a seguir: Paciente do sexo feminino, 72 anos, branca, iniciou com pápula eritematosa que\nevoluiu para pústula no dedo indicador da mão direita e trajeto eritemato-edematoso no braço\ndireito e sobre essa lesão linear surgiram gomas. Na história clínica a paciente é cuidadora de\ngatos e foi arranhada por um deles durante alimentação dos animais. Qual o diagnóstico mais\nprovável para a paciente e a melhor conduta em termos de saúde pública?","options":{"A":"Covid-19 - vacinação anti-coronavírus.","B":"Sarampo - vacina tríplice.","C":"Esporotricose - abrigo e castração para os gatos e os cachorros.","D":"Doença da arranhadura dos gatos - hábitos higiênicos adequados dos humanos e animais."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334719","number":"334719","sourceNumber":"334719","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o tratamento da psoríase, assinale a alternativa correta.","options":{"A":"O uso de glicocorticóide tópico e emolientes é a primeira linha de tratamento.","B":"O uso de doses elevadas de vitamina D está associado à menor progressão da doença.","C":"A fototerapia está melhor indicada em lesões pequenas, em associação com glicocorticóide.","D":"Ciclosporina ou metrotrexato devem ser iniciados precocemente para redução das lesões\ncutâneas."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-346853","number":"346853","sourceNumber":"346853","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Helena iniciou há seis semanas com lesões ulceradas em antebraço esquerdo. As\nlesões iniciaram com uma pápula que evoluiu para ulceração e com posterior surgimento de uma\nsequência de outros nódulos que também ulceraram. Com esse quadro já foi por duas vezes\natendido e medicado com cefalexina e sulfametoxazol- trimetoprim, sem melhora das lesões. Sua\nmãe relata contato domiciliar com gato que apresentava lesões de pele e que faleceu na última\nsemana. Restante do exame físico sem anormalidades. Nesse caso, é CORRETO afirmar que a\nhistória e as lesões são características de:","options":{"A":"Esporotricose.","B":"Toxoplasmose.","C":"Paracoccidioidomicose.","D":"Doença da arranhadura do gato."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-345741","number":"345741","sourceNumber":"345741","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher de 30 anos com lesão eritematodescamativa em região inguinocrural, sugestiva\nde dermatofitose (tinea cruris). O tratamento\ninicial recomendado é:","options":{"A":"Metronidazol tópico.","B":"Metronidazol via oral.","C":"Miconazol tópico.","D":"Cefalosporina de primeira geração via oral."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-337661","number":"337661","sourceNumber":"337661","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O Brasil é o segundo país com mais casos de hanseníase no mundo, conforme\npesquisa realizada pela Organização Mundial da\nSaúde (OMS) em 2017. Sobre a hanseníase, é\nINCORRETO afirmar que:","options":{"A":"É uma doença crônica, infectocontagiosa, causada pelo bacilo Mycobacterium leprae.","B":"O homem é reconhecido como a única fonte de infecção, embora tenham sido identificados\nanimais naturalmente infectados.","C":"Estima-se que 90% da população tenha defesa natural que confere imunidade contra o M.\nleprae.","D":"O tratamento inicial da hanseníase é hospitalar, dando seguimento em unidades próprias de\ntratamento (atenção secundária)."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-336308","number":"336308","sourceNumber":"336308","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 29 anos com história de gota procura o pronto socorro devido rash difuso,\nlesões eritematosas em pele e úlceras orais\nextensas que impedem a ingestão de líquidos. Relata\nque está em uso de antibiótico para tratamento de infecção do trato urinário, mas não recorda o\nnome. O uso de qual medicação é mais compatível como causador das alterações\n\ncutâneo-mucosas?","options":{"A":"Ciprofloxacina","B":"Sulfametoxazol -Trimetoprina","C":"Macrodantina","D":"Cefalexina"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-336311","number":"336311","sourceNumber":"336311","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 32 anos, comparece ao PS por queixa de cefaléia, sem sinais de alarme.\nForam prescritos dipirona e cetoprofeno\nendovenosos. Trinta minutos após a infusão, evoluiu com\nestridor laríngeo,desconforto respiratório, sibilância e hipotensão. A melhor conduta inicial é:","options":{"A":"Soro fisiológico 0,9% 1000 ml EV agora","B":"Metilprednisolona 60 mg EV","C":"Dopamina EV 5mcg/Kg/min","D":"Adrenalina 0,5 mg IM"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-314026","number":"314026","sourceNumber":"314026","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"De acordo com DUNCAN et al., em relação às dermatites atópicas, analisar os itens\nabaixo: I. O prurido é um sintoma tão proeminente que muitos autores consideram que a presença\nde eczema não pruriginoso não deve ser diagnosticada como um quadro de dermatite atópica. II.\nCaracteriza-se por lesões, sobretudo na face, porém, quando a criança começa a engatinhar, as\nlesões se expandem para as áreas de atrito, como os cotovelos. III. Essas lesões são constituídas\npor pápulas edematosas, às vezes confluentes, muito pruriginosas, crostosas e exsudativas.\n\nEstá(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-314029","number":"314029","sourceNumber":"314029","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à cantoplastia, analisar a sentença abaixo: A opção de realizar a destruição\nda matriz ungueal com fenol deve ser tomada\ncom cautela, por profissionais que tenham\nexperiência no método, pois, embora alguns estudos apontem para uma menor recidiva com o\nemprego desta técnica, existem evidências de que complicações mais graves como necrose e\ninfecção de partes moles estão relacionadas com a aplicação do fenol (1ª parte). No pós-operatório\nimediato, deve-se orientar a utilização de calçados abertos e elevação no membro (2ª parte). O\ncontrole da dor que pode ser feito com analgésicos ou anti-inflamatórios não esteroides, e deve ser\norientada a troca diária dos curativos (3ª parte). A sentença está:","options":{"A":"Totalmente correta.","B":"Correta somente em sua 1ª parte.","C":"Correta somente em sua 2ª parte.","D":"Correta somente em suas 1ª e 2ª partes.","E":"Correta somente em suas 2ª e 3ª partes."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-291962","number":"291962","sourceNumber":"291962","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a Leishmaniose Tegumentar Americana (LTA), assinale a alternativa CORRETA:","options":{"A":"Doença infecciosa, contagiosa, causada por protozoário, de transmissão vertical, que acomete\npele e mucosas.","B":"Os vetores da LTA são insetos denominados flebotomíneos, conhecidos popularmente como\nmosquito palha, tatuquira, birigui.","C":"O período de incubação no homem, é em média de 2 semanas, podendo apresentar períodos\nmais curtos (2 a 3 dias).","D":"A infecção e a doença conferem imunidade ao paciente."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-287839","number":"287839","sourceNumber":"287839","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"De acordo com DUNCAN, et al., a pele é composta por diferentes linhagens de células,\ntodas elas com potencial para formação de tumores benignas. Dessa forma, há tumores de origem\nepitelial de revestimento ou glandular, de origem no tecido conjuntivo, de origem neuronal, entre\noutras. Cistos são formações elevadas ou não, constituídas por uma cavidade fechada, envolta por\num epitélio, e contendo líquido ou substância semissólida no seu interior. Em relação ao exposto,\nnumerar a 2ª coluna de acordo com a 1ª e, após, assinalar a alternativa que apresenta a sequência\nCORRETA: (1) Nevos melanócitos. (2) Pólipos fibroepiteliais. (3) Lipoma. ( ) Tumor benigno que se\norigina de células gordurosas maduras. Pode ocorrer em qualquer tecido adiposo do corpo, sendo\na hipoderme o tecido mais acometido. ( ) Também conhecidos como fibromas moles ou\nacrocórdons, são os tumores de tecido conjuntivo mais comuns na pele, sendo compostos de\ntecido colagenoso frouxo a denso. ( ) São definidos como acúmulos de células provenientes de\nmalformações. São lesões originárias de células provenientes da crista neural. Podem ser divididos\nclinicamente em congênitos, adquiridos e displásicos.","options":{"A":"1 - 2 - 3.","B":"3 - 2 - 1.","C":"2 - 3 - 1.","D":"2 - 1 - 3.","E":"3 - 1 - 2."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-287325","number":"287325","sourceNumber":"287325","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Dr. Sérgio atende Douglas, 55 anos, trabalhador rural, descendente de alemães, que\napresenta lesão em dorso compatível com Queratose Actínica (QA). Observando a lesão o médico\nafirma que a lesão deve ser tratada, só falta escolher o método, retirada por cirurgia ou com uso de\nmedicamento tópico. Por que Dr. Sérgio foi tão firme na conduta? Marque a opção CORRETA:","options":{"A":"Por que QA sempre evolui para carcinoma.","B":"Por conta da faixa etária de Douglas.","C":"Devido ao tipo de trabalho e exposição solar.","D":"Pela inabilidade em predizer quais QA vão persistir, regredir ou evoluir para câncer."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-257365","number":"257365","sourceNumber":"257365","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação as dermatoses mais comuns na infância, assinale a alternativa\nINCORRETA:","options":{"A":"A tinea corporal pode ser tratada inicialmente com antibiótico tópico como miconazol ou\ncetoconazol.","B":"A pitiríase versicolor tem como agente etiológico mais comum Malassezia pachydermatis.","C":"A celulite não necrotizante deve ser tratada com antibiótico oral preferencialmente cefalexina ou\namoxicilina clavulanato.","D":"A psoríase é uma doença crônica da epiderme e de base autoimune."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-287901","number":"287901","sourceNumber":"287901","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Conforme DUNCAN, et al., em relação a doenças de pele em crianças, analisar os itens\nabaixo: I. As afecções mais comuns que contribuem para a dermatite das fraldas são dermatite por\nirritação primária, candidose, dermatite de contato alérgica, dermatite atópica, dermatite\nseborreica,\nimpetigo bolhoso, psoríase e sífilis congênita. II. A candidose nas áreas das fraldas produz lesão\navermelhada de cor viva, com bordas bem demarcadas, confluentes, e com lesões satélites\nadjacentes. Há descamação branca nas bordas. III. A infecção por Staphylococcus aureus\n(impetigo bolhoso), em área de fraldas, é muito frequente, pelo ambiente úmido e quente. As lesões\ncaracterizam-se por máculas eritematosas, que evoluem para vesículas e pústulas, rompendo-se\nfacilmente e formando erosões tipo queimadura. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-255634","number":"255634","sourceNumber":"255634","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Renata, egressa da residência de Medicina de Família e Comunidade, começa a\ntrabalhar em uma Unidade Básica de Saúde\n(UBS) no interior do Espírito Santo e estabelece, após\nreunião com equipe, um turno quinzenal para realização de pequenos procedimentos. Quanto às\netapas para realização de excisões elípticas, MARQUE A CORRETA:","options":{"A":"Para carcinomas basocelulares, utilizam-se margens de 4 a 10 mm.","B":"O eixo maior da elipse deve ser 5 vezes maior que do que o eixo menor.","C":"Para lesões benignas utilizam-se margens de 1 a 2 mm.","D":"Cistos sebáceos não necessitam ter sua base liberada do fundo da lesão."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-246366","number":"246366","sourceNumber":"246366","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança, 8 anos, chega ao PS infantil com relato de febre aferida há 4 dias e surgimento\nde rasch cutâneo com evolução para lesões de\npele, faringite e dor ocular. História pregressa de\nepisódio convulsivo há 1 semana e, desde então, iniciou uso de carbamazepina. Ao exame: lúcido\ne orientado, corado, hipohidratado, TAX: 38,6ºC. FC: 122 bpm, FR: 38 irpm, sem alterações de\nausculta cardiopulmonar. Presença de estomatite erosiva com ulceração de lábios e máculas\npurpúricas em face e tronco com algumas áreas com lesões bolhosas. O provável diagnóstico\ndessa criança é:","options":{"A":"Síndrome da pele escaldada","B":"Doença do soro like","C":"Síndrome de Stevens-Johnson","D":"Lupus eritematoso sistêmico"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-246393","number":"246393","sourceNumber":"246393","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com base nas diretrizes para vigilância, atenção e eliminação da hanseníase como\nproblema de saúde pública no Brasil\n(Ministério da Saúde, 2016), julgue as afirmativas abaixo: I -\nPacientes com menos de cinco lesões de pele são classificados como paucibacilares e com cinco\nou mais lesões como multibacilares. II - Casos com mais de um nervo comprometido devem ser\ntratados como multibacilares, independente do resultado da baciloscopia e da situação de\nenvolvimento cutâneo. III - O controle da doença é considerado bom quando a proporção de casos\nnovos de hanseníase com grau de incapacidade física avaliado no diagnóstico é igual ou maior que\n90%. IV - Contatos familiares recentes ou antigos de pacientes com as formas multibacilar e\npaucibacilar devem ser examinados, independente do tempo de convívio com o caso. Está correto\no que se afirma em:","options":{"A":"I e IV, apenas.","B":"II, III e IV, apenas.","C":"II e III, apenas.","D":"I, II, III e IV."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-227307","number":"227307","sourceNumber":"227307","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A família Herpesviridae, subfamília Alfa-herpesvírus, é composta por vírus citolíticos e\nneurotrópicos, de crescimento rápido e que tendem a permanecer em latência nos gânglios\nsensitivos durante toda a vida. Em relação aos herpes vírus é correto afirmar:","options":{"A":"Quatro tipos de herpes vírus infectam seres humanos: o vírus Herpes simplex, o Vírus da\nvaricela, o Vírus do herpes zoster e o\nvírus da Roséola do lactente (Herpes-vírus humano tipo 3).","B":"O vírus Epstein-Barr e o Citomegalovírus são herpes vírus.","C":"O Vírus da varicela e o Vírus do herpes zoster são dois herpes vírus que infectam seres\nhumanos.","D":"O vírus Herpes simplex (VHS) causa quadros recorrentes de lesão de pele na face e na região\ngenital. As encefalites herpéticas são por outros tipos de herpes vírus."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-243055","number":"243055","sourceNumber":"243055","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao melanoma cutâneo assinale dentre as alternativas abaixo o subtipo\nhistológico mais frequente:","options":{"A":"melanoma nodular.","B":"lentigo maligno.","C":"melanoma extensivo superficial.","D":"melanoma amelanotico.","E":"melanoma acral."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-202736","number":"202736","sourceNumber":"202736","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O tratamento de escolha para escabiose em um pré-escolar, dois anos, previamente\nsaudável é:","options":{"A":"Lidane creme a 1% por 8 ? 12 horas.","B":"Ivermectina 600 ?g/kg em dose única.","C":"Albendazol 400 mg em dose única.","D":"Amoxacilina 50 mg/kg/dia por 7 dias.","E":"Permetrina creme a 5% por 8 ? 12 horas."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-212938","number":"212938","sourceNumber":"212938","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre os hemangioma da infância, é correto afirmar, exceto:","options":{"A":"São os tumores vasculares benignos mais comuns na faixa etária pediátrica, com maior\nincidência em bebês prematuros do que em recém-nascidos a termo.","B":"Podem ser classificados como superficiais, profundos ou mistos, sendo que os hemangiomas\nmistos são os mais prevalentes.","C":"O marcador imunohistoquímico GLUT-1 diferencia hemangioma de outros tumores vasculares\ndos lactentes.","D":"Os hemangiomas em geral passam por uma fase de expansão rápida, seguida por um período\nestacionário e, posteriormente, por involução espontânea.","E":"O tratamento consiste na ressecção cirúrgica do hemangioma, e só é necessário quando\nocorrem complicações, como ulceração, infecção\nsecundária ou hemorragia."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-199627","number":"199627","sourceNumber":"199627","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Doenças infecciosas são doenças causadas por microorganismos como vírus,\nbactérias, protozoários ou fungos. Associe a\nprimeira coluna com a segunda e assinale a alternativa\nCORRETA. 1 - Leptospirose; 2 - Febre amarela; 3 - Leishmaniose; 4 - Malária. ( ) Doença\ninfecciosa aguda e grave, causada por arbovírus. A maioria dos casos é assintomática, mas nos\ncasos mais graves a letalidade é de aproximadamente 50%. ( ) É uma doença infecciosa\ntransmitida por mosquitos, causada por protozoários. A febre está presente na maioria dos\npacientes, costuma ser elevada e pode vir acompanhada de cefaleia e calafrio. Anorexia e artralgia\ntambém podem ocorrer. ( ) A doença é causada por protozoário, os vetores são insetos\nflebotomíneos, mais frequente em menores de 10 anos (58%) e a suspeita clínica deve ser\nlevantada nos pacientes com febre e esplenomegalia associadas ou não à hepatomegalia. ( )\nTransmitida ao homem por meio da água contaminada com urina de roedores e animais\ndomésticos ou silvestres portadores da bactéria.","options":{"A":"2 - 3 - 4 - 1.","B":"3 - 1 - 2 - 4.","C":"2 - 4 - 3 - 1.","D":"3 - 1 - 4 - 2."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-196821","number":"196821","sourceNumber":"196821","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 70 anos com história de prurido intenso há 3 semanas, evoluiu com quadro\ngeneralizado de lesões eritematosas, edematosas urticariformes seguidas pela formação de bolhas\ngrandes e tensas localizadas na superfície flexural dos membros e porção inferior do abdome.\n\nRelata ter apresentado vesículas orais que regrediram rapidamente. Baseado no quadro descrito,\nqual o diagnóstico mais provável:","options":{"A":"Penfigóide Bolhoso.","B":"Pênfigo Foliáceo.","C":"Penfigóide Cicatricial.","D":"Dermatite Herpetiforme."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-196825","number":"196825","sourceNumber":"196825","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Das assertivas abaixo, marque a falsa:","options":{"A":"os nevos congênitos podem ser precursores de melanomas.","B":"os nevos atípicos podem ser precursores e marcadores de risco de melanoma.","C":"em cerca de 70% dos casos é relatada a existência prévia de nevo pigmentar.","D":"o melanoma extensivo superficial é o que mais freqüentemente se associa com lesões névicas\nprecursoras."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-196826","number":"196826","sourceNumber":"196826","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"De acordo com o caso clínico abaixo, marque a alternativa que melhor define o quadro\napresentado: Paciente do sexo feminino, 30 anos, natural de Cariacica ?ES, compareceu ao\nambulatório de dermatologia apresentando numerosas lesões tipo placa eritematosas, infiltradas,\ncom contornos internos bem definidos e externos mal definidos, centro com coloração de pele\nnormal. Apresentava infiltração dos pavilhões auriculares. Relatou surgimento do quadro há alguns\nmeses, porém o aparecimento súbito de nódulos eritematosos dolorosos acompanhados de\nsintomas gerais tipo febre e astenia a levaram a procurar atendimento. Teste de sensibilidade das\nlesões mostrava hipoestesia.","options":{"A":"Trata-se de uma paciente com hanseníase dimorfa com eritema nodoso e deve ser instituída\npoliquimioterapia com seis doses.","B":"Trata-se de uma paciente com hanseníase dimorfa em reação tipo II e deve ser instituída\npoliquimioterapia multibacilar + talidomida.","C":"Trata-se de uma paciente com hanseníase virchowiana em reação reversa e deve ser instituída\npoliquimioterapia multibacilar + corticoterapia.","D":"Trata-se de uma paciente com hanseníase dimorfa com eritema nodoso e deve ser instituída\npoliquimioterapia multibacilar + corticoterapia."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172777","number":"172777","sourceNumber":"172777","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a leishmaniose tegumentar americana, assinale a alternativa correta.","options":{"A":"Um dos principais diagnósticos diferenciais é a esporotricose.","B":"O diagnóstico laboratorial em área endêmica é confirmado pela intradermoreação de\nMontenegro.","C":"A taxa de resposta aos antimoniais pentavelentes é baixa.","D":"O critério de cura é a ausência de lesão cutânea após 30 dias do término do tratamento."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172828","number":"172828","sourceNumber":"172828","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o manejo da anafilaxia, assinale a alternativa correta.","options":{"A":"Antagonista histamínico H2 é mais eficaz que o antagonista H1 no controle das manifestações\ncutâneas.","B":"Em pacientes com broncoespasmo o uso de agonistas beta adrenérgicos não é eficaz.","C":"Adrenalina por via endovenosa é a primeira medicação que deve ser usada.","D":"O uso de glicocorticóide não interfere no desfecho da sua fase aguda."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172765","number":"172765","sourceNumber":"172765","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente de 27 anos , previamente hígida, deu entrada no Pronto Socorro com história\nde dor, seguida de aparecimento de lesões\nvesiculosas em região anterior do tórax. Após avaliação\nclínica, recebeu diagnóstico de infecção por varicela-zoster. Sobre a infecção por varicela-zoster é\ncorreto afirmar:","options":{"A":"No curso de investigação, é mandatória a solicitação de glicemia. além das sorologias para HIV,\nhepatite C e herpes zoster.","B":"Deve-se iniciar tratamento com aciclovir oral (400 mg 5 vezes ao dia), para encurtar o tempo de\ntratamento e diminuir o risco de neuralgia pós-herpética.","C":"Caso a paciente fosse imunossuprimida, o risco de neuralgia pós herpética seria aumentado.","D":"Nos casos de herpes zoster, as indicações para uso de aciclovir injetável se resumem aos casos\nde pneumonia ou encefalite pelo vírus varicela\nzoster."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-187447","number":"187447","sourceNumber":"187447","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à escabiose, é correto afirmar que:","options":{"A":"O Sarcoptes scabiei é capaz de sobreviver no meio ambiente por cerca de 7 dias.","B":"A persistência do prurido por uma semana após o tratamento é sinal de falha terapêutica.","C":"A ivermectina não tem ação ovicida, apenas acaricida.","D":"O benzoato de benzila é contra-indicado em menores de 6 meses.","E":"Os ovos do Sarcoptes eclodem em 10 dias, daí a necessidade de repetir o tratamento."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-172555","number":"172555","sourceNumber":"172555","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 11 meses iniciou há menos de 24 h tosse seca, sibilos difusos, tempo\nexpiratório aumentado e retração subcostal leve.\nSat O2, em ar ambiente de 96%. Nega febre. Pais\nreferem quadro de tosse seca há uma semana, com melhora espontânea; diagnostico de dermatite\natópica desde 7 meses de vida. Sobre o caso:","options":{"A":"A Dermatite Atópica aumenta o risco de um lactente sibilante apresentar asma;","B":"Devido a idade, é imprescindível a historia familiar de asma em ambos ou em um dos pais, para\nhipótese diagnostica de asma;","C":"A ausência de febre exclui totalmente a hipótese diagnostica de infecção, como por exemplo\nBronquiolite aguda, sugerindo o diagnostico de asma;","D":"Por se tratar de lactente, a única hipótese diagnostica seria Bronquiolite aguda indicando\ninternação imediata para tratamento de suporte (oxigenioterapia)."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-148561","number":"148561","sourceNumber":"148561","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"São medicamentos eficazes no tratamento da dor neuropatia pós-herpética, exceto:","options":{"A":"Pre-gabalina.","B":"Amitriptilina.","C":"Gabapentina.","D":"Imipramina.","E":"Sertralina."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-155460","number":"155460","sourceNumber":"155460","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de três meses de idade apresenta lesão angiomatosa que acomete toda a\nextensão da pálpebra superior direita. A lesão que era plana quando surgiu no primeiro mês de\nvida, mostra-se atualmente elevada e volumosa, interferindo nos movimentos de abrir e fechar os\nolhos. O diagnóstico clínico firmado é de hemangioma. A conduta mais adequada para este caso é:","options":{"A":"Expectante.","B":"Corticoterapia oral.","C":"Embolização.","D":"Exérese cirúrgica.","E":"Radioterapia superficial."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-155479","number":"155479","sourceNumber":"155479","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Escolar de oito anos, do sexo masculino, apresenta perda localizada de cabelos há dois\nmeses. Ao exame notam-se duas áreas circulares de perda quase completa de pêlos, uma na\nregião frontal e outra na região ociptal. A pele no centro das placas é normal, com pêlos facilmente\ndestacáveis na periferia. Algumas unhas apresentam depressões rasas. A hipótese diagnóstica é:","options":{"A":"Tricotilomania.","B":"Eflúvio telógeno.","C":"Alopecia areata.","D":"Alopecia de tração.","E":"Tinha do couro cabeludo."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-148624","number":"148624","sourceNumber":"148624","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"João, 55 anos, é diagnosticado com Hanseníase durante acompanhamento em\nUnidade de Saúde da Família. Em seu\nhistórico familiar, relata residir com sua esposa Maria de 50\nanos, com quem é casado há 25 anos; com sua filha Mônica de 18 anos, com quem sempre morou;\ne os dois filhos de Mônica: Marcos, de 3 anos e Felipe, de 2 anos. O segundo filho de João,\nAlfredo, de 24 anos, saiu da casa de João há 3 anos, residindo sozinho no mesmo território. Como\ndeve ser feita a investigação epidemiológica e a vacinação com BCG nestes contatos de João?","options":{"A":"Realizar exame dermatoneurológico em todos os contatos intradomiciliares e em Alfredo, aplicar\nBCG em Maria, Mônica, Marcos, Felipe e Alfredo caso não apresentem sinais e sintomas de\nHanseníase e não possuam duas cicatrizes da vacina.","B":"Realizar exame dermatoneurológico e baciloscopia em todos os contatos intradomiciliares e em\nAlfredo; aplicar BCG em Maria, Mônica, Marcos, Felipe e Alfredo caso não apresentem sinais e\nsintomas de Hanseníase e não possuam duas cicatrizes da vacina.","C":"Realizar exame dermatoneurológico em todos os contatos intradomiciliares e em Alfredo; aplicar\nBCG em Maria, Mônica, Marcos e Felipe caso não apresentem sinais e sintomas de Hanseníase e\nnão possuam duas cicatrizes da vacina.","D":"Realizar exame dermatoneurológico e baciloscospia em todos os contatos intradomiciliares e em\nAlfredo, aplicar BCG em Maria, Mônica, Marcos e Felipe caso não apresentem sinais e sintomas de\nHanseníase e não possuam duas cicatrizes da vacina.","E":"Realizar exame dermatoneurológico, baciloscopia e Raio-X de tórax em todos os contatos\nintradomiciliares e observar, sem necessidade de aplicar BCG nos contatos no momento."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-149119","number":"149119","sourceNumber":"149119","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à dermatite atópica, qual é a assertiva mais correta?","options":{"A":"Apesar de frequente, é em geral bem tolerada, não causando impacto na qualidade de vida dos\npacientes.","B":"A melhora da dermatose ocorre logo no primeiro ano de vida.","C":"A dermatose dificilmente progride com o desnvolvimento de rinite e asma nos\npacientes.","D":"Ocorre alteração do metabolismo dos lipídeos com comprometimento da barreira cutânea.","E":"O envolvimento psicossomático não interfere na fisiopatologia da dermatite atópica."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-149125","number":"149125","sourceNumber":"149125","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Ao examinar um lactente de um ano, observam-se adenomegalias occipitais. O pediatra\ntranquiliza a mãe e fala que o comprometimento destes linfonodos está associado a:","options":{"A":"faringite aguda","B":"erupção dentária","C":"cistos branquiais","D":"dermatite seborreica","E":"processo inflamatório da parótida"},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-162527","number":"162527","sourceNumber":"162527","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de 10 meses é levado ao pediatra por apresentar desde o quinto mês de vida\nlesões eritematopapulosas, que evoluem com descamação brilhante, acometendo as regiões\nmalares, retroauriculares, cervical e superfícies extensoras dos membros superiores e inferiores,\nextremamente pruriginosas. A hipótese diagnóstica mais provável é:","options":{"A":"Ictiose alba.","B":"Dermatite de contato.","C":"Dermatite atópica.","D":"dermatite seborreica.","E":"Escabiose."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-162539","number":"162539","sourceNumber":"162539","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 10 anos de idade chega pela primeira vez ao consultório de um pediatra\ncom placas esbranquiçadas orais e bolhas\ncutâneas, e diz que ambas são recorrentes. A paciente\nestava bem até os dois anos de idade, quando iniciaram as lesões na boca. Em seguida notou\nvesículas e bolhas em dorso de mãos e planta dos pés, além de joelhos. As lesões esbranquiçadas\nde mucosa se tornaram ulceradas e dolorosas. As lesões duram de uma a duas semanas e\ncicatrizam com atrofia local e reabsorção óssea distal. Com base nesses dados iniciais da história,\nqual o diagnóstico mais provável?","options":{"A":"Epidermólise bolhosa.","B":"Pênfigo paraneoplásico.","C":"Eritema multiforme.","D":"Doença mão-pé-boca.","E":"Dermatite de contato ao látex."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-131612","number":"131612","sourceNumber":"131612","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente se apresenta com um melanoma comprovado por biópsia da coxa, que é\nde 3mm de espessura no exame histopatológico.\nNo momento da excisão qual deve ser a largura\ndas margens?","options":{"A":"1 cm","B":"2 cm","C":"3cm","D":"4cm","E":"5cm"},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-126922","number":"126922","sourceNumber":"126922","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lactente de dois meses de idade, iniciou com lesões em couro cabeludo desde a\nsegunda semana de vida, que pioraram\nprogressivamente e se estenderam a outras áreas. Não há\nrelato de casos semelhantes na família. Ao exame físico, se destacam as escamas de cor\namarelada aderidas e gordurosas envolvendo todo o couro cabeludo, visíveis também em\nsobrancelhas, regiões retroauriculares e tronco. A mãe não relata prurido. Em relação ao\ndiagnóstico MAIS provável, para o quadro dermatológico desta criança, assinale a alternativa\nCORRETA.","options":{"A":"Dermatite atópica, por não apresentar prurido e não ter relato familiar.","B":"Dermatite seborreica, devido à localização das lesões.","C":"Dermatite de contato, devido à presença de escamas aderidas.","D":"Miliária, devido à idade do aparecimento."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-127233","number":"127233","sourceNumber":"127233","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A hanseníase (lepra) é uma doença crônica que resulta da infecção por Mycobacterium\nleprae e da resposta suscita no hospedeiro. Em\nrelação a hanseníase é CORRETO afirmar:","options":{"A":"O período de incubação da hanseníase em seres humanos varia de 7 a 15 dias.","B":"O período de incubação da hanseníase em seres humanos varia de 3 meses a 20 anos.","C":"A hanseníase ocorre em todas as idades, mas é mais frequente em lactentes devido a\nimunidade deficiente.","D":"A infecção por HIV aumenta em 30 vezes o risco da hanseníase em áreas de alta prevalência\ndos dois patógenos.","E":"O paciente sempre deve ser isolado pois não existe tratamento até o momento para hanseníase."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-106433","number":"106433","sourceNumber":"106433","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na fisiopatologia do Pênfigo Foliáceo, estão presentes anticorpos IgG dirigidos contra a\nseguinte estrutura:","options":{"A":"desmogleína 3","B":"BP180 do hemidesmossoma","C":"desmogleína 1 do desmossoma","D":"colágeno tipo VII das fibrilas de ancoragem","E":"nenhuma das alternativas anteriores"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-106438","number":"106438","sourceNumber":"106438","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação à Hanseníase, todas as alternativas abaixo estão corretas, exceto:","options":{"A":"O Mycobacterium leprae é um parasita intracelular obrigatório.","B":"O Mycobacterium leprae tem alta patogenicidade.","C":"O Mycobacterium leprae tem alta infectividade.","D":"O Mycobacterium leprae tem baixa virulência.","E":"O Mycobacterium tem longo período de incubação, em média 2 a 7 anos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-106422","number":"106422","sourceNumber":"106422","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lucas, 2 anos de idade, foi levado para consulta no ambulatório de pediatria por\napresentar lesões de pele eritemato-descamativas\ne exsudativas, localizadas nas regiões malares,\npálpebras, pescoço, região anterior do tórax, dobras antecubitais e poplíteas. Qual alternativa\nabaixo apresenta o diagnóstico mais provável?","options":{"A":"Dermatite seborreica com infeccção secundária por Streptococcus.","B":"Dermatite seborreica com contaminação por Cândida albicans.","C":"Psoríase invertida.","D":"Dermatite atópica com infecção cutânea secundária por Staphylococcus aureus.","E":"Esporotricose cutânea."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-111615","number":"111615","sourceNumber":"111615","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na dermatite seborreica do lactente, as glândulas sebáceas são estimuladas por\nandrógenos\n\nmaternos. Além da remoção cuidadosa de crostas com óleos vegetais, pode ser utilizado:","options":{"A":"xampu contendo deltametrina.","B":"creme de óxido de zinco com óleo de amêndoas.","C":"creme contendo muporicina.","D":"xampu contendo cetoconazol 2%.","E":"xampu contendo metronidazol 1%."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-77522","number":"77522","sourceNumber":"77522","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Como se caracteriza clinicamente a urticária?","options":{"A":"Lesões eritematosas, vesiculosas, exsudativas e crostosas, nas grandes dobras cutâneas.","B":"Lesões em placas eritematosas, de borda interna bem delimitada e borda externa de limite não\nnítido, pruriginosas e persistentes.","C":"Placas eritematosas, de bordas papulosas e centro bolhoso.","D":"Pápulas e placas eritematosas e edematosas, pruriginosas, de aparecimento súbito, duração\nefêmera.","E":"Mancha arredondada, eritematosa, de limites externos nítidos, que evolui para mancha\nacastanhada, recidivante, no mesmo local."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-87461","number":"87461","sourceNumber":"87461","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Menina, oito anos de idade, relata ao pediatra que há duas semanas \"apareceu uma\nmancha\" na região do tronco. Ao exame\nfísico, visualiza-se uma lesão eritematosa, bem delimitada,\ncom escamas secas, aderentes e prateadas de aproximadamente 3 cm de diâmetro. O diagnóstico\né:","options":{"A":"Estrófulo.","B":"Ímpetigo bolhoso.","C":"Psoriase.","D":"Eczema seborreico.","E":"Tinea corporis."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-77590","number":"77590","sourceNumber":"77590","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adriano, 12 anos, vem apresentando no último ano edema de mãos e pés, cada vez\npior. Geralmente após eventos estressantes ou\napós exercícios. O último episódio foi\nacompanhado de dor abdominal, diarreia e vômitos. Os exames laboratoriais básicos foram\nnormais. Quadro semelhante já ocorreu com a tia materna. O quadro do adolescente é compatível\ncom:","options":{"A":"Síndrome nefrótica.","B":"Angioedema hereditário.","C":"Glomeruloesclerose focal.","D":"Lupus eritematoso sistêmico.","E":"Púrpura de Henoch-Schonlein atípica."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-43929","number":"43929","sourceNumber":"43929","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A hanseníase é doença infecciosa crônica, que atinge a pele e os nervos periféricos.\nQuais são as suas características epidemiológicas\nno Brasil?","options":{"A":"Apresenta alta letalidade e alta mortalidade.","B":"Observa-se relação entre endemicidade e baixos índices de desenvolvimento humano.","C":"A taxa de prevalência da doença continua alta em todas as regiões brasileiras.","D":"Compromete mais frequentemente a faixa etária abaixo dos 15 anos.","E":"A descoberta do caso é limitada à demanda espontânea do paciente."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-43936","number":"43936","sourceNumber":"43936","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual a assertativa errada em relação ao herpes zoster?","options":{"A":"É uma doença viral autolimitada.","B":"Antes do surgimento das lesões cutâneas os pacientes referem parestesias, ardor e prurido no\nlocal onde surgirá o quadro cutâneo.","C":"O seu aparecimento pode indicar baixa da resposta imunológica.","D":"O herpes zoster é decorrente da reativação do vírus Epstein-Barr em latência, em adultos e\npacientes imunocomprometidos.","E":"A neuralgia pós-herpética melhora gradativamente, mas nos idosos pode permanecer por meses\nou anos após o final do quadro cutâneo."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-32446","number":"32446","sourceNumber":"32446","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O prurido generalizado pode ser uma manifestação cutânea de doenças generalizadas.\nEm que caso esta afirmação é incorreta:","options":{"A":"Doença de Hodgkin.","B":"Doenças cardiopulmonares.","C":"Linfomas malignos outros, além da doença de Hodgkin.","D":"Uremia.","E":"Doenças hepatobiliares."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27413","number":"27413","sourceNumber":"27413","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"De acordo com o caso clínico abaixo, marque a alternativa que melhor define o quadro\napresentado: Paciente do sexo masculino, 36 anos, natural de Cariacica-ES, compareceu ao\nambulatório de dermatologia apresentando numerosas lesões tipo placa eritematosas,\n\nalgumas eritemato-violáceas, infiltradas, com contornos internos bem definidos e externos mal\ndefinidos, centro com coloração de pele normal.\nApresentava infiltração dos pavilhões auriculares.\nRelatou surgimento do quadro há alguns meses, porém o aparecimento súbito de nódulos\neritematosos dolorosos acompanhados de sintomas gerais tipo febre e astenia o levaram a procurar\natendimento. Apresentava teste de sensibilidade térmica alterado com hipoestesia.","options":{"A":"o caso trata-se de um paciente com hanseníase dimorfa e deve ser instituída poliquimioterapia\nmultibacilar com doze doses.","B":"o caso trata-se de um paciente com hanseníase dimorfa em reação tipo II e deve ser instituída\npoliquimioterapia paucibacilar + corticoterapia.","C":"o caso trata-se de um paciente com hanseníase virchowiana em reação reversa e deve ser\ninstituída poliquimioterapia multibacilar + corticoterapia.","D":"o caso trata-se de um paciente com hanseníase dimorfa com eritema nodoso e deve ser\ninstituída poliquimioterapia multibacilar + talidomida.","E":"o caso trata-se de um paciente com hanseníase virchowiana em reação tipo II e deve ser\ninstituída poliquimioterapia paucibacilar + talidomida."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27414","number":"27414","sourceNumber":"27414","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"De acordo com as dermatoses causadas por vírus, marque a alternativa incorreta:","options":{"A":"A erupção variceliforme de Kaposi é um quadro de disseminação viral causado pelo vírus\nherpético ou da vacínia em algumas doenças cutâneas.","B":"A localização mais frequente do herpes recidivante é nos lábios.","C":"É possível uma criança adquirir varicela por contato com doente com herpes zoster.","D":"Uma característica importante da varicela é a evolução por surtos com o encontro das lesões em\nvários estádios evolutivos.","E":"A neuralgia pós herpética é uma complicação rara do herpes zoster."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27337","number":"27337","sourceNumber":"27337","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, compareceu ao ambulatório de dermatologia\ncom queixa de dor e calor na perna direita. Ao\nexame dermatológico, apresentava\ncomprometimento de extensa área no membro inferior direito que se encontrava edemaciado,\neritematoso e quente. Além disso, apresentava tinha interdigital entre o terceiro e quarto\npododáctilo e linfadenomegalia inguinal à direita. O quadro cutâneo estava associado a sintomas\ngerais de febre (39°C) e calafrios.De acordo com o caso clínico descrito, marque a alternativa\nincorreta:","options":{"A":"A erisipela é geralmente causada pelo estreptococo beta-hemolítico do grupo A.","B":"O caso descrito pode evoluir com bolhas associadas, sendo denominada erisipela bolhosa.","C":"O paciente acima não apresentava fator de risco para o desenvolvimento dessa dermatose\ncausada por bactéria.","D":"O linfedema ou mesmo a elefantíase podem ocorrer como conseqüência dos surtos recidivantes.","E":"A droga de escolha para o tratamento é a penicilina."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-27377","number":"27377","sourceNumber":"27377","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação à cicatrização está correto:","options":{"A":"A suplementação de vitamina C é benéfica para doentes com e sem deficiência dessa vitamina","B":"Suplementação de vitamina A reverte os efeitos deletérios do uso de corticosteroides","C":"A infiltração de anestésicos locais aumenta a força tênsil e estimula a síntese do colágeno","D":"Na senilidade apenas a fase inflamatória está comprometida","E":"A radioterapia estimula a cicatrização das feridas"},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-23159","number":"23159","sourceNumber":"23159","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 05 anos é atendida com história de prurido nas mãos, acompanhado de\n\n??bolinhas?? que se rompem e algumas às vezes infectam. Já usou diversos medicamentos\ntópicos. Há períodos de melhora, entremeados\ncom recidiva. Ao exame local: lesões vesículosas\nem palmas das mãos e plantas dos pés, isoladas ou agrupadas, algumas com conteúdo claro,\noutras de coloração turva. Lesões descamativas também nos mesmos locais. Qual o diagnóstico\nprovável?","options":{"A":"Escabiose.","B":"Eczema de contato.","C":"Coxsakiose.","D":"Desidrose.","E":"Impetigo."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-9383","number":"9383","sourceNumber":"9383","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual das afirmações abaixo está ERRADA em relação à hanseníase?","options":{"A":"Apresenta longo período de incubação.","B":"O Mycobacterium leprae é cultivado em meios especiais de culturas laboratoriais.","C":"O bacilo é parasita intracelular obrigatório, residindo nos macrófagos.","D":"O bacilo cresce seletivamente nas porções mais frias do corpo.","E":"A determinação da viabilidade bacilar e a resistência aos agentes quimioterápicos dependem do\ncrescimento bacilar nas patas dos camundongos."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8070","number":"8070","sourceNumber":"8070","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nQual o diagnóstico etiológico da síndrome febril?","options":{"A":"Virose.","B":"Insuficiência venosa crônica.","C":"Trombose venosa profunda.","D":"Erisipela verdadeira.","E":"Eritema nodoso."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8071","number":"8071","sourceNumber":"8071","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nNo caso clínico anterior, que fator pode ser considerado determinante para o aparecimento do\nquadro clínico febril?","options":{"A":"Obesidade.","B":"Pernas que incham cronicamente.","C":"Hipertensão arterial.","D":"Problema linfático.","E":"Nenhum item acima."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8072","number":"8072","sourceNumber":"8072","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nNo caso clínico anterior, o melhor tratamento para a condição diagnosticada é:","options":{"A":"Anorexígenos, caminhadas e abstenção do álcool.","B":"Acrescentar diuréticos à medicação anti-hipertensiva.","C":"Prescrever linfagogos e linfocinéticos.","D":"Penicilina benzatina ou cristalina sob internação.","E":"Nenhum item acima."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8156","number":"8156","sourceNumber":"8156","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Escolar de 8 anos de idade, sexo masculino, é atendido devido à lesão de pele,\nprincipalmente em áreas de cotovelos, joelhos e couro cabeludo, de caráter recorrente. Ao exame\nda pele observa-se lesões simétricas em áreas de extensão dos membros e couro cabeludo de\ncontornos nítidos, base eritematosa, recobertas por descamação seca branco-prateada. Diante\ndestes dados, qual o provável diagnóstico?","options":{"A":"Eczema atópico.","B":"Dermatite seborreica.","C":"Psoríase.","D":"Estrófulo.","E":"Eczema de contato."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8111","number":"8111","sourceNumber":"8111","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente apresentando lesão localizada em uma das coxas, que se caracteriza por ter\neritema, edema, calor local, dor, ser limitada, com febre inferior a 38ºC, traduz:","options":{"A":"Erisipela.","B":"Impetigo.","C":"Foliculite.","D":"Celulite.","E":"Ectima."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-8112","number":"8112","sourceNumber":"8112","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Lesão eritemato-vesico-crostosa, de aspecto circinado, pruriginosa traduz:","options":{"A":"eczema Numular.","B":"hanseníase tuberculoide","C":"desehidrose.","D":"dermatofitose.","E":"candidíase."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-353847","number":"353847","sourceNumber":"353847","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As leishmanioses são enfermidades causadas por várias espécies de protozoários\ndigenéticos do gênero Leishmania, que acometem\no homem e diferentes espécies de animais\nsilvestres e domésticos. Amplamente distribuída em todo o mundo, a leishmaniose tegumentar\ntambém é encontrada no continente americano, onde é chamada de Leishmaniose Tegumentar\nAmericana (LTA). No Brasil, as regiões Norte e Nordeste são onde se concentra o maior número de\ncasos dessa doença. A respeito dessa doença, é CORRETO afirmar:","options":{"A":"O diagnóstico diferencial das formas cutâneas engloba: esporotricose, úlceras traumáticas,\núlceras de estase, cromomicose e\nparacoccidioidomicose.","B":"A forma mucosa apresenta comumente uma lesão no septo nasal, iniciando como granuloma e\nevoluindo lentamente para a perfuração do septo, tendendo à cicatrização espontânea.","C":"A forma cutânea disseminada apresenta-se por extensas lesões ulceradas, acometendo\nprincipalmente palma das mãos e sola dos pés.","D":"A reação intradérmica de Montenegro traduz a resposta alérgica de hipersensibilidade retardada\nao Leishmania braziliensis e, se positivo,\nconfirma o diagnóstico de LTA."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-355606","number":"355606","sourceNumber":"355606","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma menina de quatro anos de idade foi levada ao pronto-socorro com queixa de febre\nalta e lesões de pele há três dias. Fez uso de sulfameto-xazol/trimetoprima para infecção do trato\nurinário por sete dias, tendo parado há cinco dias. O exame físico mostrou edema bipalpebral, com\nhiperemia conjuntival e secreção ocular amarelada. A boca também foi acometida com enantema\nde mucosa e crostas em lábios. Apresentava lesões maculoeritematosas na face, no tronco e na\nregião proximal dos membros. Durante a hospitalização, as lesões evoluíram para bolhas e\ndescolamento cutâneo e surgiram erosões urogenitais. Em relação a esse caso hipotético, assinale\na alternativa correta:","options":{"A":"Trata-se de Síndrome da Pele Escaldada.","B":"Se o descolamento da pele for maior que 20% do corpo, o quadro é chamado de necrólise\nepidérmica tóxica (NET).","C":"Há indicação de corticosteroide.","D":"A gamaglobulina em altas doses aumenta a taxa de sobrevivência.","E":"A ciclosporina tem sido usada nesses casos com bons resultados."},"answer":"E","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-354765","number":"354765","sourceNumber":"354765","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A hanseníase é uma doença infectocontagiosa, de evolução lenta e o seu agente\netiológico é o Mycobacterium leprae. Seguida\ndas manifestações cutâneas e dos nervos periféricos,\na artrite é a terceira manifestação mais comum desta doença. Neste contexto, sabe-se que:","options":{"A":"as manifestações articulares inflamatórias ocorrem mais frequentemente durante as reações\nhansênicas, são crônicas e deixam sequelas com deformidade articular.","B":"na reação hansênica tipo 2 ou eritema nodoso hansênico, a artrite é predominantemente\nmonoarticular, acometendo principalmente joelhos,\nforma semelhante à espondiloartrite.","C":"os casos mais graves pode ocorrer máculas eritematosas, lesões vesicobolhosas, lesões\nulceradas e necróticas, acompanhadas de\nsintomas sistêmicos com diagnostico diferencial com\nvasculite.","D":"a artrite erosiva não é observada na artrite hansênica, a presença de tal achado exclui a artrite\npor hanseníase."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334764","number":"334764","sourceNumber":"334764","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Qual o critério para o paciente com hanseníase receber alta por cura?","options":{"A":"Desaparecimento das lesões de pele.","B":"Negativação da baciloscopia.","C":"Finalização das doses de poliquimioterapia.","D":"Biópsia de pele sem características de hanseníase."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334098","number":"334098","sourceNumber":"334098","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em casos com resultados parasitológicos e sorológicos de leishmania negativos ou\ninconclusivos:","options":{"A":"É possível realizar, em laboratórios de referência, o diagnóstico molecular utilizando DNA\nextraído de fragmento de pele, mucosa, sangue\nperiférico, medula óssea ou órgãos do sistema\nfagocítico-mononuclear.","B":"Não é possível realizar, em laboratórios de referência, o diagnóstico molecular utilizando DNA\nextraído de fragmento de pele, mucosa, sangue periférico, medula óssea ou órgãos do sistema\nfagocítico-mononuclear.","C":"É possível realizar, em laboratórios de referência, o diagnóstico molecular utilizando DNA\nextraído de fragmento de pele, mucosa, sangue periférico, medula óssea, mas não do sistema\nfagocítico-mononuclear.","D":"É possível realizar, em laboratórios de referência, o diagnóstico molecular utilizando DNA\nextraído de fragmento de pele, mucosa, não do sangue periférico, medula óssea ou órgãos do\nsistema fagocítico-mononuclear."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-331965","number":"331965","sourceNumber":"331965","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mulher, 62 anos, comparece a consulta médica com queixa de eritema, lesões\nvesicadas e muito prurido nos membros\ninferiores há duas semanas. Nega febre ou queda do\nestado geral. Antecedentes pessoais: diabetes há 25 anos. Exame físico: peso 85 kg, altura 1,55 m,\nedema de membros inferiores 2+/4+, presença de varizes tronculares, eritema difuso, descamação\ne vesículas agrupadas nos 2/3 distais do membro inferior direito, sem calor local. A hipótese\ndiagnóstica e a conduta adequada são:","options":{"A":"Erisipela - antibioticoterapia oral.","B":"Eczema de estase - corticoterapia tópica e compressas secativas.","C":"Insuficiência venosa crônica - compressão elástica e medicações venoativas.","D":"Linfedema - associar diurético de alça."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334101","number":"334101","sourceNumber":"334101","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Existem vários métodos empregados na identificação especifica de Leishmania, sendo\ncorreto que:","options":{"A":"A eletroforese de enzimas e o perfil de reatividade com anticorpos monoclonais encontram-se\npior padronizados.","B":"A eletroforese de enzimas e o perfil de reatividade com anticorpos monoclonais encontram-se\nmais bem padronizados.","C":"A eletroforese de enzimas e não o perfil de reatividade com anticorpos monoclonais encontra-se\nmais bem padronizados.","D":"A eletroforese de enzimas e o perfil de reatividade com anticorpos não monoclonais\nencontram-se mais bem padronizados."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-337411","number":"337411","sourceNumber":"337411","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"São diagnósticos diferenciais possíveis para urticária todos os abaixo, exceto.","options":{"A":"Porfiria aguda.","B":"Lúpus eritematoso sistêmico.","C":"Linfomas e leucemias.","D":"Mastocitose."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-337418","number":"337418","sourceNumber":"337418","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a afirmativa em que os critérios para anafilaxia foram preenchidos:","options":{"A":"Criança de 6 meses ingeriu pela primeira vez fórmula de leite de vaca e apresentou urticária com\nangioedema em lábios e orelha.","B":"Lactente que recebeu uma ferroada de abelha apresenta urticária e edema localizados ao redor\nda picada na coxa e com dor abdominal e\nvômitos.","C":"Adolescente alérgico a amendoim ingeriu alimento em festa de aniversário e apresentou urticária\nem face.","D":"Lactente sibilante de 8 meses com febre, recebendo inalações com beta 2 agonista há 3 dias\napresentou urticária após receber dipirona."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-346435","number":"346435","sourceNumber":"346435","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Criança de 10 anos, apresentou quadro de prurido difuso, edema em face, dispnéia,\nnáuseas e vômitos, 20 minutos após ingerir camarão. Chega ao pronto socorro com FC 135bpm,\nPA 85x47mmHg, FR 40ipm e saturação de 90% em ar ambiente. Além de oxigenação,\n\nanti-histamínico e expansão volêmica, qual a conduta mais adequada?","options":{"A":"Adrenalina, Corticoterapia, elevar os membros inferiores;","B":"Corticoterapia, elevar os membros inferiores;","C":"Adrenalina, elevar os membros inferiores;","D":"Adrenalina, Corticoterapia."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334803","number":"334803","sourceNumber":"334803","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O Molusco contagioso em crianças é uma infecção viral causada por um:","options":{"A":"Herpesvirus.","B":"Poxvírus.","C":"Vírus varicela-zóster.","D":"Papilomavírus."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-334135","number":"334135","sourceNumber":"334135","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente grande queimado, em 40° dia de internação em leito de terapia intensiva em\ncentro de queimados, apresentando lesão ulcerada em calcâneo direito, grande, com aspecto\nnecrótico em algumas áreas, sem melhora com as terapias tópicas prescritas. Em um\ndesbridamento foi realizado exame histopatológico que evidenciou carcinoma espinocelular. O\nprovável diagnóstico é:","options":{"A":"Úlcera de Marjolin.","B":"Úlcera de Cushing.","C":"Úlcera de Curling.","D":"Úlcera de Jhonson."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-342652","number":"342652","sourceNumber":"342652","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Um escolar de 8 anos, com placas eritematosas difusas, palidez e perda de consciência\npouco após mergulho em cachoeira, apresenta\nhistória prévia de placas eritematosas após banhos\nde mar que somem sem tratamento. Ao exame físico, está acordado, orientado e normotenso, com\nFC = 100bpm, FR = 26irpm, boa perfusão periférica, várias placas eritematosas em tronco, face e\nmembros bastante pruriginosas, sem edema. A conduta mais bem indicada, no momento, é:","options":{"A":"teste do gelo em contato com a pele por 4 minutos e observação após 10 minutos","B":"dosagem de crioproteínas, sendo sua ausência a característica desse diagnóstico","C":"adrenalina subcutânea imediatamente associada a anti-histamínico intravenoso","D":"15 dias de corticoide por via oral prescrito"},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-321602","number":"321602","sourceNumber":"321602","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A dermatite atópica é a dermatose mais frequente na infância e, nos lactentes, as\nlesões ocorrem mais comumente","options":{"A":"na face.","B":"nas pregas antecubitais.","C":"nas nádegas.","D":"no dorso das mãos e pés."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-321603","number":"321603","sourceNumber":"321603","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As lesões da dermatite atópica nas crianças maiores de 10 anos de idade ocorrem mais\nfrequentemente nas","options":{"A":"pregas antecubitais e poplíteas.","B":"pregas flexoras dos braços, do pescoço e das pernas.","C":"nádegas.","D":"áreas de contato com roupas de vestir."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-315780","number":"315780","sourceNumber":"315780","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Assinale a alternativa correta sobre a dermatite atópica em crianças.","options":{"A":"A sensibilização não IgE mediada a alimentos e por alérgenos inaláveis do ambiente deve ser\nprocurada insistentemente.","B":"A IgE é responsável só em parte pela doença.","C":"O defeito de barreira cutânea é de mecanismo imunológico.","D":"O ceratocone e a catarata são complicações."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-300838","number":"300838","sourceNumber":"300838","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A circulação cutânea é rica e a demanda metabólica da pele e dos seus elementos é\nbaixa, necessitando apenas de uma pequena fração do potencial possível da circulação cutânea\npara manter sua viabilidade. Quanto à vascularização, a pele cuja irrigação é feita por artérias\ncutâneas diretas é:","options":{"A":"Pele acima dos músculos grande dorsal.","B":"Artérias septais entre os músculos delgados da perna.","C":"Retalho inguinal.","D":"Artérias septais entre os músculos delgados do antebraço."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-295388","number":"295388","sourceNumber":"295388","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Relacione as colunas, associando as formas clínicas da Hanseníase às suas\nrespectivas lesões. COLUNA I 1. Hanseníase\nindeterminada. 2. Hanseníase tuberculoide. 3.\nHanseníase borderline borderlaine. 4. Hanseníase virchoviana. COLUNA II ( ) Lesões em placas ou\nanulares com bordas papulosas, eritematosas ou hipocrômicas. ( ) Máculas hipocrômicas com\ndiminuição da sudorese e alteração da sensibilidade. ( ) Pápulas, nódulos e infiltrações difusas com\ndistribuição simétrica. ( ) Placas e lesões foveolares com distribuição assimétrica. A sequência\ncorreta de associação da coluna II é:","options":{"A":"1, 2, 3, 4.","B":"2, 1, 4, 3.","C":"2, 3, 4, 1.","D":"4, 3, 1, 2."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317974","number":"317974","sourceNumber":"317974","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A psoríase é relativamente comum, acometendo qualquer faixa etária, sem distinções\nquanto ao gênero. Sobre o quadro clínico\ndessa doença, sabe-se que:","options":{"A":"a forma de apresentação vulgar (em placas) é a mais comum, ocorrendo em cerca de 90% dos\npacientes.","B":"as lesões costumam ocorrer de forma assimétrica, poupando regiões como palmas e plantas.","C":"o fenômeno isomórfico de Koebner é patognomônico dessa doença e se caracteriza pelo\nsurgimento de lesões em sítios de trauma.","D":"o sinal de Auspitz corresponde ao surgimento de escamas branco-prateadas por meio de\nraspagem das lesões."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-294301","number":"294301","sourceNumber":"294301","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O fator mais importante na avaliação histopatológica do melanoma é:","options":{"A":"Número de mitoses.","B":"Presença de regressão.","C":"Índice de Breslow.","D":"Localização da lesão."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-295389","number":"295389","sourceNumber":"295389","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No Estado Reacional da Hanseníase, a reação:","options":{"A":"tipo 2 ocorre em pacientes portadores da forma virchowiana e dimorfos virchowiano.","B":"tipo 1 ocorre na fase inicial da doença na forma indeterminada.","C":"tipo 1 ocorre em pacientes que não possuem nenhum grau de imunidade celular.","D":"tipo 2 caracteriza-se pela exacerbação das lesões preexistentes."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-317975","number":"317975","sourceNumber":"317975","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem de 45 anos encontra-se no terceiro mês de tratamento para hanseníase\nmultibacilar. Ao exame físico apresenta placas com alteração de sensibilidade, xerodermia e\npigmentação cutânea. Nesse caso, a xerodermia e a pigmentação cutânea são atribuídas ao\nmedicamento:","options":{"A":"Dapsona.","B":"Rifampicina.","C":"Clofazimina.","D":"Talidomida."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-308266","number":"308266","sourceNumber":"308266","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre Hanseníase, analise as afirmativas e considere a opção correta. ( ) O diagnóstico\né essencialmente clínico e epidemiológico,\nportanto, baciloscopia negativa não exclui o diagnóstico.\n( ) No exame físico devemos inspecionar toda a pele despida do paciente a fim de identificar lesões\nsuspeitas. Também no exame físico, é importante avaliar espessamento neural e sensibilidade da\nlesão. ( ) O tratamento deve ser suspenso sempre que houver reação hansênica naquela individuo\nem tratamento. ( ) As recomendações para ministrar a vacina BCG são: ministrar duas doses em\npacientes sem cicatriz vacinal; ministrar uma dose em pacientes com uma cicatriz vacinal; não\nministrar a vacina em caso de duas cicatrizes.","options":{"A":"VFFF.","B":"FVVF.","C":"VVFV.","D":"VVFF."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-316352","number":"316352","sourceNumber":"316352","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente, feminina, 12 anos de idade, vem à Clínica da Família Benjamin Spadoni,\nacompanhada pela mãe. Acompanhante refere erupção cutânea, há 4 dias, delimitada à região\nlombar à direita, inicialmente com máculas e pápulas, evoluindo para vesículas, associada a dor e\nprurido local, mal-estar e 01 episódio de febre aferida 37,9°C. Nega demais sintomas. Refere uso\nprévio de pomada de dexametasona, sem melhora dos sintomas. Refere contato com cachorro e\ngato de estimação. Cartão vacinal atualizado. Nega comorbidades, medicamentos de uso contínuo\ne alergias medicamentosas. Afirma história prévia de varicela, há 1 ano. Qual o melhor diagnóstico\ne conduta?","options":{"A":"Varicela, fazer analgesia.","B":"Herpes Zoster, fazer antiviral e analgesia.","C":"Herpes Zoster, encaminhar para especialista focal.","D":"Escabiose, prescrever ivermectina."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-311960","number":"311960","sourceNumber":"311960","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Com relação aos cânceres de pele, assinale a alternativa correta:","options":{"A":"O carcinoma espinocelular é o tumor maligno mais frequente na pele.","B":"O lentigo maligno melanoma é o tipo mais comum dos melanomas malignos.","C":"Um método importante para auxílio diagnóstico dos melanomas é a regra do ABCDE, sendo que\na letra \"\"D\"\" significa diâmetro da lesão\ngeralmente maior que 1cm.","D":"Pacientes com carcinoma basocelular apresentam risco aumentado para o desenvolvimento de\nmelanoma."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-258164","number":"258164","sourceNumber":"258164","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Na hiperidrose palmar primária:","options":{"A":"o diagnóstico pode ser confirmado pela presença do TSH elevado (hipotireoidismo subclínico)\nque acompanha o quadro clínico.","B":"a síndrome de Horner é a complicação mais frequente após a simpatectomia por\nvideotoracoscopia.","C":"a cirurgia somente deve ser indicada após avaliação multidisciplinar, com a comprovação do\nprofissional de psicologia de que há efetivo dano emocional associado ao quadro clínico.","D":"a simpatectomia videotoracoscópica, realizada em nível da terceira e quarta vértebras torácicas\n(T3-T4), é o tratamento definitivo de\nescolha."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-281977","number":"281977","sourceNumber":"281977","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Considerando paciente de 30 anos, com diagnóstico de melanoma medindo 1,0 cm no\nmaior diâmetro já submetido à biópsia excisional, cujo laudo anatomopatológico revelou neoplasia\nulcerada, ressecada com margens livres (distando 5 mm da margem cirúrgica mais próxima), com\níndice mitótico de 4/mm², espessura de Breslow 0,9 mm, é correto afirmar:","options":{"A":"Considerando melanoma ulcerado, recomenda-se tratamento adjuvante com radioterapia.","B":"O tratamento adequado inclui a biópsia de linfonodo sentinela e ampliação de margens de\nsegurança com 1,0 cm de cada lado da cicatriz.","C":"Tendo em vista de que se trata de melanoma Breslow menor de 1,0 mm ressecado com\nmargens livres, está indicado apenas controle\nclínico de 6 em 6 meses por 2 anos e anual a seguir.","D":"Em virtude de ressecção com margens livres, está indicada a biópsia de linfonodo sentinela."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-281274","number":"281274","sourceNumber":"281274","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre a Candidíase Cutânea Congênita, assinale a alternativa correta.","options":{"A":"Manifesta-se dentro dos primeiros três meses de vida e é uma infecção fúngica invasiva da\nderme.","B":"Apresenta-se com erupção maculopapular extensa e pode ser fatal principalmente nos\nrecém-nascidos de termo grandes para a idade gestacional.","C":"Manifesta-se dentro dos primeiros dias de vida, com necrose da epiderme.","D":"Sem o tratamento sistêmico imediato há risco de disseminação em populações vulneráveis."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-277420","number":"277420","sourceNumber":"277420","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"O lentigo maligno é lesão precursora de uma das seguintes patologias:","options":{"A":"nevus melanocítico","B":"carcinoma basocelular","C":"melanoma maligno","D":"doença de Bowen"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-273175","number":"273175","sourceNumber":"273175","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Neoplasia é o crescimento anormal de células em qualquer tecido corpóreo do\nhospedeiro. Câncer é a neoplasia com potencial de malignidade cujas características são,\nEXCETO:","options":{"A":"Baixa diferenciação.","B":"Baixo potencial de invasão.","C":"Grande capacidade metastática.","D":"Crescimento acelerado."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-257755","number":"257755","sourceNumber":"257755","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Homem branco, de 63 anos, relata surgimento de lesão no sulco nasogeniano há dois\nanos, indolor e sangrante aos mínimos traumas. O médico assistente descreveu a lesão como\nsendo uma pápula de aspecto perolado com telangiectasias na superfície, sendo que o exame\nanatomopatológico identificou células tumorais basaloides com núcleos periféricos em paliçada.\n\nNesse caso, o diagnóstico do paciente é:","options":{"A":"ceratoacantoma.","B":"carcinoma basocelular variante papulonodular.","C":"melanoma amelanótico.","D":"carcinoma espinocelular."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-258205","number":"258205","sourceNumber":"258205","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 18 anos, solteira, portadora de acne Grau III ou acne\npápulo-pustulosa moderada, já com cicatrizes e manchas hipercrômicas residuais, procura o\nServiço de Dermatologia do Hospital das Clínicas de Goiânia para tratamento. Em relação ao\ntratamento, sabe-se que:","options":{"A":"paciente já apresenta cicatrizes, portanto não precisamos mais tratar a acne, somente as\nmanchas residuais com clareadores e fazer\nprocedimentos cosmiátricos para as cicatrizes.","B":"caso seja indicado algum tratamento para acne não pode ser a isotretinoína oral, pois a paciente\ntem 18 anos, está em idade fértil e a\nmedicação é teratogênica.","C":"o tópico com retinoides, sabonete, filtro solar é o mais indicado e iniciar tratamento para as\nmanchas e cicatrizes concomitante com a da\nacne.","D":"por ser acne Grau III, já preconiza-se tratamento oral com antibióticos ou isotretinoína; se\noptar-se por este último, solicitar exames de\nfunção hepática, lipidograma e Beta HCG antes de\niniciar a terapia."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-257756","number":"257756","sourceNumber":"257756","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"No uso da isotretinoína para o tratamento de acne,","options":{"A":"esse medicamento é mais bem absorvido pelo trato gastrointestinal quando ingerido com\nrefeição gordurosa, sendo seu uso proibido em\nmenores de 16 anos pelo risco de hepatotoxicidade.","B":"o uso concomitante de penicilinas aumenta o risco de desenvolvimento de hipertensão\nintracraniana benigna, ou pseudotumor cerebral, se\napresentando clinicamente com náuseas,\nvômitos e visão turva.","C":"esse fármaco tem indicação nas formas graves da doença e nas formas resistentes ou\nrecorrentes aos tratamentos habituais ou\nnaqueles pacientes muito afetados psicologicamente.","D":"em alguns pacientes pode ocorrer o agravamento (flare-up) da acne no final da terapia, sendo\ncontraindicado o uso de corticoterapia sistêmica nesses casos."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-258206","number":"258206","sourceNumber":"258206","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Paciente grávida (idade gestacional = 18 semanas), apresenta lesões\n\npápulo-escoriadas com prurido importante principalmente noturno. Mora com o marido e mais\nquatro filhos na mesma casa. O marido e dois\nde seus filhos também apresentam sintomas\nsemelhantes. Fez uso de plantas caseiras indicado por uma vizinha com piora do quadro clínico,\nevoluindo com várias lesões eritematosas pelo corpo. Nesse caso, deve-se considerar ainda:","options":{"A":"as prováveis hipóteses diagnósticas são escabiose na paciente, no marido e nos dois filhos e\neczema de contato somente na paciente.","B":"o tratamento da escabiose pode ser feito com ivermectina e/ou permetrina naqueles que\napresentaram os sintomas. Nos dois outros\nfilhos que não manifestaram a doença, é desnecessário\nqualquer tratamento.","C":"a paciente em questão não deve fazer nenhum tratamento porque está grávida, deve usar\napenas pasta d'água manipulada para aliviar o prurido.","D":"o tratamento do eczema da paciente deve ser anti-histamínico oral (qualquer classe, sedante ou\nnão sedante), retirar a causa do contato e\ncorticoide apenas tópico, já que corticoide oral a paciente\nnão poderá fazer uso por estar grávida."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-274512","number":"274512","sourceNumber":"274512","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A dermatite de fraldas é a forma mais frequente de dermatite de contato por irritante\nprimário na criança. Estima-se que até os 2\nanos de vida 25% das crianças apresentarão esta\ndermatose. Analise as afirmativas abaixo. I. A lesão cutânea na dermatite de fraldas é determinada\npor processo inflamatório na pele coberta pela fralda e resulta da interação de múltiplos fatores\ncomo: o aumento da umidade, pH elevado, enzimas fecais e micro-organismos que se\ndesenvolvem pela condição ideal proporcionada pela oclusão. II. A irritação pela limpeza e\nprincipalmente pela utilização de lenços úmidos contendo álcool ou sabões com pH alcalino irão\nquebrar a função de barreira cutânea o que permite que a lesão se estabeleça. III. As lesões são\ncaracterizadas por eritema que poupa as pregas, e acomete as áreas que estão em contato com as\nsubstâncias que promovem o dano à pele da região, dando uma configuração clínica que lembra a\nletra \"W\". A manifestação clínica pode ser leve, moderada e grave. IV. O tratamento deve ser feito\ncom a troca de fraldas com maior frequência que a habitual, limpeza suave da região, exposição da\npele ao ar e aplicação de cremes de barreira. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"I,II e III.","D":"I,II,III e IV."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-257781","number":"257781","sourceNumber":"257781","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"A larva migrans cutânea, ou bicho-geográfico acomete muitas crianças e tem como\ncaracterística:","options":{"A":"é causada pelas larvas do Necator Americanus.","B":"a contaminação ocorre pela ingestão de alimentos mal lavados.","C":"as lesões são encontradas em qualquer área do corpo.","D":"é uma patologia com lesão na pele, sem prurido."},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-274821","number":"274821","sourceNumber":"274821","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Pré escolar de 5 anos de idade, com queixa de aparecimento de lesões pelo corpo e\nprurido intenso, prejudicando sono há cerca de 8 dias. Nega febre ou outros sintomas. Frequenta\ncreche. Ao exame: lesões por todo corpo acometendo couro cabeludo, punhos, espaços\ninterdigitais, palma da mão, planta dos pés, axilas e virilha. Com presença de pápulas, vesículas,\ncrostas e nódulos vermelhos acastanhados, além de lesões por escoriações. Assinale o diagnóstico\nmais provável e tratamento, respectivamente.","options":{"A":"Dermatite atópica. Corticoide tópico e hidratante.","B":"Escabiose. Permetrina loção.","C":"Varicela. Analgésicos e loção calmante.","D":"Picada de inseto. Anti-histamínico oral e corticoide tópico."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-257782","number":"257782","sourceNumber":"257782","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"As infecções fúngicas superficiais acometem frequentemente as crianças. Dentre elas,\na tinea cruris","options":{"A":"acomete principalmente a população adolescente.","B":"ocorre mais comumente nas regiões interdigitais.","C":"tem um maior tropismo pelas crianças do sexo feminino.","D":"necessita de tratamento tópico e sistêmico para sua completa resolução."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-282042","number":"282042","sourceNumber":"282042","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Em relação ao uso de epinefrina, assinale a alternativa correta:","options":{"A":"Deve ser feito intramuscular no deltoide em casos de choque anafilático.","B":"Não está indicado em casos graves de supraglotite aguda.","C":"Não é recomendado uso via traqueal em nenhuma situação.","D":"Não deve ser aplicado em região subcutânea em casos de parada cardiorrespiratória."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-282046","number":"282046","sourceNumber":"282046","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Uma menina de 24 meses apresenta lesões papulares e pruriginosas com distribuição\nlinear e aos pares em região de antebraços,\nface e pernas. As lesões evoluem para formação de\ncrostas hemáticas e hipercromia residual. Com bases nesses dados, assinale a alternativa\nincorreta:","options":{"A":"O provável agente é o Sarcoptes scabei e está indicado para tratamento loção de permetrina a\n5%.","B":"Está indicado a utilização de barreiras físicas para proteção dessa criança.","C":"Repelentes infantis a base de icaridina em concentração de 20% são autorizados nesta faixa\netária.","D":"O uso de corticoide tópico de alta potencia não está indicado neste tipo de lesão."},"answer":"A","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-274828","number":"274828","sourceNumber":"274828","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Adolescente de 13 anos é levada ao pronto-socorro com história de que há 1 hora\ningeriu crustáceos, evoluiu com quadro de\nanafilaxia. Recebeu 2 doses de adrenalina na diluição\nde (1:1000) 0,4 mg IM. Permaneceu deitada, com membros inferiores elevados, manteve\nestabilidade hemodinâmica, sem sinais de choque. Após 12 horas de observação clínica recebeu\nalta com a orientação de qual medicação:","options":{"A":"Prednisona + Ranitidina.","B":"Dexametasona + Prometazina.","C":"Dexametasona + Dexclorfeniramina.","D":"Prednisolona + Cetirizina."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-282053","number":"282053","sourceNumber":"282053","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Mãe afirma que lactente de 11 meses apresenta lesões de pele recorrentes desde os\nquatro meses de vida. As lesões são escamosas e crostosas de distribuição periférica na face,\nregiões antecubitais e poplíteas. A mãe nega casos semelhantes na família e refere apresentar\nasma controlada. A melhor conduta neste caso seria:","options":{"A":"Prescrever anti-histamínicos via oral, corticosteroide via oral e banhos com loção capilar\nantifúngica.","B":"Prescrever anti-histamínicos via oral, corticosteroide via oral e antibióticos tópicos.","C":"Prescrever antibióticos via oral e corticoide tópico.","D":"Prescrever anti-histamínico via oral e corticoide tópico."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-231932","number":"231932","sourceNumber":"231932","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"Sobre o melanoma cutâneo, assinale a alternativa incorreta:","options":{"A":"a regra do ABCDE do melanoma considera os seguintes fatores para diagnóstico das lesões\nsuspeitas: assimetria, bordas, coloração, diâmetro acima de 6mm e extensaão em superfície ou\nmodificação do aspecto da lesão","B":"a síndrome do nevo displásico representa um fator de risco para melanoma","C":"o melanoma lentiginoso-acral é a forma de melanoma mais comum em indivíduos de pele clara","D":"o índice de Breslow é um importante marcador de sobrevida no melanoma cutâneo","E":"a predisposição genética está entre os principais fatores etiológicos"},"answer":"C","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-254225","number":"254225","sourceNumber":"254225","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"\"A Previdência Social paga cerca de 7,3 milhões de reais de pensão mensal para\npessoas que tiveram hanseníase. segundo\ndados do órgão, 5.715 pessoas recebem o benefício.\"\n(REVISTA EXAME, 08 de outubro de 2018). A respeito da hanseníase, é CORRETO afirmar:","options":{"A":"O quadro clínico de manchas hipopigmentadas e hipossensíveis é típico dos doentes\nmultibacilares.","B":"Pacientes que desenvolvem uma resposta imune padrão Th2 tendem a desenvolver a forma\nvirchowiana da doença.","C":"O teste de Mitsuda é um ótimo teste diagnóstico da doença.","D":"Paciente portador da forma tuberculoide é o que mais transmite o bacilo por secreções orais e\nnasais."},"answer":"B","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-dermatologia-der-unico-254231","number":"254231","sourceNumber":"254231","collectionBlock":"medcurso:medcurso-dermatologia-der-unico","collectionLabel":"Medcurso · DER UNICO","documentBlock":"","area":"Dermatologia","specialty":"Dermatologia","topic":"DER UNICO","subtopic":"","stem":"RN com 21 dias de vida apresentando em região glútea e genital pápulas que confluem\nem placas, pústulas, lesões satélites e\nalgumas pústulas rompidas de base eritematosa. Qual o\ndiagnóstico?","options":{"A":"Impetigo.","B":"Tinha crural.","C":"Dermatite atópica.","D":"Candidose cutânea."},"answer":"D","source":"Dermatologia/DER UNICO.txt","sourceLabel":"Medcurso · DER UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Dermatologia","DER UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
